;
// ---- employee-picker.js ----
// Searchable employee picker
// ---------------------------------------------------------------------------
// Turns a plain <select> full of employees into a searchable picker.
// Institutions can have 100+ employees, and every existing <select id="...">
// that lists them (Start Onboarding, Reports To, Approval Workflow's
// specific-employee step, L&D enrollment, Apply Leave on behalf of,
// Total Rewards, User Management's linked employee) forced scrolling
// through the whole roster to find one person.
//
// The <select> stays the real source of truth — same id, same .value, same
// onchange="..." attribute — this just hides it and layers a text input +
// filtered dropdown panel on top, reading directly from whatever <option>s
// are already sitting in the <select> at call time. That means:
//   - No changes needed to how any call site builds its options (some use
//     createElement/appendChild loops, some use innerHTML/map/join — both
//     keep working exactly as before).
//   - Pinned non-employee options (e.g. fReportsTo's "None (Top Level)" /
//     "⭐ Self (CEO / Top of Org)") just work — they're options too,
//     matched by their own label text like anyone else.
//   - Zero changes needed at any submit-time document.getElementById(id).value
//     read, anywhere — picking a result dispatches a real 'change' event on
//     the underlying <select>, so every existing onchange handler still fires.
//
// Call ONCE, right after a <select>'s options finish being (re)populated —
// idempotent, so it's safe to call unconditionally every time a modal opens
// or a page reloads its options, not just the first time.
// ---------------------------------------------------------------------------

function filterEmployeeOptions(options, query) {
  // options: array of {value, label}. Pure so it's unit-testable without a DOM.
  // Deliberately does NOT exclude blank-value options — some call sites
  // (e.g. fReportsTo) have a meaningful choice living at value="" (its
  // "None (Top Level)" option), indistinguishable from a plain "please
  // select…" placeholder by value alone. Showing every option (including
  // a placeholder row) when the query is empty is a minor, harmless
  // redundancy; correctly keeping "None (Top Level)" reachable by typing
  // "none" is worth that trade-off.
  const q = (query || '').trim().toLowerCase();
  return options.filter(o => o.label.toLowerCase().includes(q));
}

function initEmployeeSearchSelect(selectId, placeholder) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const inputClass = sel.className.split(/\s+/).filter(c => c && c !== 'hidden').join(' ');

  let wrap = document.getElementById(selectId + 'SearchWrap');
  if (!wrap) {
    // Visually hidden but NOT display:none — a couple of these <select>s
    // (e.g. approval-workflow.js's "specific employee" step picker) have
    // their own external code toggling the *select's own* 'hidden' class
    // to show/hide the whole field. Using inline styles here (instead of
    // also touching the 'hidden' class) leaves that class free for such
    // external toggling to keep working unmodified — a MutationObserver
    // below mirrors whatever it does onto the wrap.
    Object.assign(sel.style, { position: 'absolute', opacity: '0', width: '0', height: '0', overflow: 'hidden', pointerEvents: 'none' });
    wrap = document.createElement('div');
    wrap.id = selectId + 'SearchWrap';
    wrap.className = 'relative' + (sel.classList.contains('hidden') ? ' hidden' : '');
    sel.insertAdjacentElement('afterend', wrap);
    new MutationObserver(() => {
      wrap.classList.toggle('hidden', sel.classList.contains('hidden'));
    }).observe(sel, { attributes: true, attributeFilter: ['class'] });
    wrap.innerHTML = `
      <input type="text" id="${selectId}Search" class="${esc(inputClass)}" placeholder="${esc(placeholder || 'Search…')}" autocomplete="off"/>
      <div id="${selectId}Dropdown" class="hidden absolute z-20 mt-1 w-full max-h-60 overflow-y-auto bg-white border border-slate-200 rounded-lg shadow-lg"></div>
    `;
    const input = wrap.querySelector('input');
    const dropdown = wrap.querySelector('div');

    const render = (query) => {
      const options = [...sel.options].map(o => ({ value: o.value, label: o.textContent }));
      const rows = filterEmployeeOptions(options, query);
      dropdown.innerHTML = rows.length
        ? rows.map(o => `<div class="px-3 py-2 text-sm hover:bg-slate-50 cursor-pointer" data-v="${esc(o.value)}">${esc(o.label)}</div>`).join('')
        : `<div class="px-3 py-2 text-sm text-slate-400">No matches</div>`;
    };
    const pick = (value) => {
      const opt = [...sel.options].find(o => o.value === value);
      sel.value = value;
      input.value = opt ? opt.textContent : '';
      dropdown.classList.add('hidden');
      sel.dispatchEvent(new Event('change'));
    };

    input.addEventListener('input', () => { render(input.value); dropdown.classList.remove('hidden'); });
    // select() on focus: whatever's currently shown (a placeholder like
    // "Select employee…", or a previously-picked name) is fully selected,
    // so the user's first keystroke cleanly replaces it rather than
    // requiring a manual clear first — standard combobox behavior. Render
    // against an EMPTY query, not that pre-existing text — it's about to
    // be replaced, not a search the user actually typed, so filtering by
    // it (e.g. against the literal placeholder "Select employee…") would
    // wrongly show "No matches" the moment the field is focused.
    input.addEventListener('focus', () => { input.select(); render(''); dropdown.classList.remove('hidden'); });
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') { dropdown.classList.add('hidden'); input.blur(); }
      if (e.key === 'Enter') {
        e.preventDefault();
        const first = dropdown.querySelector('[data-v]');
        if (first) pick(first.dataset.v);
      }
    });
    // mousedown (not click) fires before the input's blur event would
    // otherwise hide the dropdown first and swallow the click.
    dropdown.addEventListener('mousedown', (e) => {
      const row = e.target.closest('[data-v]');
      if (row) pick(row.dataset.v);
    });
    document.addEventListener('click', (e) => {
      if (!wrap.contains(e.target)) dropdown.classList.add('hidden');
    });
  }

  // Re-sync the visible text with whatever is actually selected — needed
  // both on first render and whenever a call site repopulates the
  // underlying <select>'s options (e.g. a modal reopened for a new record).
  // selectedIndex (not a value-truthiness check) so a legitimately
  // blank-valued option that's actually selected — e.g. fReportsTo's
  // "None (Top Level)", value="" — still displays its own label, distinct
  // from "nothing chosen yet" on a picker whose placeholder is also "".
  const input = wrap.querySelector('input');
  const current = sel.options[sel.selectedIndex];
  input.value = current ? current.textContent : '';
}

;
// ---- dashboard.js ----
// Dashboard
// ---------------------------------------------------------------------------
// Tabs load lazily (dash-tabs.js loaded flag) — everything past General/
// Workforce used to fire its own API call in parallel on every single
// dashboard visit regardless of which section (if any) the user actually
// looked at. For an HR manager that's 4+ concurrent DB round-trips just to
// land on the page. Now only General (notifications/To-Do) and Workforce
// (which includes Locations Overview) fetch up front, since both are
// reachable with a single click from landing; Recruitment/Timesheet/
// Compensation & Benefits fetch once, on first click, and are cached for
// the rest of the session.
const _dashTabLoaded = { recruitment: false, timesheet: false, compensation: false, leave: false };
let _lastBenefitsDashboard = null;
window.getLastBenefitsDashboard = () => _lastBenefitsDashboard;

function switchDashTab(tabId) {
  document.querySelectorAll('.dash-tab-panel').forEach(el => el.classList.toggle('hidden', el.id !== tabId));
  document.querySelectorAll('[data-dashtab]').forEach(btn => {
    btn.classList.toggle('pill-tab-active', btn.dataset.dashtab === tabId);
  });
  if (tabId === 'dash-recruitment' && !_dashTabLoaded.recruitment) { _dashTabLoaded.recruitment = true; loadRecruitmentDash(); }
  if (tabId === 'dash-timesheet' && !_dashTabLoaded.timesheet) { _dashTabLoaded.timesheet = true; loadTimesheetDash(); }
  if (tabId === 'dash-compensation' && !_dashTabLoaded.compensation) { _dashTabLoaded.compensation = true; loadCompensationDash(); }
  if (tabId === 'dash-leave' && !_dashTabLoaded.leave) { _dashTabLoaded.leave = true; loadLeaveDash(); }
}

function renderDashboard() {
  checkDashboardSystemNotification();
  checkDashboardNotification();
  loadDashboardTodos();
  const isEmployee = currentUser?.role === 'employee';
  document.getElementById('dashboardQuickActions')?.classList.toggle('hidden', !isEmployee);
  document.getElementById('dashboardResignRow')?.classList.toggle('hidden', !isEmployee);
  if (isEmployee) { refreshResignButtonState(); refreshDashClockState(); }
  renderDashGreeting();
  if (currentUser.role === 'superadmin' && !currentInstitution) {
    document.getElementById('superadminGlobalDash').classList.remove('hidden');
    document.getElementById('instDash').classList.add('hidden');
    document.getElementById('gStatInst').textContent = institutions.length;
    document.getElementById('gStatEmp').textContent = institutions.reduce((a,i)=>a+i.employee_count,0);
    document.getElementById('gStatUser').textContent = institutions.reduce((a,i)=>a+i.user_count,0);
    document.getElementById('gInstList').innerHTML = institutions.map(i=>`
      <div class="flex items-center justify-between py-2.5 border-b border-slate-100 last:border-0">
        <div class="flex items-center gap-3">
          <span class="badge ${i.status==='Active'?'status-positive':'status-negative'}">${i.status}</span>
          <div>
            <p class="text-sm font-medium">${esc(i.name)}</p>
            <p class="text-xs text-slate-400">${esc(i.code)} · ${i.employee_count} employees</p>
          </div>
        </div>
        <button onclick="enterInstitutionContext(this.dataset.inst)" data-inst='${JSON.stringify(i).replace(/'/g,"&apos;")}' class="btn-primary" style="font-size:.75rem;padding:.25rem .75rem">Manage</button>
      </div>
    `).join('') || '<p class="text-slate-400 text-sm">No institutions.</p>';
    return;
  }
  document.getElementById('superadminGlobalDash').classList.add('hidden');
  document.getElementById('instDash').classList.remove('hidden');
  document.getElementById('dashKpiRow')?.classList.remove('hidden');
  loadDashboardKpis();
  loadWorkforceStats();

  // Locations overview (Workforce tab, HR Manager / HR Admin only) — the one
  // section besides base stats that still fetches immediately, since it's
  // grouped into the always-visible Workforce tab rather than a lazy tab.
  const canViewLoc = HR_STAFF_ROLES.includes(currentUser?.role);
  document.getElementById('locDashSection').classList.toggle('hidden', !canViewLoc);
  if (canViewLoc) loadLocationsOverviewDash();

  // Reset per-tab load-once flags and gate tab button visibility for this
  // user/institution context, then always land back on General.
  _dashTabLoaded.recruitment = false;
  _dashTabLoaded.timesheet = false;
  _dashTabLoaded.compensation = false;
  _dashTabLoaded.leave = false;
  const canRecruit = HR_AND_MANAGER_ROLES.includes(currentUser?.role);
  const canViewUtil = HR_MANAGER_ONLY_ROLES.includes(currentUser?.role);
  const canViewBenefitsDash = BENEFITS_DASHBOARD_ROLES.includes(currentUser?.role);
  const hasEmployeeRecord = !!currentUser?.employee_id;
  const canViewLeaveDash = HR_STAFF_ROLES.includes(currentUser?.role);
  document.getElementById('dash-tab-recruitment-btn').classList.toggle('hidden', !canRecruit);
  document.getElementById('dash-tab-timesheet-btn').classList.toggle('hidden', !canViewUtil);
  document.getElementById('dash-tab-compensation-btn').classList.toggle('hidden', !(canViewBenefitsDash || hasEmployeeRecord));
  document.getElementById('dash-tab-leave-btn').classList.toggle('hidden', !(canViewLeaveDash || hasEmployeeRecord));
  switchDashTab('dash-general');
}

// Home KPI Headcount tile + the whole Workforce tab (Total/Active/
// Inactive/Depts, Nationality/Race composition, Department/Employment
// Type breakdown). Backed by GET /api/employees/workforce-stats —
// aggregate counts only, deliberately NOT the role-scoped `employees[]`
// array (list_employees restricts "employee" to their own record and
// "manager" to their reporting chain, to protect individual PII) — every
// role sees the same institution-wide totals here, since a count is never
// an individual record. Independent of loadDashboardKpis' other tiles
// and fails soft (leaves everything at its default "—"/0) rather than
// blocking the rest of the dashboard.
async function loadWorkforceStats() {
  const res = await api('/api/employees/workforce-stats');
  if (!res?.ok) return;
  const s = await res.json();

  const headcountEl = document.getElementById('kpiHeadcount');
  if (headcountEl) headcountEl.textContent = s.active;

  const total = s.total || 1;
  document.getElementById('statTotal').textContent = s.total;
  document.getElementById('statActive').textContent = s.active;
  document.getElementById('statInactive').textContent = s.inactive;
  document.getElementById('statDepts').textContent = s.departments;
  const genderLabel = g => (g.Male || g.Female) ? `${g.Male || 0} Male · ${g.Female || 0} Female` : '—';
  document.getElementById('statTotalGender').textContent = genderLabel(s.total_gender);
  document.getElementById('statActiveGender').textContent = genderLabel(s.active_gender);
  document.getElementById('statInactiveGender').textContent = genderLabel(s.inactive_gender);
  document.getElementById('statActivePct').textContent = `${Math.round(s.active/total*100)}%`;
  document.getElementById('statInactivePct').textContent = `${Math.round(s.inactive/total*100)}%`;

  const breakdownBar = (containerId, counts, barColor) => {
    const entries = Object.entries(counts).sort((a,b)=>b[1]-a[1]);
    document.getElementById(containerId).innerHTML = entries.map(([label,c])=>`
      <div class="flex items-center gap-2">
        <div class="w-28 text-xs text-slate-600 truncate">${esc(label)}</div>
        <div class="flex-1 bg-slate-100 rounded-full h-2">
          <div class="${barColor} h-2 rounded-full" style="width:${Math.round(c/total*100)}%"></div>
        </div>
        <div class="text-xs text-slate-500 w-5 text-right">${c}</div>
      </div>`).join('') || '<p class="text-slate-400 text-sm">No data.</p>';
  };
  breakdownBar('deptBreakdown', s.dept_breakdown, 'bg-blue-500');
  breakdownBar('empTypeBreakdown', s.employment_type_breakdown, 'bg-violet-500');

  // Workforce Composition — Nationality (Local/Foreigner) and Race, as
  // proportional segmented bars. Nationality is free text in this app (see
  // core/constants.py — there's no NATIONALITIES enum), so "Local" is a
  // nationality==='Malaysian' heuristic, not a validated field; anything
  // else (including typos/inconsistent entries) counts as "Foreigner" —
  // computed server-side now (see get_workforce_stats), same heuristic.
  // Race IS a validated, required 7-value enum (core/constants.py's
  // RACES) — every employee always has one, so there's no "Undefined"
  // bucket to design for, unlike a generic HR system might need.
  const segmentedBar = (containerId, legendId, segments) => {
    const shown = segments.filter(s => s.count > 0);
    document.getElementById(containerId).innerHTML = shown.map(s =>
      `<div class="${s.color}" style="width:${Math.round(s.count/total*100)}%" title="${esc(s.label)}: ${s.count}"></div>`
    ).join('');
    document.getElementById(legendId).innerHTML = shown.map(s =>
      `<span class="flex items-center gap-1"><span class="w-2 h-2 rounded-full ${s.color} inline-block"></span>${esc(s.label)} ${s.count}</span>`
    ).join('') || '<span class="text-slate-400">No data.</span>';
  };
  segmentedBar('nationalityBar', 'nationalityLegend', [
    { label:'Local', count:s.local_count, color:'bg-blue-700' },
    { label:'Foreigner', count:s.foreign_count, color:'bg-blue-300' },
  ]);
  const RACE_COLORS = {
    'Malay':'bg-blue-600', 'Chinese':'bg-emerald-500', 'Indian':'bg-amber-500',
    'Bumiputera Sabah':'bg-rose-500', 'Bumiputera Sarawak':'bg-violet-500',
    'Orang Asli':'bg-cyan-500', 'Others':'bg-slate-400',
  };
  segmentedBar('raceBar', 'raceLegend',
    Object.entries(s.race_breakdown).sort((a,b)=>b[1]-a[1])
      .map(([race,count])=>({ label:race, count, color:RACE_COLORS[race]||'bg-slate-400' })));
}

function loadLocationsOverviewDash() {
  api('/api/institutions/' + currentUser.institution_id + '/location-summary').then(async res => {
    if (!res || !res.ok) return;
    const s = await res.json();

    document.getElementById('locStatTotal').textContent = s.total_locations || 0;

    const avgUtil = s.locations && s.locations.length > 0
      ? Math.round(s.locations.reduce((sum, loc) => sum + (loc.utilization_percent || 0), 0) / s.locations.length)
      : 0;
    document.getElementById('locStatAvgUtil').textContent = avgUtil + '%';

    const totalEmpInLoc = s.locations ? s.locations.reduce((sum, loc) => sum + (loc.employee_count || 0), 0) : 0;
    document.getElementById('locStatEmpCount').textContent = totalEmpInLoc;

    const withManager = s.locations ? s.locations.filter(loc => loc.manager_user_id).length : 0;
    document.getElementById('locStatManaged').textContent = withManager;

    if (s.locations && s.locations.length > 0) {
      const maxEmps = Math.max(...s.locations.map(l => l.employee_count || 0)) || 1;
      document.getElementById('locEmpDistribution').innerHTML = s.locations
        .sort((a, b) => (b.employee_count || 0) - (a.employee_count || 0))
        .map(loc => `
          <div class="flex items-center gap-2">
            <div class="w-32 text-xs text-slate-600 truncate" title="${esc(loc.location_name)}">${esc(loc.location_name)}</div>
            <div class="flex-1 bg-slate-100 rounded-full h-2">
              <div class="bg-blue-500 h-2 rounded-full" style="width:${Math.round((loc.employee_count || 0)/maxEmps*100)}%"></div>
            </div>
            <div class="text-xs text-slate-500 w-6 text-right">${loc.employee_count || 0}</div>
          </div>
        `).join('');
    } else {
      document.getElementById('locEmpDistribution').innerHTML = '<p class="text-slate-400 text-sm">No locations yet.</p>';
    }

    if (s.locations && s.locations.length > 0) {
      const locWithCap = s.locations.filter(l => l.capacity && l.capacity > 0);
      if (locWithCap.length > 0) {
        document.getElementById('locCapacityChart').innerHTML = locWithCap
          .sort((a, b) => (b.utilization_percent || 0) - (a.utilization_percent || 0))
          .map(loc => {
            const util = loc.utilization_percent || 0;
            const color = util > 90 ? 'bg-red-500' : util > 70 ? 'bg-amber-500' : 'bg-emerald-500';
            return `
              <div class="flex items-center gap-2">
                <div class="w-32 text-xs text-slate-600 truncate" title="${esc(loc.location_name)}">${esc(loc.location_name)}</div>
                <div class="flex-1 bg-slate-100 rounded-full h-2">
                  <div class="${color} h-2 rounded-full" style="width:${util}%"></div>
                </div>
                <div class="text-xs text-slate-500 w-10 text-right">${util}%</div>
              </div>
            `;
          }).join('');
      } else {
        document.getElementById('locCapacityChart').innerHTML = '<p class="text-slate-400 text-sm">No capacity data.</p>';
      }
    } else {
      document.getElementById('locCapacityChart').innerHTML = '<p class="text-slate-400 text-sm">No locations yet.</p>';
    }
  });
}

function loadRecruitmentDash() {
  api('/api/recruitment/dashboard-stats').then(async res => {
    if (!res || !res.ok) return;
    const s = await res.json();
    document.getElementById('rStatOpenReq').textContent = (s.req_by_status['Approved'] || 0) + (s.req_by_status['Draft'] || 0);
    document.getElementById('rStatPendingApproval').textContent = s.pending_approvals ? `${s.pending_approvals} pending approval` : '';
    document.getElementById('rStatCands').textContent = s.total_candidates;
    document.getElementById('rStatHiredMonth').textContent = s.hired_this_month ? `${s.hired_this_month} hired this month` : '';
    document.getElementById('rStatUpcoming').textContent = s.upcoming_interviews;
    document.getElementById('rStatIntMonth').textContent = `${s.interviews_this_month} this month`;
    document.getElementById('rStatOffers').textContent = s.offers_pending;

    // Candidate pipeline bar chart
    const PIPELINE_STAGES = ['New','Screening','Interview','Pending Checks','Offer','Hired','Rejected by Candidate','Rejected by Company','Withdrawn'];
    const PIPELINE_COLORS = {New:'bg-slate-400',Screening:'bg-blue-400',Interview:'bg-purple-400','Pending Checks':'bg-orange-400',Offer:'bg-yellow-400',Hired:'bg-emerald-500','Rejected by Candidate':'bg-red-400','Rejected by Company':'bg-red-400',Withdrawn:'bg-slate-300'};
    const totalCands = s.total_candidates || 1;
    document.getElementById('rCandPipeline').innerHTML = s.total_candidates ? PIPELINE_STAGES.map(stage => {
      const cnt = s.cand_by_stage[stage] || 0;
      const avgSeconds = (s.avg_time_in_stage || {})[stage];
      return `<div class="flex items-center gap-2">
        <div class="w-20 text-xs text-slate-600">${stage}</div>
        <div class="flex-1 bg-slate-100 rounded-full h-2">
          <div class="${statusColor(PIPELINE_COLORS, stage, 'bg-slate-400')} h-2 rounded-full" style="width:${Math.round(cnt/totalCands*100)}%"></div>
        </div>
        <div class="text-xs text-slate-500 w-5 text-right">${cnt}</div>
        <div class="text-xs text-slate-400 w-16 text-right">avg ${fmtDuration(avgSeconds)}</div>
      </div>`;
    }).join('') : '<p class="text-slate-400 text-sm">No candidates yet.</p>';

    // Requisitions by status
    const REQ_COLORS = {Draft:'bg-slate-300','Pending Approval':'bg-amber-400',Approved:'bg-emerald-400',Rejected:'bg-red-400',Filled:'bg-blue-400',Closed:'bg-slate-200'};
    const totalReqs = s.total_requisitions || 1;
    document.getElementById('rReqStatus').innerHTML = Object.entries(s.req_by_status)
      .sort((a,b)=>b[1]-a[1]).map(([status,cnt])=>`
        <div class="flex items-center gap-2">
          <div class="w-28 text-xs text-slate-600 truncate">${status}</div>
          <div class="flex-1 bg-slate-100 rounded-full h-2">
            <div class="${statusColor(REQ_COLORS, status, 'bg-slate-400')} h-2 rounded-full" style="width:${Math.round(cnt/totalReqs*100)}%"></div>
          </div>
          <div class="text-xs text-slate-500 w-5 text-right">${cnt}</div>
        </div>`).join('') || '<p class="text-slate-400 text-sm">No requisitions yet.</p>';
  });
}

function loadTimesheetDash() {
  api('/api/projects/utilization').then(async res => {
    if (!res || !res.ok) return;
    const projects = await res.json();
    const listEl = document.getElementById('utilProjectList');
    const emptyEl = document.getElementById('utilEmpty');
    if (!projects.length) { listEl.innerHTML=''; emptyEl.classList.remove('hidden'); return; }
    emptyEl.classList.add('hidden');
    listEl.innerHTML = projects.map(p => {
      const taskRows = p.tasks.length ? p.tasks.map(t => {
        const pct = t.estimated_hours ? Math.min(100, Math.round(t.logged_hours / t.estimated_hours * 100)) : null;
        const over = t.estimated_hours && t.logged_hours > t.estimated_hours;
        return `<div class="flex items-center gap-2">
          <div class="w-40 text-xs text-slate-600 truncate" title="${esc(t.name)}">${esc(t.name)}</div>
          <div class="flex-1 bg-slate-100 rounded-full h-2">
            <div class="${over?'bg-red-500':'bg-blue-500'} h-2 rounded-full" style="width:${pct===null?(t.logged_hours>0?100:0):pct}%"></div>
          </div>
          <div class="text-xs ${over?'text-red-600 font-medium':'text-slate-500'} w-24 text-right">${t.logged_hours}${t.estimated_hours?` / ${t.estimated_hours}h`:'h'}</div>
        </div>`;
      }).join('') : '<p class="text-xs text-slate-400">No tasks defined yet.</p>';
      return `<div class="bg-white rounded-xl border border-slate-200 p-5">
        <div class="flex items-center justify-between mb-3">
          <h4 class="font-medium text-sm text-slate-800">${esc(p.name)}</h4>
          <span class="text-xs font-semibold text-slate-600">${p.total_hours}h total</span>
        </div>
        <div class="space-y-2">${taskRows}</div>
      </div>`;
    }).join('');
  });
}

function loadCompensationDash() {
  // Benefits cost & utilization — HR Manager / Compensation Manager / Manager
  const canViewBenefitsDash = BENEFITS_DASHBOARD_ROLES.includes(currentUser?.role);
  document.getElementById('benefitsDashSection')?.classList.toggle('hidden', !canViewBenefitsDash);
  if (canViewBenefitsDash) {
    api('/api/benefits/reports/dashboard').then(async res => {
      if (!res || !res.ok) return;
      const s = await res.json();
      _lastBenefitsDashboard = s;
      document.getElementById('bdActivePlans').textContent = s.total_active_plans;
      document.getElementById('bdEnrolledEmployees').textContent = s.total_enrolled_employees;
      document.getElementById('bdEmployerCost').textContent = fmtCurrency(s.total_monthly_employer_cost);
      document.getElementById('bdClaimsPaid').textContent = fmtCurrency(s.total_claims_paid_ytd);

      const deptEl = document.getElementById('bdDeptCostList');
      document.getElementById('bdDeptCostEmpty')?.classList.toggle('hidden', s.department_costs.length > 0);
      const maxDeptCost = Math.max(...s.department_costs.map(d => d.monthly_employer_cost_total), 1);
      deptEl.innerHTML = s.department_costs.map(d => `
        <div class="flex items-center gap-2">
          <div class="w-28 text-xs text-slate-600 truncate" title="${esc(d.department)}">${esc(d.department)}</div>
          <div class="flex-1 bg-slate-100 rounded-full h-2">
            <div class="bg-blue-500 h-2 rounded-full" style="width:${Math.round(d.monthly_employer_cost_total/maxDeptCost*100)}%"></div>
          </div>
          <div class="text-xs text-slate-500 w-20 text-right">${fmtCurrency(d.monthly_employer_cost_total)}</div>
        </div>`).join('');

      const planEl = document.getElementById('bdPlanUtilList');
      document.getElementById('bdPlanUtilEmpty')?.classList.toggle('hidden', s.plan_utilization.length > 0);
      planEl.innerHTML = s.plan_utilization.map(p => `
        <tr class="border-t border-slate-100">
          <td class="py-1.5 text-xs text-slate-600 truncate max-w-36" title="${esc(p.plan_name)}">${esc(p.plan_name)}</td>
          <td class="py-1.5 text-xs text-slate-700 text-right">${fmtCurrency(p.claims_claimed_ytd)}</td>
          <td class="py-1.5 text-xs text-slate-700 text-right">${fmtCurrency(p.claims_paid_ytd)}</td>
        </tr>`).join('');
    });
  }

  // My Benefits — anyone with a linked employee record
  const hasEmployeeRecord = !!currentUser?.employee_id;
  document.getElementById('myBenefitsDashSection')?.classList.toggle('hidden', !hasEmployeeRecord);
  if (hasEmployeeRecord) {
    api('/api/benefits/dashboard/mine').then(async res => {
      if (!res || !res.ok) return;
      const s = await res.json();

      const claimsEl = document.getElementById('mdClaimsList');
      document.getElementById('mdClaimsEmpty')?.classList.toggle('hidden', s.recent_claims.length > 0);
      const claimBadge = status => {
        if (status === 'Approved') return 'status-info';
        if (status === 'Paid') return 'status-positive';
        if (status === 'Rejected') return 'status-negative';
        return 'status-pending';
      };
      claimsEl.innerHTML = s.recent_claims.map(c => `
        <div class="flex items-center justify-between py-1.5 border-b border-slate-100 last:border-0">
          <div>
            <p class="text-sm text-slate-700">${esc(c.plan_name)}</p>
            <p class="text-xs text-slate-400">${fmtDate(c.claim_date)} · ${fmtCurrency(c.amount_claimed)}</p>
          </div>
          <span class="badge ${claimBadge(c.status)}">${esc(c.status)}</span>
        </div>`).join('');

      const balEl = document.getElementById('mdBalancesList');
      document.getElementById('mdBalancesEmpty')?.classList.toggle('hidden', s.balances.length > 0);
      balEl.innerHTML = s.balances.map(b => {
        const pctUsed = b.annual_cap > 0 ? Math.min(100, Math.round(b.used_amount / b.annual_cap * 100)) : 0;
        return `
        <div>
          <div class="flex items-center justify-between mb-1">
            <span class="text-sm text-slate-700">${esc(b.plan_name)}</span>
            <span class="text-xs text-slate-500">${fmtCurrency(b.remaining_amount)} left of ${fmtCurrency(b.annual_cap)}</span>
          </div>
          <div class="bg-slate-100 rounded-full h-2">
            <div class="bg-emerald-500 h-2 rounded-full" style="width:${pctUsed}%"></div>
          </div>
        </div>`;
      }).join('');
    });
  }
}

function exportBenefitsDeptCostCsv() {
  const s = window.getLastBenefitsDashboard?.();
  if (!s) return;
  const rows = [['Department', 'Enrolled Count', 'Monthly Employer Cost', 'Monthly Employee Cost']];
  s.department_costs.forEach(d => rows.push([d.department, d.enrolled_count, d.monthly_employer_cost_total, d.monthly_employee_cost_total]));
  downloadCsv(rows, 'benefits-cost-by-department.csv');
}

function exportBenefitsUtilizationCsv() {
  const s = window.getLastBenefitsDashboard?.();
  if (!s) return;
  const rows = [['Plan', 'Category', 'Enrolled', 'Waived', 'Claims Claimed YTD', 'Claims Paid YTD']];
  s.plan_utilization.forEach(p => rows.push([p.plan_name, p.plan_category, p.enrolled_count, p.waived_count, p.claims_claimed_ytd, p.claims_paid_ytd]));
  downloadCsv(rows, 'benefits-utilization-by-plan.csv');
}

function downloadCsv(rows, filename) {
  const csv = rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// ---------------------------------------------------------------------------
// Dashboard To-Do list — computed server-side from live pending-action state.
// Always visible (per spec) for all roles except superadmin, even when empty.
// ---------------------------------------------------------------------------
function renderDashGreeting() {
  const dateEl = document.getElementById('dashGreetingDate');
  const greetEl = document.getElementById('dashGreeting');
  if (!dateEl || !greetEl) return;
  const now = new Date();
  dateEl.textContent = `${now.toLocaleDateString('en-MY',{weekday:'short'})}, ${fmtDate(now)}`;
  const hour = now.getHours();
  const partOfDay = hour < 12 ? 'morning' : hour < 17 ? 'afternoon' : 'evening';
  const firstName = (currentUser?.full_name || currentUser?.username || '').split(' ')[0] || 'there';
  greetEl.textContent = `Good ${partOfDay}, ${firstName}`;
}

// Home KPI tiles: headcount (populated by loadWorkforceStats instead — see
// that function — same figure as Workforce tab's statActive), pending
// approvals (from /api/todos — see loadDashboardTodos, which populates
// this tile itself once it has the data, to avoid a second fetch),
// payroll cut-off (computed client-side from the institution's pay_day,
// no new endpoint), open roles (reuses /api/recruitment/dashboard-stats,
// same figure loadRecruitmentDash's rStatOpenReq shows). Each is
// independent and fails soft (leaves the tile at its default "—") rather
// than blocking the others — a role without recruitment access, for
// instance, just doesn't get an Open Roles number.
async function loadDashboardKpis() {
  const inst = currentUser?.role === 'superadmin' ? currentInstitution : currentUser?.institution;
  const cutoffEl = document.getElementById('kpiPayrollCutoff');
  if (cutoffEl) {
    const payDay = inst?.pay_day || 25;
    const now = new Date();
    let next = new Date(now.getFullYear(), now.getMonth(), payDay);
    if (next < now) next = new Date(now.getFullYear(), now.getMonth() + 1, payDay);
    cutoffEl.textContent = next.toLocaleDateString('en-MY', { day: 'numeric', month: 'short' });
    const daysAway = Math.ceil((next - now) / 86400000);
    const deltaEl = document.getElementById('kpiPayrollCutoffDelta');
    if (deltaEl) deltaEl.textContent = daysAway <= 3 ? `${daysAway}d away` : `in ${daysAway} days`;
  }

  api('/api/recruitment/dashboard-stats').then(async res => {
    const openRolesEl = document.getElementById('kpiOpenRoles');
    if (!openRolesEl) return;
    if (!res?.ok) { openRolesEl.textContent = '—'; return; }
    const s = await res.json();
    openRolesEl.textContent = (s.req_by_status['Approved'] || 0) + (s.req_by_status['Draft'] || 0);
  }).catch(() => {});
}

// Picks which single row gets the accent "needs action" treatment: the
// item with the nearest due date if any todo has one (overdue first,
// then soonest upcoming), otherwise the item with the highest count,
// otherwise just the first row — always exactly one row, never zero
// (matches "Only one row is highlighted at a time" in the redesign brief).
function _pickUrgentTodo(items) {
  const dated = items.filter(t => t.due_date);
  if (dated.length) return dated.slice().sort((a, b) => a.due_date < b.due_date ? -1 : 1)[0];
  return items.slice().sort((a, b) => (b.count || 0) - (a.count || 0))[0];
}

async function loadDashboardTodos() {
  const card=document.getElementById('dashboardTodoCard');
  if(!card) return;
  if(currentUser?.role==='superadmin'){ card.classList.add('hidden'); return; }
  card.classList.remove('hidden');
  const listEl=document.getElementById('dashboardTodoList');
  const emptyEl=document.getElementById('dashboardTodoEmpty');
  const res=await api('/api/todos');
  const items=res?.ok?await res.json():[];

  const approvalsEl = document.getElementById('kpiApprovals');
  if (approvalsEl) {
    const pending = items.filter(t => t.label.includes('awaiting your approval'))
      .reduce((sum, t) => sum + (t.count || 0), 0);
    approvalsEl.textContent = pending;
  }

  if(!items.length){
    listEl.innerHTML='';
    emptyEl.classList.remove('hidden');
    return;
  }
  emptyEl.classList.add('hidden');
  const today = new Date().toISOString().slice(0, 10);
  const urgent = _pickUrgentTodo(items);
  listEl.innerHTML=items.map(t=>{
    // A "dash-" page value is a Dashboard sub-tab (e.g. "dash-leave" for
    // the monthly calendar), not a top-level page — showPage() alone
    // lands on the Dashboard's default tab, so it needs switchDashTab()
    // too. No top-level ALL_PAGES entry starts with "dash-", so this
    // prefix check is unambiguous.
    const onclick = t.page.startsWith('dash-')
      ? `showPage('dashboard');switchDashTab('${t.page}')`
      : `showPage('${t.page}')`;
    const isUrgent = t === urgent;
    const overdue = t.due_date && t.due_date < today;
    const initials = t.employee_name
      ? t.employee_name.split(' ').slice(0,2).map(w=>w[0]||'').join('').toUpperCase()
      : String(t.count || '');
    const metaParts = t.employee_name
      ? [t.employee_name, t.stage_type, t.due_date ? fmtDate(t.due_date) : null].filter(Boolean)
      : [];
    const metaLine = metaParts.length ? metaParts.join(' · ') : '';
    const action = isUrgent
      ? `<button onclick="event.stopPropagation();${onclick}" class="pill-btn pill-btn-primary" style="padding:6px 16px;font-size:12.5px">Review</button>`
      : `<span class="todo-row-open">Open</span>`;
    return `
    <div class="todo-row${isUrgent ? ' todo-row-urgent' : ''} cursor-pointer" onclick="${onclick}">
      <div class="todo-avatar">${esc(initials)}</div>
      <div class="flex-1 min-w-0">
        <p class="todo-row-title truncate">${esc(t.label)}</p>
        ${metaLine ? `<p class="todo-row-meta truncate${overdue ? ' overdue' : ''}">${esc(metaLine)}</p>` : ''}
      </div>
      ${action}
    </div>`;
  }).join('');
}

// Dashboard quick-action shortcuts (employee role only — see
// renderDashboard's dashboardQuickActions toggle). Each jumps to the
// relevant page (for its own nav-active state and title) and pre-loads
// just the one piece of cached state its modal actually reads, rather
// than awaiting that page's whole load function (which showPage's own
// dispatch already fires in the background) — avoids a duplicate
// full-page fetch just to guarantee ordering.
async function dashShortcutApplyLeave() {
  showPage('leave-my');
  await loadLeaveTypesCache();
  openLeaveApplyModal();
}

async function dashShortcutSubmitClaim() {
  showPage('payroll-mybenefits');
  const res = await api('/api/benefits/eligible-plans/mine');
  myEligiblePlans = (res && res.ok) ? await res.json() : [];
  openClaimForm();
}

// Clock In/Out shortcut — unlike the two above, this acts immediately in
// place rather than navigating to a page + opening a modal, so it's a
// lightweight standalone version of attendanceClockIn/Out (static/js/
// attendance.js, the page-attendance-clock page) rather than a reuse of
// those functions directly: those read/write DOM elements (geo note,
// history table) that only exist on that page, not Home. attCaptureGeo()
// itself has no such dependency, so it's shared as-is.
async function refreshDashClockState() {
  const btn = document.getElementById('dashClockBtn');
  if (!btn || !currentUser?.employee_id) return;
  const res = await api('/api/attendance/mine?limit=1');
  const rows = (res && res.ok) ? await res.json() : [];
  const open = rows[0] && rows[0].clock_in_at && !rows[0].clock_out_at;
  btn.textContent = open ? 'Clock Out' : 'Clock In';
  btn.setAttribute('onclick', open ? 'dashShortcutClockOut()' : 'dashShortcutClockIn()');
}

async function dashShortcutClockIn() {
  const geo = await attCaptureGeo();
  const res = await api('/api/attendance/clock-in', {
    method: 'POST',
    body: JSON.stringify({ lat: geo?.lat ?? null, lng: geo?.lng ?? null }),
  });
  if (!res || !res.ok) { const d = await res?.json().catch(() => ({})); alert(d?.detail || 'Failed to clock in'); return; }
  await refreshDashClockState();
}

async function dashShortcutClockOut() {
  const geo = await attCaptureGeo();
  const res = await api('/api/attendance/clock-out', {
    method: 'POST',
    body: JSON.stringify({ lat: geo?.lat ?? null, lng: geo?.lng ?? null }),
  });
  if (!res || !res.ok) { const d = await res?.json().catch(() => ({})); alert(d?.detail || 'Failed to clock out'); return; }
  await refreshDashClockState();
}

// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Leave Calendar — visible to anyone with Leave-tab access (see
// loadLeaveDash's canViewLeaveDash/hasEmployeeRecord gate below, which
// already controls whether dash-leave itself is reachable). The endpoint
// itself (not this code) decides whether each entry's leave type is
// visible — see routers/leave.py's get_leave_calendar.
// ---------------------------------------------------------------------------
let leaveCalYear = new Date().getFullYear();
let leaveCalMonth = new Date().getMonth() + 1; // 1-12

function leaveCalPrevMonth() {
  leaveCalMonth--;
  if (leaveCalMonth < 1) { leaveCalMonth = 12; leaveCalYear--; }
  loadLeaveCalendar();
}

function leaveCalNextMonth() {
  leaveCalMonth++;
  if (leaveCalMonth > 12) { leaveCalMonth = 1; leaveCalYear++; }
  loadLeaveCalendar();
}

const LEAVE_CAL_MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

function loadLeaveCalendar() {
  document.getElementById('leaveCalMonthLabel').textContent = `${LEAVE_CAL_MONTH_NAMES[leaveCalMonth-1]} ${leaveCalYear}`;
  // Document expiry reminders (work permit renewal, passport expiry, etc)
  // are HR-only — skip the fetch entirely for other roles rather than
  // just discarding an unauthorized response; the endpoint also enforces
  // this server-side (routers/employee_documents.py) as defense in depth.
  const canViewDocExpiry = HR_STAFF_ROLES.includes(currentUser?.role);
  Promise.all([
    api(`/api/leave/calendar?year=${leaveCalYear}&month=${leaveCalMonth}`),
    api(`/api/holidays?year=${leaveCalYear}`),
    api(`/api/ob/calendar?year=${leaveCalYear}&month=${leaveCalMonth}`),
    canViewDocExpiry ? api(`/api/employee-documents/calendar?year=${leaveCalYear}&month=${leaveCalMonth}`) : Promise.resolve(null),
  ]).then(async ([leaveRes, holidayRes, obRes, docRes]) => {
    const entries = (leaveRes && leaveRes.ok) ? await leaveRes.json() : [];
    const holidays = (holidayRes && holidayRes.ok) ? await holidayRes.json() : [];
    const obItems = (obRes && obRes.ok) ? await obRes.json() : [];
    const docExpiries = (docRes && docRes.ok) ? await docRes.json() : [];
    renderLeaveCalendarGrid(entries, holidays, obItems, docExpiries);
  });
}

function renderLeaveCalendarGrid(entries, holidays, obItems, docExpiries) {
  const grid = document.getElementById('leaveCalGrid');
  const firstDay = new Date(leaveCalYear, leaveCalMonth - 1, 1);
  const daysInMonth = new Date(leaveCalYear, leaveCalMonth, 0).getDate();
  const startOffset = firstDay.getDay(); // 0=Sun

  // Bucket each entry's days into the calendar cells they span. A
  // half-day period only annotates the specific day it applies to — the
  // start day for start_day_period, the end day for end_day_period, never
  // the full days in between — so each day gets its own shallow copy
  // carrying just that day's period (or null for a full day).
  const byDay = {};
  for (const e of entries) {
    const start = new Date(e.start_date + 'T00:00:00');
    const end = new Date(e.end_date + 'T00:00:00');
    for (let d = new Date(Math.max(start, firstDay)); d <= end && d.getMonth() === leaveCalMonth - 1; d.setDate(d.getDate() + 1)) {
      const day = d.getDate();
      const dStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
      const dayPeriod = dStr === e.start_date ? e.start_day_period : (dStr === e.end_date ? e.end_day_period : null);
      (byDay[day] = byDay[day] || []).push({ ...e, _dayPeriod: dayPeriod });
    }
  }
  // Public holidays fall on exactly one day each (unlike leave, which can
  // span a range) — bucket by that day's date string directly, no range walk.
  const holidaysByDay = {};
  for (const h of (holidays || [])) {
    const d = new Date(h.date + 'T00:00:00');
    if (d.getFullYear() === leaveCalYear && d.getMonth() === leaveCalMonth - 1) {
      (holidaysByDay[d.getDate()] = holidaysByDay[d.getDate()] || []).push(h);
    }
  }
  // Onboarding/offboarding action items with a due_date — one day each,
  // same bucketing as holidays. due_date is a plain HR-entered wall-clock
  // value (not a UTC *_at timestamp — see routers/onboarding.py), so its
  // date portion is read literally, no parseUTC/timezone conversion.
  const obByDay = {};
  for (const o of (obItems || [])) {
    if (!o.due_date) continue;
    const d = new Date(o.due_date.slice(0, 10) + 'T00:00:00');
    if (d.getFullYear() === leaveCalYear && d.getMonth() === leaveCalMonth - 1) {
      (obByDay[d.getDate()] = obByDay[d.getDate()] || []).push(o);
    }
  }
  // Employee document expiries (work permit renewal, passport expiry,
  // etc) — one day each like holidays, no range walk needed.
  const docExpiryByDay = {};
  for (const de of (docExpiries || [])) {
    const d = new Date(de.expiry_date + 'T00:00:00');
    if (d.getFullYear() === leaveCalYear && d.getMonth() === leaveCalMonth - 1) {
      (docExpiryByDay[d.getDate()] = docExpiryByDay[d.getDate()] || []).push(de);
    }
  }

  const todayStr = new Date().toISOString().slice(0, 10);
  let cells = '';
  for (let i = 0; i < startOffset; i++) cells += `<div></div>`;
  for (let day = 1; day <= daysInMonth; day++) {
    const dateStr = `${leaveCalYear}-${String(leaveCalMonth).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
    const isToday = dateStr === todayStr;
    const dayHolidays = holidaysByDay[day] || [];
    const isHoliday = dayHolidays.length > 0;
    // Leave entries and action items share one combined +N-more cap, so a
    // busy day doesn't just show whichever type happened to bucket first.
    const dayItems = [
      ...(byDay[day] || []).map(e => ({ kind: 'leave', e })),
      ...(obByDay[day] || []).map(o => ({ kind: 'ob', o })),
      ...(docExpiryByDay[day] || []).map(de => ({ kind: 'docexpiry', de })),
    ];
    const shown = dayItems.slice(0, 3);
    const rest = dayItems.slice(3);
    const holidayChips = dayHolidays.map(h => `
      <div class="text-xs bg-rose-50 text-rose-700 rounded-sm px-1 py-0.5 truncate font-medium" title="${esc(h.name)}">
        ${esc(h.name)}
      </div>`).join('');
    const chipInner = item => {
      if (item.kind === 'leave') return `${esc(displayName(item.e.full_name,item.e.preferred_name))}${item.e.leave_type_name ? ` (${esc(item.e.leave_type_name)})` : ''}${item.e._dayPeriod ? ` (${item.e._dayPeriod})` : ''}`;
      if (item.kind === 'docexpiry') return `⚠️ ${esc(displayName(item.de.full_name,item.de.preferred_name))} — ${esc(item.de.document_type_name)} expires`;
      return `📌 ${esc(item.o.title)} — ${esc(displayName(item.o.employee_name,item.o.employee_preferred_name))}`;
    };
    const chipTitle = item => {
      if (item.kind === 'leave') return `${esc(displayName(item.e.full_name,item.e.preferred_name))}${item.e.leave_type_name ? ' — ' + esc(item.e.leave_type_name) : ''}${item.e._dayPeriod ? ` (${item.e._dayPeriod})` : ''}`;
      if (item.kind === 'docexpiry') return `${esc(displayName(item.de.full_name,item.de.preferred_name))} — ${esc(item.de.document_type_name)} expires ${fmtDate(item.de.expiry_date)}`;
      return `${esc(item.o.title)} — ${esc(displayName(item.o.employee_name,item.o.employee_preferred_name))}`;
    };
    const chipClass = item => {
      if (item.kind === 'leave') return 'bg-amber-50 text-amber-700';
      if (item.kind === 'ob') return 'bg-indigo-50 text-indigo-700';
      // docexpiry — colored by urgency, same status vocabulary as the
      // Employee Detail Documents tab (routers/employee_documents.py's
      // STATUS_CASE_SQL).
      return item.de.status === 'overdue' ? 'bg-red-50 text-red-700' : 'bg-amber-50 text-amber-800';
    };
    const chips = shown.map(item => `
      <div class="text-xs ${chipClass(item)} rounded-sm px-1 py-0.5 truncate" title="${chipTitle(item)}">
        ${chipInner(item)}
      </div>`).join('');
    const extraLabel = rest.length > 0 ? `
      <div class="relative group">
        <div class="text-xs text-slate-400 cursor-default">+${rest.length} more</div>
        <div class="hidden group-hover:block absolute z-10 left-0 top-full mt-1 bg-white border border-slate-200 rounded-lg shadow-lg p-2 min-w-[160px] max-w-[240px] space-y-0.5">
          ${rest.map(item => `<div class="text-xs text-slate-700 truncate">${chipInner(item)}</div>`).join('')}
        </div>
      </div>` : '';
    cells += `
      <div class="min-h-[70px] border rounded-lg p-1 ${isToday ? 'ring-1 ring-blue-400' : ''} ${isHoliday ? 'bg-rose-50/50 border-rose-100' : 'border-slate-100'}">
        <div class="text-xs ${isToday ? 'font-bold text-blue-600' : (isHoliday ? 'font-semibold text-rose-500' : 'text-slate-400')} mb-0.5">${day}</div>
        <div class="space-y-0.5">${holidayChips}${chips}${extraLabel}</div>
      </div>`;
  }
  grid.innerHTML = cells;
}

// Cache of the last-fetched by-type breakdown (always institution-wide,
// unfiltered) so clicking a row can look its id/name back up without a
// round trip, and the currently selected type (if any) the Top/Bottom 10
// rankings below are narrowed to — see loadLeaveUtilDash.
let leaveDashByTypeCache = [];
let leaveDashTypeFilter = null; // { id, name } | null — null means "all types"

function loadLeaveDash() {
  loadLeaveCalendar();
  const canViewLeaveDash = HR_STAFF_ROLES.includes(currentUser?.role);
  document.getElementById('leaveUtilDashSection').classList.toggle('hidden', !canViewLeaveDash);
  if (canViewLeaveDash) {
    leaveDashTypeFilter = null;
    loadLeaveUtilDash();
  }

  const hasEmployeeRecord = !!currentUser?.employee_id;
  document.getElementById('myLeaveDashSection').classList.toggle('hidden', !hasEmployeeRecord);
  if (hasEmployeeRecord) loadMyLeaveDash();
}

function loadLeaveUtilDash() {
  const url = '/api/leave/dashboard/utilization' + (leaveDashTypeFilter ? `?leave_type_id=${leaveDashTypeFilter.id}` : '');
  api(url).then(async res => {
    if (!res || !res.ok) return;
    const s = await res.json();
    leaveDashByTypeCache = s.by_type;

    const byTypeEl = document.getElementById('leaveDashByType');
    document.getElementById('leaveDashByTypeEmpty').classList.toggle('hidden', s.by_type.length > 0);
    byTypeEl.innerHTML = s.by_type.map(t => {
      const active = leaveDashTypeFilter?.id === t.leave_type_id;
      return `
      <div class="flex items-center gap-2 cursor-pointer rounded-lg px-1.5 -mx-1.5 py-0.5 transition ${active ? 'bg-blue-50 ring-1 ring-blue-200' : 'hover:bg-slate-50'}" onclick="setLeaveDashTypeFilter(${t.leave_type_id})" title="Click to rank employees by ${esc(t.leave_type_name)}">
        <div class="w-32 text-xs text-slate-600 truncate" title="${esc(t.leave_type_name)}">${esc(t.leave_type_name)}</div>
        <div class="flex-1 bg-slate-100 rounded-full h-2">
          <div class="bg-blue-500 h-2 rounded-full" style="width:${Math.min(100, t.utilization_percent)}%"></div>
        </div>
        <div class="text-xs text-slate-500 w-32 text-right">${t.total_used}/${t.total_entitled} days (${t.utilization_percent}%)</div>
      </div>`;
    }).join('');

    document.getElementById('leaveDashFilterLabel').textContent = leaveDashTypeFilter ? leaveDashTypeFilter.name : 'All Leave Types';
    document.getElementById('leaveDashClearFilter').classList.toggle('hidden', !leaveDashTypeFilter);

    renderLeaveDashRanking('leaveDashTopHighest', s.top_highest, 'bg-red-500');
    renderLeaveDashRanking('leaveDashTopLowest', s.top_lowest, 'bg-emerald-500');
  });
}

function setLeaveDashTypeFilter(leaveTypeId) {
  if (leaveDashTypeFilter?.id === leaveTypeId) {
    leaveDashTypeFilter = null; // clicking the already-active type toggles back to "all"
  } else {
    const t = leaveDashByTypeCache.find(x => x.leave_type_id === leaveTypeId);
    leaveDashTypeFilter = t ? { id: t.leave_type_id, name: t.leave_type_name } : null;
  }
  loadLeaveUtilDash();
}

function clearLeaveDashTypeFilter() {
  leaveDashTypeFilter = null;
  loadLeaveUtilDash();
}

function loadMyLeaveDash() {
  const year = new Date().getFullYear();
  const empId = currentUser.employee_id;

  api(`/api/leave/balances?year=${year}&employee_id=${empId}`).then(async res => {
    const listEl = document.getElementById('myLeaveBalancesList');
    const emptyEl = document.getElementById('myLeaveBalancesEmpty');
    if (!res || !res.ok) { listEl.innerHTML = ''; emptyEl.classList.remove('hidden'); return; }
    const balances = await res.json();
    if (!balances.length) { listEl.innerHTML = ''; emptyEl.classList.remove('hidden'); return; }
    emptyEl.classList.add('hidden');
    listEl.innerHTML = balances.map(b => {
      // accrued_days equals entitled_days for full_year types (no visual
      // difference) and the pro-rated earn-as-you-work figure for monthly
      // accrual types — Balance/Utilization are based on what's actually
      // usable right now (accrued), not the full annual figure.
      const usable = b.accrued_days + b.carried_forward_days;
      const remaining = usable - b.used_days;
      const pct = usable ? Math.round(b.used_days / usable * 100) : 0;
      return `
      <tr class="border-t border-slate-100">
        <td class="py-1.5 text-sm text-slate-700">${esc(b.leave_type_name)}</td>
        <td class="py-1.5 text-sm text-right">${b.entitled_days}</td>
        <td class="py-1.5 text-sm text-right">${b.accrued_days}</td>
        <td class="py-1.5 text-sm text-right">${b.used_days}</td>
        <td class="py-1.5 text-sm text-right font-medium">${remaining}</td>
        <td class="py-1.5 text-sm text-right">${pct}%</td>
      </tr>`;
    }).join('');
  });

  api('/api/leave/applications').then(async res => {
    const listEl = document.getElementById('myLeaveHistoryList');
    const emptyEl = document.getElementById('myLeaveHistoryEmpty');
    if (!res || !res.ok) { listEl.innerHTML = ''; emptyEl.classList.remove('hidden'); return; }
    const apps = (await res.json()).filter(a => a.employee_id === empId);
    if (!apps.length) { listEl.innerHTML = ''; emptyEl.classList.remove('hidden'); return; }
    emptyEl.classList.add('hidden');
    const statusBadge = status => {
      if (status === 'Approved') return 'status-positive';
      if (status === 'Rejected' || status === 'Cancelled') return 'status-negative';
      return 'status-pending';
    };
    listEl.innerHTML = apps.map(a => `
      <tr class="border-t border-slate-100">
        <td class="py-1.5 text-sm text-slate-700">${esc(a.leave_type_name)}</td>
        <td class="py-1.5 text-sm text-slate-600">${fmtDate(a.start_date)} – ${fmtDate(a.end_date)}</td>
        <td class="py-1.5 text-sm text-right">${a.days_count}</td>
        <td class="py-1.5 text-xs text-slate-500">${fmtDate(a.created_at)}</td>
        <td class="py-1.5 text-xs text-slate-500">${fmtDate(a.approved_at)}</td>
        <td class="py-1.5"><span class="badge ${statusBadge(a.status)}">${esc(a.status)}</span></td>
      </tr>`).join('');
  });
}

function renderLeaveDashRanking(containerId, list, barColor) {
  const el = document.getElementById(containerId);
  document.getElementById(containerId + 'Empty').classList.toggle('hidden', list.length > 0);
  el.innerHTML = list.map((e, i) => `
    <div class="flex items-center gap-2">
      <div class="w-5 text-xs text-slate-400 text-right shrink-0">${i + 1}</div>
      <div class="w-28 text-xs text-slate-700 truncate cursor-default leave-emp-name" title="${esc(displayName(e.full_name,e.preferred_name))}"
           data-breakdown='${JSON.stringify({ name: displayName(e.full_name,e.preferred_name), department: e.department, breakdown: e.breakdown }).replace(/'/g,"&apos;")}'>
        ${esc(displayName(e.full_name,e.preferred_name))}
      </div>
      <div class="flex-1 bg-slate-100 rounded-full h-2">
        <div class="${barColor} h-2 rounded-full" style="width:${Math.min(100, e.utilization_percent)}%"></div>
      </div>
      <div class="text-xs text-slate-500 w-28 text-right">${e.total_used}/${e.total_entitled} days (${e.utilization_percent}%)</div>
    </div>`).join('');
}

// Shared floating tooltip for the Leave dashboard's top/bottom lists — shows
// the hovered employee's own leave-type breakdown, since the ranking bar
// only shows their overall utilization.
document.addEventListener('mouseover', e => {
  const target = e.target.closest('.leave-emp-name');
  if (!target) return;
  const data = JSON.parse(target.dataset.breakdown);
  const tooltip = document.getElementById('leaveEmpTooltip');
  const rows = data.breakdown.map(b =>
    `<div class="flex justify-between gap-3"><span>${esc(b.leave_type_name)}</span><span>${b.used_days}/${b.entitled_days}d (${b.utilization_percent}%)</span></div>`
  ).join('') || '<div class="text-slate-300">No leave type balances.</div>';
  tooltip.innerHTML = `<div class="font-semibold mb-1">${esc(data.name)}${data.department ? ` · ${esc(data.department)}` : ''}</div>${rows}`;
  const rect = target.getBoundingClientRect();
  tooltip.style.left = `${rect.left}px`;
  tooltip.style.top = `${rect.bottom + 6}px`;
  tooltip.classList.remove('hidden');
});
document.addEventListener('mouseout', e => {
  if (e.target.closest('.leave-emp-name')) document.getElementById('leaveEmpTooltip').classList.add('hidden');
});

;
// ---- employees.js ----
// Employees
// ---------------------------------------------------------------------------
async function loadEmployees() {
  const res = await api('/api/employees');
  if (!res || !res.ok) return;
  employees = await res.json();
}

// Years lapsed since start_date, as a float (for sorting) — e.g. 3.33 for 3y4m.
function yearsOfServiceValue(e) {
  if (!e.start_date) return -1;
  const start = new Date(e.start_date);
  if (isNaN(start)) return -1;
  return (Date.now() - start.getTime()) / (1000*60*60*24*365.25);
}

function yearsOfServiceLabel(e) {
  const v = yearsOfServiceValue(e);
  if (v < 0) return '—';
  const years = Math.floor(v);
  const months = Math.round((v - years) * 12);
  if (years === 0) return `${months} mo${months===1?'':'s'}`;
  return months ? `${years}y ${months}m` : `${years}y`;
}

// Server-paginated (routers/employees.py's optional limit/offset/sort_by
// + X-Total-Count header — opt-in, so the app-wide employees[] roster used
// by org chart/pickers/dashboards via loadEmployees() above is completely
// unaffected). Independent of employees[]: this screen's rows come from
// its own dedicated fetch below, not from filtering the full roster.
// manager_name/location_name/pay_grade_name/years_of_service aren't real
// DB columns (resolved server-side per-row via post-query lookups, same
// as before) so they're not in the server sort allowlist — sorting by one
// of those sorts only the current page, client-side (empClientSort*),
// rather than the whole table like the 13 plain-column sorts do.
const EMP_DERIVED_SORT_KEYS = new Set(['manager_name', 'location_name', 'pay_grade_name', 'years_of_service']);
let empPage = 1, empPageSize = 50, empTotal = 0;
let empSortKey = 'full_name', empSortDir = 'asc';
let empClientSortKey = null, empClientSortDir = 'asc';
let empPageRows = [];
let empSearchDebounceTimer = null;

// ---------------------------------------------------------------------------
// Employee List — optional columns
// ---------------------------------------------------------------------------
// The Name column (avatar + name) and the trailing chevron are always
// shown; every other column is opt-in via the Columns picker, remembered
// per-browser in localStorage. "Pay Grade" only appears for roles that can
// already see compensation data elsewhere (Compensation module's own
// gate — see dashboard.js's canCompensation) — it's filtered out of the
// picker AND never rendered for anyone else, even if a stale preference
// from a different user/role is sitting in this browser's storage.
const EMP_COLUMNS = [
  { key:'employee_id', label:'ID', sortKey:'employee_id', default:false, render:e=>esc(e.employee_id) },
  { key:'email', label:'Email', sortKey:'work_email', default:false, render:e=>esc(e.work_email||'—') },
  { key:'phone', label:'Mobile No', sortKey:'phone', default:false, render:e=>esc(e.phone||'—') },
  { key:'designation', label:'Job Title', sortKey:'designation', default:true, render:e=>esc(e.designation||'—') },
  { key:'department', label:'Department', sortKey:'department', default:true, render:e=>esc(e.department||'—') },
  { key:'manager', label:'Manager', sortKey:'manager_name', default:true, render:e=>e.manager_name?esc(displayName(e.manager_name,e.manager_preferred_name)):'—' },
  { key:'location', label:'Location', sortKey:'location_name', default:true, render:e=>esc(e.location_name||'—') },
  { key:'start_date', label:'Join Date', sortKey:'start_date', default:false, render:e=>fmtDate(e.start_date) },
  { key:'probation_end_date', label:'Confirm Date', sortKey:'probation_end_date', default:false, render:e=>fmtDate(e.probation_end_date) },
  { key:'resign_date', label:'Resign Date', sortKey:'resign_date', default:false, render:e=>fmtDate(e.resign_date) },
  { key:'last_working_day', label:'Last Working Day', sortKey:'last_working_day', default:false, render:e=>fmtDate(e.last_working_day) },
  { key:'date_of_birth', label:'Date of Birth', sortKey:'date_of_birth', default:false, render:e=>fmtDate(e.date_of_birth) },
  { key:'gender', label:'Gender', sortKey:'gender', default:false, render:e=>esc(e.gender||'—') },
  { key:'race', label:'Race', sortKey:'race', default:false, render:e=>esc(e.race||'—') },
  { key:'employment_type', label:'Employee Type', sortKey:'employment_type', default:true, render:e=>esc(e.employment_type||'—') },
  { key:'years_of_service', label:'Years of Service', sortKey:'years_of_service', default:true, render:e=>yearsOfServiceLabel(e) },
  { key:'status', label:'Status', sortKey:'status', default:true, render:e=>`<span class="badge ${e.status==='Active'?'status-positive':'status-neutral'}">${e.status}</span>` },
  { key:'pay_grade', label:'Pay Grade', sortKey:'pay_grade_name', default:false, roles:COMPENSATION_STAFF_ROLES, render:e=>esc(e.pay_grade_name||'—') },
];
const EMP_COLUMNS_STORAGE_KEY = 'empListColumns';

function empAvailableColumns() {
  return EMP_COLUMNS.filter(c => !c.roles || c.roles.includes(currentUser?.role));
}

function loadEmpColumnPrefs() {
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(EMP_COLUMNS_STORAGE_KEY) || 'null'); } catch { /* ignore malformed value */ }
  const available = new Set(empAvailableColumns().map(c => c.key));
  if (Array.isArray(saved)) return new Set(saved.filter(k => available.has(k)));
  return new Set(EMP_COLUMNS.filter(c => c.default).map(c => c.key));
}
// Loaded lazily (not at script-parse time) since it depends on
// currentUser.role for the roles-gated columns, and currentUser isn't set
// yet until login completes — see empAvailableColumns.
let empVisibleColumns = null;
function ensureEmpColumnPrefsLoaded() { if (empVisibleColumns === null) empVisibleColumns = loadEmpColumnPrefs(); }

function saveEmpColumnPrefs() { localStorage.setItem(EMP_COLUMNS_STORAGE_KEY, JSON.stringify([...empVisibleColumns])); }

function toggleEmpColumn(key) {
  if (empVisibleColumns.has(key)) empVisibleColumns.delete(key); else empVisibleColumns.add(key);
  saveEmpColumnPrefs();
  renderEmpColumnsPicker();
  renderEmpTable();
}

function resetEmpColumns() {
  empVisibleColumns = new Set(EMP_COLUMNS.filter(c => c.default).map(c => c.key));
  saveEmpColumnPrefs();
  renderEmpColumnsPicker();
  renderEmpTable();
}

function toggleEmpColumnPicker() {
  const panel = document.getElementById('empColumnsPanel');
  const opening = panel.classList.contains('hidden');
  if (opening) renderEmpColumnsPicker();
  panel.classList.toggle('hidden');
}
document.addEventListener('click', e => {
  if (!document.getElementById('empColumnsBtn')?.contains(e.target) && !document.getElementById('empColumnsPanel')?.contains(e.target)) {
    document.getElementById('empColumnsPanel')?.classList.add('hidden');
  }
});

function renderEmpColumnsPicker() {
  ensureEmpColumnPrefsLoaded();
  document.getElementById('empColumnsList').innerHTML = empAvailableColumns().map(c => `
    <label class="flex items-center gap-2 text-sm text-slate-700 cursor-pointer py-0.5">
      <input type="checkbox" class="rounded-sm" ${empVisibleColumns.has(c.key)?'checked':''} onchange="toggleEmpColumn('${c.key}')"/>
      ${esc(c.label)}
    </label>`).join('');
}

function setEmpSort(key) {
  if (EMP_DERIVED_SORT_KEYS.has(key)) {
    if (empClientSortKey === key) empClientSortDir = empClientSortDir === 'asc' ? 'desc' : 'asc';
    else { empClientSortKey = key; empClientSortDir = 'asc'; }
    renderEmpTable();
    return;
  }
  empClientSortKey = null; // a real server sort replaces any current-page-only client sort
  if (empSortKey === key) empSortDir = empSortDir === 'asc' ? 'desc' : 'asc';
  else { empSortKey = key; empSortDir = 'asc'; }
  empPage = 1;
  loadEmployeeListPage();
}
function setEmpPageSize(size) { empPageSize = parseInt(size) || 50; empPage = 1; loadEmployeeListPage(); }
function empPagePrev() { if (empPage > 1) { empPage--; loadEmployeeListPage(); } }
function empPageNext() {
  const totalPages = Math.max(1, Math.ceil(empTotal / empPageSize));
  if (empPage < totalPages) { empPage++; loadEmployeeListPage(); }
}

// Debounced — empSearch fires on every keystroke (oninput), and each call
// here is a real network round trip now (server-side search), not an
// in-memory filter.
function filterEmployees() {
  empPage = 1;
  clearTimeout(empSearchDebounceTimer);
  empSearchDebounceTimer = setTimeout(loadEmployeeListPage, 250);
}

// A fast typist (or a quick page/sort click) can fire a new fetch before
// an older one's response lands — with a debounce this is rare but not
// impossible (e.g. two searches within the round-trip time of the first),
// and network completion order isn't guaranteed to match request order.
// empRequestSeq discards a response that's no longer the most recent
// request, so a slow, stale response can never overwrite the table.
let empRequestSeq = 0;
async function loadEmployeeListPage() {
  const seq = ++empRequestSeq;
  const q = document.getElementById('empSearch').value.trim();
  const s = document.getElementById('empStatusFilter').value;
  const offset = (empPage - 1) * empPageSize;
  const params = new URLSearchParams({
    limit: String(empPageSize), offset: String(offset),
    sort_by: empSortKey, sort_dir: empSortDir,
  });
  if (q) params.set('search', q);
  if (s) params.set('status', s);
  const res = await api(`/api/employees?${params}`);
  if (seq !== empRequestSeq) return; // a newer request has since started
  if (!res || !res.ok) return;
  empPageRows = await res.json();
  empTotal = parseInt(res.headers.get('X-Total-Count') || '0', 10);
  renderEmpTable();
}

function empSortValue(e, key) { return key === 'years_of_service' ? yearsOfServiceValue(e) : e[key]; }

// Applies the current-page-only derived-column sort, if one is active;
// otherwise rows are already in the server's sorted order.
function empDisplayRows() {
  if (!empClientSortKey) return empPageRows;
  const dir = empClientSortDir === 'asc' ? 1 : -1;
  return [...empPageRows].sort((a, b) => {
    let x = empSortValue(a, empClientSortKey), y = empSortValue(b, empClientSortKey);
    if (typeof x === 'string') x = x.toLowerCase();
    if (typeof y === 'string') y = y.toLowerCase();
    if (x == null) x = '';
    if (y == null) y = '';
    return x < y ? -1 * dir : x > y ? 1 * dir : 0;
  });
}

function renderEmpTableHead() {
  ensureEmpColumnPrefsLoaded();
  const cols = empAvailableColumns().filter(c => empVisibleColumns.has(c.key));
  document.getElementById('empTableHeadRow').innerHTML = `
    <th class="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase cursor-pointer select-none whitespace-nowrap" onclick="setEmpSort('full_name')">Name<span class="emp-sort-arrow" data-sort-key="full_name"></span></th>
    ${cols.map(c => `<th class="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase cursor-pointer select-none whitespace-nowrap" onclick="setEmpSort('${c.sortKey}')">${esc(c.label)}<span class="emp-sort-arrow" data-sort-key="${c.sortKey}"></span></th>`).join('')}
    <th class="px-4 py-3"></th>
  `;
}

function renderEmpTable() {
  const tbody = document.getElementById('empTableBody');
  const empty = document.getElementById('empEmpty');
  const pagination = document.getElementById('empPagination');
  renderEmpTableHead();
  document.querySelectorAll('.emp-sort-arrow').forEach(el => {
    const key = el.dataset.sortKey;
    const activeKey = empClientSortKey || empSortKey;
    const activeDir = empClientSortKey ? empClientSortDir : empSortDir;
    el.textContent = key === activeKey ? (activeDir === 'asc' ? ' ▲' : ' ▼') : '';
  });
  if (!empPageRows.length) { tbody.innerHTML=''; empty.classList.remove('hidden'); pagination.classList.add('hidden'); return; }
  empty.classList.add('hidden');
  pagination.classList.remove('hidden');
  document.getElementById('empPageSize').value = String(empPageSize);

  const offset = (empPage - 1) * empPageSize;
  document.getElementById('empPageInfo').textContent =
    `${offset + 1}-${Math.min(offset + empPageSize, empTotal)} of ${empTotal}`;

  const cols = empAvailableColumns().filter(c => empVisibleColumns.has(c.key));
  tbody.innerHTML = empDisplayRows().map(e=>`
    <tr class="hover:bg-slate-50 transition cursor-pointer" onclick="viewEmployee('${esc(e.employee_id)}')">
      <td class="px-4 py-3">
        <div class="flex items-center gap-3">
          <div class="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 text-xs font-bold shrink-0">${e.full_name.split(' ').slice(0,2).map(w=>w[0]||'').join('').toUpperCase()}</div>
          <p class="font-medium whitespace-nowrap">${esc(combinedName(e.full_name, e.preferred_name))}</p>
        </div>
      </td>
      ${cols.map(c => `<td class="px-4 py-3 text-sm text-slate-600 whitespace-nowrap">${c.render(e)}</td>`).join('')}
      <td class="px-4 py-3 text-right">
        <svg class="w-4 h-4 text-slate-300 inline" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
      </td>
    </tr>
  `).join('');
}

// ---------------------------------------------------------------------------
// Employee View Modal
// ---------------------------------------------------------------------------
function viewEmployee(id) {
  const e = employees.find(em=>em.employee_id===id); if(!e) return;
  viewingId = id;
  const role = currentUser.role;
  const canWrite  = HR_MANAGE_ROLES.includes(role);
  const canToggle = HR_MANAGER_ONLY_ROLES.includes(role);
  const canNotes  = HR_MANAGE_ROLES.includes(role);
  document.getElementById('viewName').textContent = e.full_name;
  document.getElementById('viewMeta').textContent = `${e.employee_id} · ${e.designation} · ${e.department}`;
  const badge = document.getElementById('viewBadge');
  badge.textContent = e.status;
  badge.className = `badge ${e.status==='Active'?'status-positive':'status-neutral'}`;
  document.getElementById('vt-notes-btn').classList.toggle('hidden', !canNotes);
  // Employee document compliance tracking is HR-only end to end (matches
  // routers/employee_documents.py's require_roles("hr_manager","hr_admin")
  // — narrower than canWrite, which also allows superadmin).
  document.getElementById('vt-documents-btn').classList.toggle('hidden', !HR_STAFF_ROLES.includes(role));
  // FR (facial-recognition attendance kiosk) consent — same tier as
  // Activate/Deactivate (canToggle), matching the backend's
  // employees.manage_recognition_consent permission-matrix entry.
  document.getElementById('vt-consent-btn').classList.toggle('hidden', !canToggle);
  document.getElementById('vt-consent').innerHTML = `
    <div class="max-w-xl">
      <p class="text-xs text-slate-400 mb-4">Controls what the FR facial-recognition attendance kiosk integration may do with this employee's data. Everything starts off — recognition, greetings, and birthday messages are opt-in only, never assumed.</p>
      <label class="flex items-start gap-3 py-3 border-b border-slate-100 cursor-pointer">
        <input type="checkbox" id="consentRecognition" class="mt-1" ${e.consent_recognition?'checked':''}/>
        <div>
          <p class="text-sm font-medium text-slate-800">Recognition</p>
          <p class="text-xs text-slate-500">Allow the FR kiosk to enrol and recognise this employee's face for clock-in/out. Off means FR must not enrol or match them at all.</p>
        </div>
      </label>
      <label class="flex items-start gap-3 py-3 border-b border-slate-100 cursor-pointer">
        <input type="checkbox" id="consentDisplayName" class="mt-1" ${e.consent_display_name?'checked':''}/>
        <div>
          <p class="text-sm font-medium text-slate-800">Display Name Greeting</p>
          <p class="text-xs text-slate-500">Show a "Hi ${esc(e.preferred_name||e.full_name)}" greeting on the kiosk/TV when they clock in. Off means they clock in silently.</p>
        </div>
      </label>
      <label class="flex items-start gap-3 py-3 cursor-pointer">
        <input type="checkbox" id="consentDob" class="mt-1" ${e.consent_dob?'checked':''}/>
        <div>
          <p class="text-sm font-medium text-slate-800">Birthday Greeting</p>
          <p class="text-xs text-slate-500">Show a birthday greeting on their birthday, even if a date of birth is on file. Off means no birthday greeting regardless.</p>
        </div>
      </label>
      <div class="mt-5 flex items-center gap-3">
        <button onclick="saveConsent()" class="btn-primary text-sm">Save Consent Settings</button>
        <span id="consentSaveStatus" class="text-xs"></span>
      </div>
    </div>
  `;
  document.getElementById('noteForm').classList.toggle('hidden', !canNotes);
  document.getElementById('viewEditBtn').classList.toggle('hidden', !canWrite);
  document.getElementById('viewToggleBtn').classList.toggle('hidden', !canToggle);
  document.getElementById('viewFileResignBtn').classList.toggle('hidden', !canWrite || e.status !== 'Active');
  // Shown once a probation end date is on file at all — HR's own signal
  // that this employee is (or was) on probation; not gated on the date
  // having passed, since confirming is an explicit HR decision, not
  // something this app infers automatically (no cron jobs — see CLAUDE.md).
  document.getElementById('viewConfirmProbationBtn')?.classList.toggle('hidden',
    !canWrite || e.status !== 'Active' || !e.probation_end_date);
  const tb = document.getElementById('viewToggleBtn');
  tb.textContent = e.status==='Active' ? 'Deactivate' : 'Activate';
  tb.style.color = e.status==='Active' ? '#dc2626' : '#059669';
  const reportsToEmp = e.reports_to ? (employees||[]).find(x=>x.employee_id===e.reports_to) : null;
  const rt = e.reports_to===e.employee_id ? '⭐ CEO / Top of Org'
    : (e.reports_to ? `${reportsToEmp?displayName(reportsToEmp.full_name,reportsToEmp.preferred_name):e.reports_to} (${e.reports_to})` : '—');
  document.getElementById('vt-personal').innerHTML = vgrid([
    ['Full Name',e.full_name,false,true],['Preferred Name',e.preferred_name||'—'],
    ['IC Number',e.ic_number,true],['Passport No.',e.passport_number||'—'],
    ['Nationality',e.nationality],['Race',e.race],['Religion',e.religion],['Gender',e.gender],
    ['Date of Birth',fmtDate(e.date_of_birth)],['Marital Status',e.marital_status],
    ['Personal Email',e.personal_email||'—'],['Phone',e.phone],
    ['Address',e.address||'—',false,true],
  ]);
  document.getElementById('vt-employment').innerHTML = vgrid([
    ['Department',e.department],['Designation',e.designation],
    ['Employment Type',e.employment_type],['Start Date',fmtDate(e.start_date)],
    ['Probation End',fmtDate(e.probation_end_date)],['Contract End',fmtDate(e.contract_end_date)],
    ['Resign Date',fmtDate(e.resign_date)],['Last Working Day',fmtDate(e.last_working_day)],
    ['Work Email',e.work_email||'—'],['Reports To',rt],
  ]) + `<div id="relatedContracts" class="mt-6"></div>`;
  loadRelatedContracts(e.employee_id);
  document.getElementById('vt-statutory').innerHTML = vgrid([
    ['EPF Number',e.epf_number||'—',true],['SOCSO Number',e.socso_number||'—',true],
    ['Income Tax No.',e.income_tax_number||'—',true],
    ['Basic Salary',e.basic_salary?fmtCurrency(e.basic_salary):'—'],
    ['Bank Name',e.bank_name||'—'],['Bank Account',e.bank_account||'—',true],
  ]);
  loadEmployeeLocations(id);
  loadEmployeeCompensationTab(id);
  switchViewTab('vt-personal');
  document.getElementById('viewModal').classList.remove('hidden');
}

function vgrid(fields) {
  return `<div class="grid grid-cols-2 md:grid-cols-3 gap-x-6 gap-y-4">${
    fields.map(([label,value,mono,wide])=>`
      <div class="${wide?'col-span-2 md:col-span-3':''}">
        <p class="text-xs font-medium text-slate-400 uppercase tracking-wider mb-1">${label}</p>
        <p class="text-sm text-slate-800 ${mono?'font-mono':''}">${esc(String(value??'—'))}</p>
      </div>`).join('')
  }</div>`;
}

async function switchViewTab(name) {
  VIEW_TABS.forEach(t=>{
    document.getElementById(t)?.classList.toggle('hidden',t!==name);
    const btn=document.querySelector(`[data-vtab="${t}"]`);
    if(btn) btn.classList.toggle('active',t===name);
  });
  if(name==='vt-notes') loadNotes();
  // employee-documents.js is lazy-loaded (Speed Audit item 7 — HR-only,
  // this tab's button is itself hidden for non-HR-staff roles already).
  if(name==='vt-documents') { await ensureModuleLoaded('employee-documents'); loadEmployeeDocuments(viewingId); }
  closeViewTabMenu();
}

// Sections drawer (mobile/narrow only) — mirrors app-init.js's
// openBurgerMenu/closeBurgerMenu/toggleBurgerMenu for the main shell's
// sidebar, scoped to this modal's own drawer/overlay instead.
function openViewTabMenu() {
  document.getElementById('viewTabDrawer')?.classList.remove('-translate-x-full');
  document.getElementById('viewTabOverlay')?.classList.remove('hidden');
}
function closeViewTabMenu() {
  if (window.innerWidth >= 640) return;
  document.getElementById('viewTabDrawer')?.classList.add('-translate-x-full');
  document.getElementById('viewTabOverlay')?.classList.add('hidden');
}
function toggleViewTabMenu() {
  const isOpen = !document.getElementById('viewTabDrawer')?.classList.contains('-translate-x-full');
  if (isOpen) closeViewTabMenu(); else openViewTabMenu();
}

function closeViewModal() { closeModal('viewModal', () => { viewingId=null; closeViewTabMenu(); }); }

async function loadEmployeeLocations(empId) {
  const el = document.getElementById('vt-locations');
  if (!el) return;
  try {
    const res = await api(`/api/employees/${empId}/locations`);
    if (!res || !res.ok) {
      el.innerHTML = '<p class="text-slate-500">No locations assigned</p>';
      return;
    }
    const data = await res.json();
    if (!data.locations || data.locations.length === 0) {
      el.innerHTML = '<p class="text-slate-500">No locations assigned</p>';
      return;
    }
    el.innerHTML = `
      <div class="space-y-4">
        <h3 class="font-medium text-slate-800">Location Assignments</h3>
        <div class="grid gap-3">
          ${data.locations.map(loc => `
            <div class="border border-slate-200 rounded-lg p-4 hover:bg-slate-50 transition">
              <div class="flex items-start justify-between">
                <div>
                  <p class="font-medium text-slate-800">${esc(loc.name)}</p>
                  <p class="text-xs text-slate-500 mt-1">
                    <span class="inline-block mr-3">📍 ${esc(loc.city)}</span>
                    <span class="inline-block">${esc(loc.state)}</span>
                  </p>
                  <div class="mt-2 space-y-1 text-sm text-slate-600">
                    <p><strong>Type:</strong> ${esc(loc.assignment_type)}</p>
                    <p><strong>Start:</strong> ${fmtDate(loc.start_date)}</p>
                    ${loc.end_date ? `<p><strong>End:</strong> ${fmtDate(loc.end_date)}</p>` : ''}
                    <p><strong>Status:</strong> <span class="badge ${loc.is_active ? 'status-positive' : 'status-neutral'}">${loc.is_active ? 'Active' : 'Inactive'}</span></p>
                  </div>
                </div>
              </div>
            </div>
          `).join('')}
        </div>
      </div>
    `;
  } catch (err) {
    console.error('Error loading locations:', err);
    el.innerHTML = '<p class="text-red-600">Error loading locations</p>';
  }
}

async function loadRelatedContracts(empId) {
  const el=document.getElementById('relatedContracts');
  if(!el) return;
  const canRehire=HR_MANAGE_ROLES.includes(currentUser?.role);
  try {
    const r=await api(`/api/employees/${empId}/related-contracts`);
    if(!r.ok){el.innerHTML='';return;}
    const contracts=await r.json();
    const STATUS_COLOR={'Active':'status-positive','Inactive':'status-neutral'};
    const TYPE_COLOR={'Permanent':'bg-blue-100 text-blue-700','Contract':'bg-orange-100 text-orange-700','Part-Time':'bg-purple-100 text-purple-700','Internship':'bg-yellow-100 text-yellow-700'};
    el.innerHTML=`
      <div class="border-t border-slate-200 pt-5">
        <div class="flex items-center justify-between mb-3">
          <p class="text-xs font-semibold text-slate-400 uppercase tracking-wide">Other Contracts — Same Person</p>
          ${canRehire?`<button onclick="startRehire('${empId}')" class="btn-primary text-xs px-3 py-1.5">+ Rehire</button>`:''}
        </div>
        ${contracts.length?`<div class="space-y-2">${contracts.map(c=>`
          <div class="flex items-center gap-3 rounded-lg border border-slate-100 bg-slate-50 px-4 py-3 cursor-pointer hover:bg-slate-100 transition" onclick="closeViewModal();viewEmployee('${c.employee_id}')">
            <div class="flex-1 min-w-0">
              <div class="flex items-center gap-2 flex-wrap">
                <span class="text-sm font-medium text-slate-700">${esc(c.employee_id)}</span>
                <span class="badge text-xs ${TYPE_COLOR[c.employment_type]||'bg-slate-100 text-slate-600'}">${esc(c.employment_type)}</span>
                <span class="badge text-xs ${STATUS_COLOR[c.status]||'bg-slate-100 text-slate-600'}">${esc(c.status)}</span>
              </div>
              <p class="text-xs text-slate-500 mt-0.5">${esc(c.designation)} · ${esc(c.department)}</p>
              <p class="text-xs text-slate-400 mt-0.5">${fmtDate(c.start_date)}${c.contract_end_date?' → '+fmtDate(c.contract_end_date):' → present'}</p>
            </div>
            <svg class="w-4 h-4 text-slate-300 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
          </div>`).join('')}</div>`
        :`<p class="text-xs text-slate-400">No other contracts on record for this person.</p>${canRehire?'':`<p class="text-xs text-slate-400 mt-1">Contact HR to process a rehire.</p>`}`}
      </div>`;
  } catch(e){ el.innerHTML=''; }
}

async function startRehire(fromEmpId) {
  const r=await api(`/api/employees/${fromEmpId}/rehire-prefill`);
  if(!r.ok) return;
  const pre=await r.json();
  // Open modal first, then close view so re-renders don't dismiss it
  openAddModal();
  document.getElementById('viewModal').classList.add('hidden'); viewingId=null;
  // Fill personal fields after modal opens
  await new Promise(res=>setTimeout(res,50));
  const fields={
    fFullName:pre.full_name, fPreferredName:pre.preferred_name||'',
    fIcNumber:pre.ic_number, fPassportNumber:pre.passport_number||'',
    fNationality:pre.nationality||'Malaysian',
    fPersonalEmail:pre.personal_email||'', fPhone:pre.phone||'',
    fAddress:pre.address||''
  };
  Object.entries(fields).forEach(([id,val])=>{
    const el=document.getElementById(id);
    if(el) el.value=val||'';
  });
  // Set select fields
  ['fGender','fRace','fReligion','fMaritalStatus'].forEach(id=>{
    const el=document.getElementById(id);
    const val={fGender:pre.gender,fRace:pre.race,fReligion:pre.religion,fMaritalStatus:pre.marital_status}[id];
    if(el&&val) el.value=val;
  });
  if(pre.date_of_birth) document.getElementById('fDateOfBirth').value=pre.date_of_birth;
  // Switch to personal tab so user sees the prefilled data
  switchTab('personal');
  // Add a banner so user knows this is a rehire
  const form=document.getElementById('empForm');
  if(form&&!document.getElementById('rehireBanner')){
    const banner=document.createElement('div');
    banner.id='rehireBanner';
    banner.className='mx-6 mt-4 px-4 py-3 bg-blue-50 border border-blue-200 rounded-lg text-sm text-blue-700';
    banner.innerHTML=`<strong>Rehire:</strong> Personal details pre-filled from ${esc(fromEmpId)}. Assign a new Employee ID and update contract details.`;
    form.prepend(banner);
  }
}

function editFromView() {
  const e=employees.find(em=>em.employee_id===viewingId); if(!e) return;
  closeViewModal(); openEditModal(e);
}

async function toggleStatusFromView() {
  const e=employees.find(em=>em.employee_id===viewingId); if(!e) return;
  const newStatus=e.status==='Active'?'Inactive':'Active';
  const res=await api(`/api/employees/${viewingId}/status`,{method:'PATCH',body:JSON.stringify({status:newStatus})});
  if(res?.ok){
    const updated=await res.json();
    const idx=employees.findIndex(em=>em.employee_id===viewingId);
    if(idx>=0) employees[idx]=updated;
    closeViewModal(); filterEmployees(); renderDashboard();
  }
}

async function saveConsent() {
  const statusEl=document.getElementById('consentSaveStatus');
  statusEl.textContent='Saving…'; statusEl.className='text-xs text-slate-400';
  const body={
    consent_recognition: document.getElementById('consentRecognition').checked,
    consent_display_name: document.getElementById('consentDisplayName').checked,
    consent_dob: document.getElementById('consentDob').checked,
  };
  const res=await api(`/api/employees/${viewingId}/consent`,{method:'PATCH',body:JSON.stringify(body)});
  if(!res?.ok){
    statusEl.textContent='Failed to save'; statusEl.className='text-xs text-red-600';
    return;
  }
  const updated=await res.json();
  const idx=employees.findIndex(em=>em.employee_id===viewingId);
  if(idx>=0) employees[idx]={...employees[idx], ...updated};
  statusEl.textContent='Saved'; statusEl.className='text-xs text-emerald-600';
  setTimeout(()=>{ if(statusEl.textContent==='Saved') statusEl.textContent=''; }, 2000);
}

