;
// ---- ld.js ----
// Learning & Development
// ---------------------------------------------------------------------------
let ldCoursesCache=[], ldCatFilter='', ldEnrollFilter='', ldEnrollData=[];
// Sort-only, like the Projects list (timesheet.js) — the catalog has no
// pagination UI, and an institution's course count is small enough that
// showing everything at once (rather than paging) matches how the rest
// of L&D's own tables (My Trainings, below) already behave.
const ldCourseList = createListState({ sortKey: 'title', pageSize: Number.MAX_SAFE_INTEGER });
const LD_COURSE_COLUMNS = [
  { key:'title', label:'Course', sortKey:'title' },
  { key:'category', label:'Category', sortKey:'category' },
  { key:'cost', label:'Cost', sortKey:'cost' },
];
const ldEnrollList = createListState({
  sortKey: 'employee_name',
  pageSize: Number.MAX_SAFE_INTEGER,
  sortValue: (en, key) => key === 'progress' ? (en.module_count > 0 ? en.modules_viewed / en.module_count : -1) : en[key],
});
const LD_ENROLL_COLUMNS = [
  { key:'employee_name', label:'Employee', sortKey:'employee_name' },
  { key:'department', label:'Department', sortKey:'department' },
  { key:'course_title', label:'Course', sortKey:'course_title' },
  { key:'course_category', label:'Category', sortKey:'course_category' },
  { key:'status', label:'Status', sortKey:'status' },
  { key:'progress', label:'Progress', sortKey:'progress' },
  { key:'created_at', label:'Requested', sortKey:'created_at' },
  { key:'completed_at', label:'Completed', sortKey:'completed_at' },
];
const LD_CATEGORY_LABELS={mandatory:'Mandatory',professional_development:'Professional Dev',certification:'Certification'};
const LD_CATEGORY_COLORS={mandatory:'bg-red-100 text-red-700',professional_development:'bg-blue-100 text-blue-700',certification:'bg-purple-100 text-purple-700'};
const LD_STATUS_COLORS={'Pending Approval':'status-pending','Approved':'status-info','Rejected':'status-negative','In Progress':'status-info','Completed':'status-positive'};

async function loadLdCourses() {
  const bodyEl=document.getElementById('ldCourseTableBody');
  const emptyEl=document.getElementById('ldCourseEmpty');
  bodyEl.innerHTML='<tr><td colspan="4" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  let url='/api/ld/courses';
  if(ldCatFilter) url+=`?category=${encodeURIComponent(ldCatFilter)}`;
  const res=await api(url);
  ldCoursesCache=res&&res.ok?await res.json():[];
  renderLdCourseTable();
}

function setLdCourseSort(key) { ldCourseList.setSort(key); renderLdCourseTable(); }

function renderLdCourseTableHead() {
  document.getElementById('ldCourseTableHead').innerHTML = LD_COURSE_COLUMNS.map(c =>
    `<th class="text-left px-4 py-2.5 text-xs font-semibold text-slate-500 uppercase tracking-wide cursor-pointer select-none whitespace-nowrap" onclick="setLdCourseSort('${c.sortKey}')">${esc(c.label)}<span class="ld-course-sort-arrow" data-sort-key="${c.sortKey}"></span></th>`
  ).join('') + `<th class="px-4 py-2.5"></th>`;
}

function renderLdCourseTable() {
  const bodyEl=document.getElementById('ldCourseTableBody');
  const emptyEl=document.getElementById('ldCourseEmpty');
  renderLdCourseTableHead();
  ldCourseList.updateSortArrows('.ld-course-sort-arrow');
  if(!ldCoursesCache.length){bodyEl.innerHTML='';emptyEl?.classList.remove('hidden');return;}
  emptyEl?.classList.add('hidden');
  const canManage=HR_MANAGE_ROLES.includes(currentUser?.role);
  const { pageItems } = ldCourseList.view(ldCoursesCache);
  bodyEl.innerHTML=pageItems.map(c=>`
    <tr class="border-t border-slate-100">
      <td class="px-4 py-3">
        <p class="font-medium text-slate-800">${esc(c.title)}</p>
        <p class="text-xs text-slate-400 line-clamp-1">${esc(c.description||'')}</p>
      </td>
      <td class="px-4 py-3 whitespace-nowrap"><span class="badge text-xs ${statusColor(LD_CATEGORY_COLORS, c.category)}">${LD_CATEGORY_LABELS[c.category]||c.category}</span></td>
      <td class="px-4 py-3 whitespace-nowrap font-medium ${c.cost>0?'text-amber-600':'text-green-600'}">${c.cost>0?fmtCurrency(c.cost):'Free'}</td>
      <td class="px-4 py-3 text-right whitespace-nowrap">
        <div class="flex items-center justify-end gap-2">
          ${canManage?`<div class="flex items-center gap-1">
            <button onclick="openLdModulesModal(${c.id})" class="text-slate-300 hover:text-green-600" title="Course Content"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s4.832.477 6 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"/></svg></button>
            <button onclick="openLdQuizModal(${c.id})" class="text-slate-300 hover:text-purple-500" title="Manage Quiz"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg></button>
            <button onclick="openLdCourseModal(${c.id})" class="text-slate-300 hover:text-blue-500" title="Edit"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
            <button onclick="deleteLdCourse(${c.id})" class="text-slate-300 hover:text-red-500" title="Remove"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
          </div>
          <button onclick="openLdPreviewQuizModal(${c.id})" class="btn-ghost text-xs px-3 py-1.5 border border-slate-200">Preview</button>`:''}
          <button onclick="openLdEnrollModal(${c.id})" class="btn-primary text-xs px-3 py-1.5">Enroll</button>
        </div>
      </td>
    </tr>`).join('');
}

function setLdCatFilter(cat) {
  ldCatFilter=cat;
  document.querySelectorAll('.ld-cat-filter-btn').forEach(b=>b.classList.remove('ld-cat-filter-active'));
  event?.target?.classList?.add('ld-cat-filter-active');
  loadLdCourses();
}

function openLdCourseModal(courseId) {
  const form=document.getElementById('ldCourseModal').querySelector('form');
  form.reset();
  document.getElementById('ldCourseId').value=courseId||'';
  document.getElementById('ldCourseModalTitle').textContent=courseId?'Edit Course':'Add Course';
  if(courseId){
    const c=ldCoursesCache.find(x=>x.id===courseId);
    if(c){
      document.getElementById('ldCourseTitle').value=c.title;
      document.getElementById('ldCourseCategory').value=c.category;
      document.getElementById('ldCourseDesc').value=c.description||'';
      document.getElementById('ldCourseCost').value=c.cost;
    }
  }
  document.getElementById('ldCourseModal').classList.remove('hidden');
}

function closeLdCourseModal() {
  document.getElementById('ldCourseModal').classList.add('hidden');
}

async function submitLdCourse(e) {
  e.preventDefault();
  const id=document.getElementById('ldCourseId').value;
  const body={
    title:document.getElementById('ldCourseTitle').value.trim(),
    category:document.getElementById('ldCourseCategory').value,
    description:document.getElementById('ldCourseDesc').value.trim()||null,
    cost:parseFloat(document.getElementById('ldCourseCost').value)||0,
  };
  const url=id?`/api/ld/courses/${id}`:'/api/ld/courses';
  const res=await api(url,{method:id?'PUT':'POST',body:JSON.stringify(body)});
  if(res?.ok){closeLdCourseModal();loadLdCourses();}
}

async function deleteLdCourse(courseId) {
  if(!confirm('Remove this course from the catalog?')) return;
  await api(`/api/ld/courses/${courseId}`,{method:'DELETE'});
  loadLdCourses();
}

function openLdEnrollModal(courseId) {
  document.getElementById('ldEnrollCourseId').value=courseId;
  document.getElementById('ldEnrollNotes').value='';
  const course=ldCoursesCache.find(c=>c.id===courseId);
  const costNote=document.getElementById('ldEnrollCostNote');
  if(course && course.cost>0){
    costNote.textContent=`This course costs ${fmtCurrency(course.cost)} — enrollment will require manager/HR approval before starting.`;
    costNote.classList.remove('hidden');
  } else {
    costNote.classList.add('hidden');
  }
  const empWrap=document.getElementById('ldEnrollEmpWrap');
  const canManage=HR_AND_MANAGER_ROLES.includes(currentUser?.role);
  if(canManage){
    empWrap.classList.remove('hidden');
    const sel=document.getElementById('ldEnrollEmpId');
    sel.innerHTML=employees.filter(e=>e.status==='Active').map(e=>`<option value="${e.employee_id}">${e.employee_id} — ${esc(displayName(e.full_name,e.preferred_name))}</option>`).join('');
    if(currentUser?.employee_id) sel.value=currentUser.employee_id;
    initEmployeeSearchSelect('ldEnrollEmpId', 'Search employee…');
  } else {
    empWrap.classList.add('hidden');
  }
  document.getElementById('ldEnrollModal').classList.remove('hidden');
}

function closeLdEnrollModal() {
  document.getElementById('ldEnrollModal').classList.add('hidden');
}

async function submitLdEnroll(e) {
  e.preventDefault();
  const courseId=parseInt(document.getElementById('ldEnrollCourseId').value);
  const canManage=HR_AND_MANAGER_ROLES.includes(currentUser?.role);
  const employeeId=canManage?document.getElementById('ldEnrollEmpId').value:currentUser?.employee_id;
  if(!employeeId){alert('No employee selected.');return;}
  const res=await api('/api/ld/enrollments',{method:'POST',body:JSON.stringify({
    employee_id:employeeId, course_id:courseId,
    notes:document.getElementById('ldEnrollNotes').value.trim()||null
  })});
  if(res?.ok){
    closeLdEnrollModal();
    showPage('ld-trainings');
  } else {
    const d=await res.json();
    alert(d.detail||'Failed to enroll');
  }
}

async function loadLdEnrollments() {
  const bodyEl=document.getElementById('ldEnrollTableBody');
  const emptyEl=document.getElementById('ldEnrollmentEmpty');
  bodyEl.innerHTML='<tr><td colspan="9" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  let url='/api/ld/enrollments';
  if(ldEnrollFilter) url+=`?status=${encodeURIComponent(ldEnrollFilter)}`;
  const res=await api(url);
  ldEnrollData=res&&res.ok?await res.json():[];
  renderLdEnrollTable();
}

function setLdSort(key) { ldEnrollList.setSort(key); renderLdEnrollTable(); }

function renderLdEnrollTableHead() {
  document.getElementById('ldEnrollTableHead').innerHTML = LD_ENROLL_COLUMNS.map(c =>
    `<th class="text-left px-4 py-2.5 text-xs font-semibold text-slate-500 uppercase tracking-wide cursor-pointer select-none whitespace-nowrap" onclick="setLdSort('${c.sortKey}')">${esc(c.label)}<span class="ld-sort-arrow" data-sort-key="${c.sortKey}"></span></th>`
  ).join('') + `<th class="px-4 py-2.5"></th>`;
}

function renderLdEnrollTable() {
  const bodyEl=document.getElementById('ldEnrollTableBody');
  const emptyEl=document.getElementById('ldEnrollmentEmpty');
  renderLdEnrollTableHead();
  ldEnrollList.updateSortArrows('.ld-sort-arrow');
  if(!ldEnrollData.length){bodyEl.innerHTML='';emptyEl?.classList.remove('hidden');return;}
  emptyEl?.classList.add('hidden');
  const canApprove=HR_AND_MANAGER_ROLES.includes(currentUser?.role);
  const { pageItems } = ldEnrollList.view(ldEnrollData);
  bodyEl.innerHTML=pageItems.map(en=>{
    const isSelf = currentUser?.role!=='employee' || currentUser?.employee_id===en.employee_id;
    const isOwnEmployeeAccount = currentUser?.role==='employee' && currentUser?.employee_id===en.employee_id;
    const canAct = en.status==='In Progress' && isSelf;
    const hasQuiz = !!en.quiz_id;
    return `<tr class="border-t border-slate-100">
      <td class="px-4 py-3 font-medium text-slate-800 whitespace-nowrap">${esc(displayName(en.employee_name,en.employee_preferred_name))}</td>
      <td class="px-4 py-3 text-slate-600 whitespace-nowrap">${esc(en.department||'—')}</td>
      <td class="px-4 py-3">
        <p class="text-slate-800">${esc(en.course_title)}</p>
        ${hasQuiz?`<span class="badge text-xs bg-purple-100 text-purple-700 mt-1 inline-block">Quiz Required</span>`:''}
      </td>
      <td class="px-4 py-3 whitespace-nowrap"><span class="badge text-xs ${statusColor(LD_CATEGORY_COLORS, en.course_category)}">${LD_CATEGORY_LABELS[en.course_category]||en.course_category}</span></td>
      <td class="px-4 py-3 whitespace-nowrap"><span class="badge ${statusColor(LD_STATUS_COLORS, en.status)}">${en.status}</span></td>
      <td class="px-4 py-3 text-slate-600 whitespace-nowrap">${en.module_count>0?`${en.modules_viewed}/${en.module_count} lessons`:'—'}</td>
      <td class="px-4 py-3 text-slate-600 whitespace-nowrap">${fmtDate(en.created_at)}</td>
      <td class="px-4 py-3 text-slate-600 whitespace-nowrap">${en.completed_at?fmtDate(en.completed_at):'—'}</td>
      <td class="px-4 py-3 text-right whitespace-nowrap">
        ${en.status==='Pending Approval'&&canApprove?`
          <button onclick="updateLdEnrollStatus(${en.id},'Approved')" class="btn-primary text-xs px-3 py-1.5">Approve</button>
          <button onclick="updateLdEnrollStatus(${en.id},'Rejected')" class="btn-ghost text-xs px-3 py-1.5 text-red-600">Reject</button>
        `:''}
        ${en.status!=='Pending Approval'&&en.status!=='Rejected'&&en.module_count>0?`<button onclick="openLdViewerModal(${en.course_id},${en.id},'${esc(en.course_title).replace(/'/g,"\\'")}')" class="btn-ghost text-xs px-3 py-1.5 border border-slate-200">View Course</button>`:''}
        ${en.status==='In Progress'&&hasQuiz&&isOwnEmployeeAccount?`<button onclick="openLdTakeQuizModal(${en.course_id},${en.id})" class="btn-primary text-xs px-3 py-1.5">Take Quiz</button>`:''}
        ${en.status==='In Progress'&&hasQuiz&&!isOwnEmployeeAccount?`<span class="text-xs text-slate-400 italic">Awaiting employee to take quiz</span>`:''}
        ${canAct&&!hasQuiz?`<button onclick="updateLdEnrollStatus(${en.id},'Completed')" class="btn-primary text-xs px-3 py-1.5">Mark Complete</button>`:''}
      </td>
    </tr>`;
  }).join('');
}

function setLdEnrollFilter(status) {
  ldEnrollFilter=status;
  document.querySelectorAll('.ld-enr-filter-btn').forEach(b=>b.classList.remove('ld-enr-filter-active'));
  event?.target?.classList?.add('ld-enr-filter-active');
  loadLdEnrollments();
}

async function updateLdEnrollStatus(enrId, status) {
  const res=await api(`/api/ld/enrollments/${enrId}/status`,{method:'PATCH',body:JSON.stringify({status})});
  if(res?.ok) loadLdEnrollments();
}

// ---------------------------------------------------------------------------
// Quiz Builder (HR)
// ---------------------------------------------------------------------------
let ldQuizQuestionCount=0;

async function openLdQuizModal(courseId) {
  document.getElementById('ldQuizCourseId').value=courseId;
  document.getElementById('ldQuizQuestions').innerHTML='';
  ldQuizQuestionCount=0;
  document.getElementById('ldQuizTitle').value='';
  document.getElementById('ldQuizPassThreshold').value=80;
  document.getElementById('ldQuizMaxAttempts').value=3;
  document.getElementById('ldQuizRandomizeQuestions').checked=false;
  document.getElementById('ldQuizRandomizeOptions').checked=false;
  document.getElementById('ldQuizDeleteBtn').classList.add('hidden');

  const res=await api(`/api/ld/courses/${courseId}/quiz/manage`);
  if(res?.ok){
    const quiz=await res.json();
    document.getElementById('ldQuizTitle').value=quiz.title;
    document.getElementById('ldQuizPassThreshold').value=quiz.pass_threshold;
    document.getElementById('ldQuizMaxAttempts').value=quiz.max_attempts;
    document.getElementById('ldQuizRandomizeQuestions').checked=!!quiz.randomize_questions;
    document.getElementById('ldQuizRandomizeOptions').checked=!!quiz.randomize_options;
    document.getElementById('ldQuizDeleteBtn').classList.remove('hidden');
    quiz.questions.forEach(q=>addLdQuizQuestion(q.question_text, q.options, q.question_type));
  } else {
    addLdQuizQuestion();
  }
  document.getElementById('ldQuizModal').classList.remove('hidden');
}

function closeLdQuizModal() {
  document.getElementById('ldQuizModal').classList.add('hidden');
}

function addLdQuizQuestion(questionText, options, questionType) {
  const idx=ldQuizQuestionCount++;
  const opts=options || [{text:'',is_correct:true},{text:'',is_correct:false}];
  const qtype=questionType||'single';
  const wrap=document.createElement('div');
  wrap.id=`ldQ-${idx}`;
  wrap.dataset.qtype=qtype;
  wrap.className='border border-slate-200 rounded-xl p-4';
  wrap.innerHTML=`
    <div class="flex items-start gap-2 mb-2">
      <input class="inp ldq-text flex-1" placeholder="Question text…" value="${esc(questionText||'')}"/>
      <button type="button" onclick="document.getElementById('ldQ-${idx}').remove()" class="text-slate-300 hover:text-red-500 mt-1.5" title="Remove question"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
    </div>
    <label class="flex items-center gap-2 text-xs text-slate-500 mb-2 cursor-pointer">
      <input type="checkbox" class="ldq-multi-toggle" ${qtype==='multi'?'checked':''} onchange="ldToggleQuestionType(${idx},this.checked)"/> Multiple correct answers
    </label>
    <div class="ldq-options space-y-2">
      ${opts.map((o,i)=>`
        <div class="flex items-center gap-2">
          <input type="${qtype==='multi'?'checkbox':'radio'}" name="ldq-correct-${idx}" class="ldq-correct" ${o.is_correct?'checked':''}/>
          <input class="inp ldq-option-text flex-1 text-sm" placeholder="Option text…" value="${esc(o.text||'')}"/>
          <button type="button" onclick="this.parentElement.remove()" class="text-slate-300 hover:text-red-500" title="Remove option"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
        </div>`).join('')}
    </div>
    <button type="button" onclick="addLdQuizOption(${idx})" class="text-xs text-blue-600 hover:text-blue-700 mt-2">+ Add Option</button>
  `;
  document.getElementById('ldQuizQuestions').appendChild(wrap);
}

function ldToggleQuestionType(idx, isMulti) {
  const wrap=document.getElementById(`ldQ-${idx}`);
  wrap.dataset.qtype=isMulti?'multi':'single';
  wrap.querySelectorAll('.ldq-correct').forEach(el=>{
    const checked=el.checked;
    el.type=isMulti?'checkbox':'radio';
    el.checked=checked;
  });
  if(!isMulti){
    // Switching back to single-answer: keep only the first checked option
    const checked=[...wrap.querySelectorAll('.ldq-correct')].filter(el=>el.checked);
    checked.slice(1).forEach(el=>el.checked=false);
  }
}

function addLdQuizOption(idx) {
  const wrap=document.getElementById(`ldQ-${idx}`);
  const optsEl=wrap.querySelector('.ldq-options');
  const isMulti=wrap.dataset.qtype==='multi';
  const div=document.createElement('div');
  div.className='flex items-center gap-2';
  div.innerHTML=`
    <input type="${isMulti?'checkbox':'radio'}" name="ldq-correct-${idx}" class="ldq-correct"/>
    <input class="inp ldq-option-text flex-1 text-sm" placeholder="Option text…"/>
    <button type="button" onclick="this.parentElement.remove()" class="text-slate-300 hover:text-red-500" title="Remove option"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
  `;
  optsEl.appendChild(div);
}

const submitLdQuiz = guardAsync(async function() {
  const courseId=document.getElementById('ldQuizCourseId').value;
  const title=document.getElementById('ldQuizTitle').value.trim();
  if(!title){alert('Quiz title is required');return;}
  const questions=[...document.querySelectorAll('#ldQuizQuestions > div')].map(qEl=>{
    const question_text=qEl.querySelector('.ldq-text').value.trim();
    const question_type=qEl.dataset.qtype==='multi'?'multi':'single';
    const options=[...qEl.querySelectorAll('.ldq-options > div')].map(oEl=>({
      text: oEl.querySelector('.ldq-option-text').value.trim(),
      is_correct: oEl.querySelector('.ldq-correct').checked
    })).filter(o=>o.text);
    return {question_text, question_type, options};
  }).filter(q=>q.question_text && q.options.length>=2);

  if(!questions.length){alert('Add at least one question with at least 2 options.');return;}
  for(const q of questions){
    const correctCount=q.options.filter(o=>o.is_correct).length;
    if(correctCount===0){alert(`Mark a correct answer for: "${q.question_text}"`);return;}
    if(q.question_type==='single'&&correctCount>1){alert(`"${q.question_text}" is single-answer but has multiple correct options marked. Check "Multiple correct answers" if that's intended.`);return;}
  }

  const body={
    title,
    pass_threshold: parseInt(document.getElementById('ldQuizPassThreshold').value)||80,
    max_attempts: parseInt(document.getElementById('ldQuizMaxAttempts').value)||3,
    randomize_questions: document.getElementById('ldQuizRandomizeQuestions').checked,
    randomize_options: document.getElementById('ldQuizRandomizeOptions').checked,
    questions
  };
  const res=await api(`/api/ld/courses/${courseId}/quiz`,{method:'PUT',body:JSON.stringify(body)});
  if(res?.ok){closeLdQuizModal();loadLdCourses();}
  else{const d=await res.json();alert(d.detail||'Failed to save quiz');}
});

async function deleteLdQuiz() {
  if(!confirm('Remove this quiz? Employees will be able to mark the course complete manually instead.')) return;
  const courseId=document.getElementById('ldQuizCourseId').value;
  await api(`/api/ld/courses/${courseId}/quiz`,{method:'DELETE'});
  closeLdQuizModal();
  loadLdCourses();
}

// ---------------------------------------------------------------------------
// Quiz Taking (Employee)
// ---------------------------------------------------------------------------
async function openLdTakeQuizModal(courseId, enrollmentId) {
  const res=await api(`/api/ld/courses/${courseId}/quiz`);
  if(!res?.ok){alert('Could not load quiz.');return;}
  const quiz=await res.json();
  document.getElementById('ldTakeQuizId').value=quiz.id;
  document.getElementById('ldTakeQuizEnrollId').value=enrollmentId;
  document.getElementById('ldTakeQuizTitle').textContent=quiz.title;
  document.getElementById('ldTakeQuizResult').classList.add('hidden');
  document.getElementById('ldTakeQuizSubmitBtn').classList.remove('hidden');
  document.getElementById('ldTakeQuizQuestions').innerHTML=quiz.questions.map(q=>{
    const isMulti=q.question_type==='multi';
    return `<div data-qid="${q.id}" data-qtype="${isMulti?'multi':'single'}">
      <p class="text-sm font-medium text-slate-800 mb-1">${esc(q.question_text)}</p>
      ${isMulti?`<p class="text-xs text-slate-400 mb-2">Select all that apply</p>`:''}
      <div class="space-y-1.5">
        ${q.options.map(o=>`
          <label class="flex items-center gap-2 text-sm cursor-pointer">
            <input type="${isMulti?'checkbox':'radio'}" name="ldtq-${q.id}" value="${o.id}"/>
            ${esc(o.text)}
          </label>`).join('')}
      </div>
    </div>`;
  }).join('');
  document.getElementById('ldTakeQuizModal').classList.remove('hidden');
}

function closeLdTakeQuizModal() {
  document.getElementById('ldTakeQuizModal').classList.add('hidden');
}

const submitLdQuizAttempt = guardAsync(async function() {
  const quizId=document.getElementById('ldTakeQuizId').value;
  const questionEls=document.querySelectorAll('#ldTakeQuizQuestions > div');
  const answers={};
  let unanswered=false;
  questionEls.forEach(qEl=>{
    const qId=qEl.dataset.qid;
    const checked=[...qEl.querySelectorAll('input:checked')].map(el=>parseInt(el.value));
    if(checked.length) answers[qId]=checked;
    else unanswered=true;
  });
  if(unanswered && !confirm('Some questions are unanswered. Submit anyway?')) return;

  const res=await api(`/api/ld/quizzes/${quizId}/attempts`,{method:'POST',body:JSON.stringify({answers})});
  if(!res?.ok){
    const d=await res.json();
    alert(d.detail||'Failed to submit quiz');
    return;
  }
  const result=await res.json();
  const resultEl=document.getElementById('ldTakeQuizResult');
  resultEl.classList.remove('hidden');
  if(result.passed){
    resultEl.className='mb-4 rounded-xl p-4 text-sm bg-green-50 border border-green-200 text-green-700';
    resultEl.innerHTML=`<strong>Passed!</strong> Score: ${result.score}%. Course marked complete.`;
    document.getElementById('ldTakeQuizSubmitBtn').classList.add('hidden');
  } else {
    const remaining=result.max_attempts - result.attempt_number;
    resultEl.className='mb-4 rounded-xl p-4 text-sm bg-red-50 border border-red-200 text-red-700';
    resultEl.innerHTML=`<strong>Not passed.</strong> Score: ${result.score}%. ${remaining>0?`${remaining} attempt(s) remaining.`:'No attempts remaining.'}`;
    if(remaining<=0) document.getElementById('ldTakeQuizSubmitBtn').classList.add('hidden');
  }
  loadLdEnrollments();
});

// ---------------------------------------------------------------------------
// Course Modules — Editor (HR)
// ---------------------------------------------------------------------------
let ldModuleCount=0;

async function openLdModulesModal(courseId) {
  document.getElementById('ldModulesCourseId').value=courseId;
  document.getElementById('ldModulesList').innerHTML='';
  ldModuleCount=0;
  const course=ldCoursesCache.find(c=>c.id===courseId);
  document.getElementById('ldModulesModalTitle').textContent=`Course Content — ${course?course.title:''}`;
  const res=await api(`/api/ld/courses/${courseId}/modules`);
  if(res?.ok){
    const modules=await res.json();
    modules.forEach(m=>addLdModule(m.content_type, m.title, m.content));
  }
  document.getElementById('ldModulesModal').classList.remove('hidden');
}

function closeLdModulesModal() {
  document.getElementById('ldModulesModal').classList.add('hidden');
}

function addLdModule(type, title, content) {
  const idx=ldModuleCount++;
  const wrap=document.createElement('div');
  wrap.id=`ldM-${idx}`;
  wrap.dataset.contentType=type;
  wrap.className='border border-slate-200 rounded-xl p-4';
  wrap.innerHTML=`
    <div class="flex items-center gap-2 mb-2">
      <span class="badge text-xs ${type==='video'?'bg-rose-100 text-rose-700':'bg-slate-100 text-slate-600'}">${type==='video'?'Video':'Text'}</span>
      <input class="inp ldm-title flex-1" placeholder="Lesson title…" value="${esc(title||'')}"/>
      <button type="button" onclick="ldMoveModule(${idx},-1)" class="text-slate-300 hover:text-blue-500" title="Move up"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 15l7-7 7 7"/></svg></button>
      <button type="button" onclick="ldMoveModule(${idx},1)" class="text-slate-300 hover:text-blue-500" title="Move down"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg></button>
      <button type="button" onclick="document.getElementById('ldM-${idx}').remove()" class="text-slate-300 hover:text-red-500" title="Remove"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
    </div>
    ${type==='video'
      ?`<input class="inp ldm-content text-sm" placeholder="Video URL (YouTube / Vimeo / direct link)…" value="${esc(content||'')}"/>
        <p class="text-xs text-slate-400 mt-1">YouTube links are embedded as a player; other links open in a new tab.</p>`
      :`<textarea class="inp ldm-content text-sm" rows="4" placeholder="Lesson content…">${esc(content||'')}</textarea>`}
  `;
  document.getElementById('ldModulesList').appendChild(wrap);
}

function ldMoveModule(idx, dir) {
  const el=document.getElementById(`ldM-${idx}`);
  if(!el) return;
  if(dir<0 && el.previousElementSibling) el.parentElement.insertBefore(el, el.previousElementSibling);
  if(dir>0 && el.nextElementSibling) el.parentElement.insertBefore(el.nextElementSibling, el);
}

const submitLdModules = guardAsync(async function() {
  const courseId=document.getElementById('ldModulesCourseId').value;
  const modules=[...document.querySelectorAll('#ldModulesList > div')].map(el=>({
    title: el.querySelector('.ldm-title').value.trim(),
    content_type: el.dataset.contentType,
    content: el.querySelector('.ldm-content').value.trim()||null
  })).filter(m=>m.title);
  const res=await api(`/api/ld/courses/${courseId}/modules`,{method:'PUT',body:JSON.stringify({modules})});
  if(res?.ok){closeLdModulesModal();loadLdCourses();}
  else{const d=await res.json();alert(d.detail||'Failed to save content');}
});

// ---------------------------------------------------------------------------
// Course Modules — Viewer (Employee)
// ---------------------------------------------------------------------------
function ldYoutubeEmbed(url) {
  const m=url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([\w-]{11})/);
  return m?`https://www.youtube.com/embed/${m[1]}`:null;
}

// Renders a single module's body (video embed/link, or plain text) —
// shared by the real Course Viewer (employee, enrollment-bound, below)
// and the HR Preview modal, which has no enrollment behind it and so
// never has viewed/progress state to render alongside this.
function ldModuleContentHtml(m) {
  if(m.content_type==='video'&&m.content){
    const embed=ldYoutubeEmbed(m.content);
    return embed
      ?`<div class="aspect-video rounded-lg overflow-hidden bg-slate-100"><iframe src="${embed}" class="w-full h-full" frameborder="0" allowfullscreen></iframe></div>`
      :`<a href="${esc(m.content)}" target="_blank" rel="noopener" class="text-sm text-blue-600 hover:underline">Open video ↗</a>`;
  }
  return `<p class="text-sm text-slate-600 whitespace-pre-wrap">${esc(m.content||'')}</p>`;
}

async function openLdViewerModal(courseId, enrollmentId, courseTitle) {
  const res=await api(`/api/ld/courses/${courseId}/modules?enrollment_id=${enrollmentId}`);
  if(!res?.ok){alert('Could not load course content.');return;}
  const modules=await res.json();
  document.getElementById('ldViewerTitle').textContent=courseTitle||'Course';
  const viewed=modules.filter(m=>m.viewed).length;
  document.getElementById('ldViewerProgress').textContent=`${viewed} / ${modules.length} lessons viewed`;
  const isOwn=currentUser?.role==='employee';
  document.getElementById('ldViewerBody').innerHTML=modules.map(m=>`
    <div class="border border-slate-200 rounded-xl p-4" id="ldv-${m.id}">
      <div class="flex items-center justify-between gap-2 mb-2">
        <p class="font-medium text-slate-800 text-sm">${esc(m.title)}</p>
        ${m.viewed
          ?`<span class="badge text-xs status-positive">✓ Viewed</span>`
          :isOwn?`<button onclick="markLdModuleViewed(${enrollmentId},${m.id},${courseId},'${esc(courseTitle||'').replace(/'/g,"\\'")}')" class="btn-ghost text-xs px-2 py-1 border border-slate-200">Mark as viewed</button>`
          :`<span class="badge text-xs status-neutral">Not viewed</span>`}
      </div>
      ${ldModuleContentHtml(m)}
    </div>`).join('')||'<p class="text-sm text-slate-400 text-center py-8">No content in this course yet.</p>';
  document.getElementById('ldViewerModal').classList.remove('hidden');
}

function closeLdViewerModal() {
  document.getElementById('ldViewerModal').classList.add('hidden');
  loadLdEnrollments();
}

async function markLdModuleViewed(enrollmentId, moduleId, courseId, courseTitle) {
  const res=await api(`/api/ld/enrollments/${enrollmentId}/modules/${moduleId}/viewed`,{method:'POST'});
  if(res?.ok) openLdViewerModal(courseId, enrollmentId, courseTitle);
}

// ---------------------------------------------------------------------------
// Quiz Preview (HR test-run — graded client-side, nothing persisted)
// ---------------------------------------------------------------------------
let ldPreviewAnswerKey={};
window.ldPreviewCourseId=null;

function ldShuffle(arr) {
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}

async function openLdPreviewQuizModal(courseId) {
  window.ldPreviewCourseId=courseId;
  document.getElementById('ldPreviewQuizResult').classList.add('hidden');
  document.getElementById('ldPreviewQuizSubmitBtn').classList.remove('hidden');
  document.getElementById('ldPreviewQuizRetryBtn').classList.add('hidden');
  const course=ldCoursesCache.find(c=>c.id===courseId);
  document.getElementById('ldPreviewQuizTitle').textContent=`Course Preview — ${course?course.title:''}`;

  // Course Content — same rendering as the real Course Viewer
  // (ldModuleContentHtml), just with no viewed/progress state: a preview
  // has no real enrollment behind it, so there's nothing to track.
  const modRes=await api(`/api/ld/courses/${courseId}/modules`);
  const modules=modRes?.ok?await modRes.json():[];
  document.getElementById('ldPreviewContent').innerHTML=modules.map(m=>`
    <div class="border border-slate-200 rounded-xl p-4">
      <p class="font-medium text-slate-800 text-sm mb-2">${esc(m.title)}</p>
      ${ldModuleContentHtml(m)}
    </div>`).join('')||'<p class="text-sm text-slate-400 text-center py-6">No content in this course yet.</p>';

  const res=await api(`/api/ld/courses/${courseId}/quiz/manage`);
  if(!res?.ok){
    document.getElementById('ldPreviewQuizQuestions').innerHTML='<p class="text-sm text-slate-400 text-center py-8">This course has no quiz yet.</p>';
    document.getElementById('ldPreviewQuizSubmitBtn').classList.add('hidden');
    document.getElementById('ldPreviewQuizModal').classList.remove('hidden');
    return;
  }
  const quiz=await res.json();
  let questions=quiz.questions;
  if(quiz.randomize_questions) questions=ldShuffle(questions);

  ldPreviewAnswerKey={};
  document.getElementById('ldPreviewQuizQuestions').innerHTML=questions.map(q=>{
    const isMulti=q.question_type==='multi';
    let opts=q.options;
    if(quiz.randomize_options) opts=ldShuffle(opts);
    ldPreviewAnswerKey[q.id]=opts.filter(o=>o.is_correct).map(o=>o.id);
    return `<div data-qid="${q.id}" data-qtype="${isMulti?'multi':'single'}" id="ldpq-${q.id}">
      <p class="text-sm font-medium text-slate-800 mb-1">${esc(q.question_text)}</p>
      ${isMulti?`<p class="text-xs text-slate-400 mb-2">Select all that apply</p>`:''}
      <div class="space-y-1.5 ldpq-options">
        ${opts.map(o=>`
          <label class="flex items-center gap-2 text-sm cursor-pointer" data-oid="${o.id}">
            <input type="${isMulti?'checkbox':'radio'}" name="ldpq-${q.id}" value="${o.id}"/>
            <span class="ldpq-option-label">${esc(o.text)}</span>
          </label>`).join('')}
      </div>
    </div>`;
  }).join('');
  document.getElementById('ldPreviewQuizModal').classList.remove('hidden');
}

function closeLdPreviewQuizModal() {
  document.getElementById('ldPreviewQuizModal').classList.add('hidden');
}

function submitLdQuizPreview() {
  const questionEls=document.querySelectorAll('#ldPreviewQuizQuestions > div');
  let correctCount=0;
  questionEls.forEach(qEl=>{
    const qId=qEl.dataset.qid;
    const selected=[...qEl.querySelectorAll('input:checked')].map(el=>parseInt(el.value));
    const correctIds=ldPreviewAnswerKey[qId]||[];
    const isCorrect=selected.length===correctIds.length && selected.every(id=>correctIds.includes(id));
    if(isCorrect) correctCount++;
    // Mark each option: green if correct answer, red ring if wrongly selected
    qEl.querySelectorAll('.ldpq-options > label').forEach(lbl=>{
      const oid=parseInt(lbl.dataset.oid);
      const wasSelected=selected.includes(oid);
      const isRight=correctIds.includes(oid);
      lbl.classList.remove('bg-green-50','bg-red-50','rounded-lg','px-2','py-1','-mx-2');
      if(isRight){ lbl.classList.add('bg-green-50','rounded-lg','px-2','py-1','-mx-2'); }
      else if(wasSelected){ lbl.classList.add('bg-red-50','rounded-lg','px-2','py-1','-mx-2'); }
    });
    qEl.querySelectorAll('input').forEach(inp=>inp.disabled=true);
  });
  const total=questionEls.length;
  const score=total?Math.round((correctCount/total)*100):0;
  const resultEl=document.getElementById('ldPreviewQuizResult');
  resultEl.classList.remove('hidden');
  resultEl.className=`mb-4 rounded-xl p-4 text-sm ${score>=80?'bg-green-50 border border-green-200 text-green-700':'bg-amber-50 border border-amber-200 text-amber-700'}`;
  resultEl.innerHTML=`<strong>Preview result:</strong> ${correctCount}/${total} correct (${score}%). This was not recorded — correct answers are highlighted in green, wrong picks in red.`;
  document.getElementById('ldPreviewQuizSubmitBtn').classList.add('hidden');
  document.getElementById('ldPreviewQuizRetryBtn').classList.remove('hidden');
}

;
// ---- leave.js ----
// Leave / Holiday Manager
// ---------------------------------------------------------------------------
let leaveTypesCache=[], leaveFilter='', leaveApprovalFilter='Pending Approval', leaveHolidaysCache=[];
// Leave Approvals — server-paginated (routers/leave.py's optional
// limit/offset/sort_by/sort_dir + X-Total-Count header), mirroring
// Timesheet Approvals' pattern. My Leave (loadLeaveApplications above)
// hits the same endpoint with no limit at all, for one employee's own
// bounded history, and is unaffected.
let leaveApprovalRowsCache=[];
let leaveApprovalPage=1, leaveApprovalPageSize=50, leaveApprovalTotal=0;
let leaveApprovalSortKey='created_at', leaveApprovalSortDir='desc';
let leaveApprovalRequestSeq=0;
const LEAVE_STATUS_COLORS={'Pending Approval':'status-pending','Approved':'status-positive','Rejected':'status-negative','Cancelled':'status-neutral'};

function isLeaveManager() {
  return HR_MANAGE_ROLES.includes(currentUser?.role);
}
function canApproveLeave() {
  return HR_AND_MANAGER_ROLES.includes(currentUser?.role);
}

// ---------------------------------------------------------------------------
// My Leave
// ---------------------------------------------------------------------------
async function loadLeaveTypesCache() {
  const res=await api('/api/leave/types');
  leaveTypesCache=res?.ok?await res.json():[];
}

async function loadLeavePage() {
  await loadLeaveTypesCache();
  await loadHolidaysCacheForYear(new Date().getFullYear());
  await renderLeaveBalanceCards();
  await loadLeaveApplications();
}

async function renderLeaveBalanceCards() {
  const wrap=document.getElementById('leaveBalanceCards');
  const empId=currentUser?.employee_id;
  if(!empId){ wrap.innerHTML=''; return; }
  const res=await api(`/api/leave/balances?year=${new Date().getFullYear()}`);
  if(!res?.ok){ wrap.innerHTML=''; return; }
  const balances=await res.json();
  wrap.innerHTML=balances.map(b=>{
    const entitled=b.accrued_days ?? b.entitled_days;
    const available=entitled+b.carried_forward_days-b.used_days;
    return `<div class="bg-white border border-slate-200 rounded-xl p-4">
      <p class="text-xs text-slate-400 uppercase tracking-wide mb-1">${esc(b.leave_type_name)}</p>
      <p class="text-2xl font-semibold text-slate-800">${available}</p>
      <p class="text-xs text-slate-400 mt-1">of ${entitled+b.carried_forward_days} day(s) left</p>
    </div>`;
  }).join('');
}

async function loadLeaveApplications() {
  const listEl=document.getElementById('leaveAppList');
  const emptyEl=document.getElementById('leaveAppEmpty');
  listEl.innerHTML='<p class="text-slate-400 text-sm text-center py-8">Loading…</p>';
  let url='/api/leave/applications';
  if(leaveFilter) url+=`?status=${encodeURIComponent(leaveFilter)}`;
  const res=await api(url);
  if(!res?.ok){ listEl.innerHTML=''; return; }
  const rows=await res.json();
  if(!rows.length){ listEl.innerHTML=''; emptyEl?.classList.remove('hidden'); return; }
  emptyEl?.classList.add('hidden');
  listEl.innerHTML=rows.map(a=>`
    <div class="bg-white border border-slate-200 rounded-xl p-4">
      <div class="flex items-start justify-between gap-3">
        <div class="flex-1 min-w-0">
          <div class="flex items-center gap-2 mb-0.5 flex-wrap">
            <p class="font-medium text-slate-800">${esc(a.leave_type_name)}</p>
            <span class="badge ${statusColor(LEAVE_STATUS_COLORS, a.status)} text-xs">${a.status}</span>
          </div>
          <p class="text-xs text-slate-500">${fmtDate(a.start_date)} → ${fmtDate(a.end_date)} · ${a.days_count} working day(s)${ldHalfDaySuffix(a)}</p>
          ${a.reason?`<p class="text-xs text-slate-400 italic mt-1">${esc(a.reason)}</p>`:''}
          ${a.notes?`<p class="text-xs text-slate-500 mt-1">Note: ${esc(a.notes)}</p>`:''}
          ${a.attachment?`<a href="${a.attachment}" target="_blank" class="text-xs text-blue-600 hover:underline mt-1 inline-block">View attachment</a>`:''}
        </div>
        ${(a.status==='Pending Approval'||a.status==='Approved')?`<button onclick="cancelLeaveApplication(${a.id})" class="text-xs text-red-600 hover:text-red-700 shrink-0">Cancel</button>`:''}
      </div>
      <p class="text-xs text-slate-400 mt-2">Applied ${fmtDate(a.created_at)}</p>
    </div>`).join('');
}

function setLeaveFilter(status) {
  leaveFilter=status;
  document.querySelectorAll('.leave-filter-btn').forEach(b=>b.classList.remove('leave-filter-active'));
  event?.target?.classList?.add('leave-filter-active');
  loadLeaveApplications();
}

async function cancelLeaveApplication(appId) {
  if(!confirm('Cancel this leave application?')) return;
  const res=await api(`/api/leave/applications/${appId}/status`,{method:'PATCH',body:JSON.stringify({status:'Cancelled'})});
  if(res?.ok){ loadLeaveApplications(); renderLeaveBalanceCards(); }
  else { const d=await res.json(); alert(d.detail||'Failed to cancel'); }
}

// ---------------------------------------------------------------------------
// Apply for Leave
// ---------------------------------------------------------------------------
let leaveApplyAttachment=null;
let leaveApplyBalancesCache=[];

async function openLeaveApplyModal() {
  document.getElementById('leaveApplyErr').classList.add('hidden');
  document.getElementById('leaveApplyReason').value='';
  document.getElementById('leaveApplyStart').value='';
  document.getElementById('leaveApplyEnd').value='';
  document.getElementById('leaveApplyStartPeriod').value='';
  document.getElementById('leaveApplyEndPeriod').value='';
  document.getElementById('leaveApplyDayPeriodWrap').classList.add('hidden');
  document.getElementById('leaveApplyAttachFile').value='';
  leaveApplyAttachment=null;

  const empWrap=document.getElementById('leaveApplyEmpWrap');
  if(isLeaveManager()||currentUser?.role==='manager'){
    empWrap.classList.remove('hidden');
    const sel=document.getElementById('leaveApplyEmpId');
    sel.innerHTML=employees.filter(e=>e.status==='Active').map(e=>`<option value="${e.employee_id}">${e.employee_id} — ${esc(displayName(e.full_name,e.preferred_name))}</option>`).join('');
    if(currentUser?.employee_id) sel.value=currentUser.employee_id;
    initEmployeeSearchSelect('leaveApplyEmpId', 'Search employee…');
  } else {
    empWrap.classList.add('hidden');
  }

  const typeSel=document.getElementById('leaveApplyTypeId');
  typeSel.innerHTML=leaveTypesCache.map(t=>{
    const shared=t.shares_entitlement_with_id?leaveTypesCache.find(x=>x.id===t.shares_entitlement_with_id):null;
    const label=shared?`${esc(t.name)} (shares with ${esc(shared.name)})`:`${esc(t.name)} (${t.annual_entitlement}/yr)`;
    return `<option value="${t.id}">${label}</option>`;
  }).join('');

  const empId=(isLeaveManager()||currentUser?.role==='manager')?document.getElementById('leaveApplyEmpId').value:currentUser?.employee_id;
  const res=await api(`/api/leave/balances?year=${new Date().getFullYear()}${empId?`&employee_id=${empId}`:''}`);
  leaveApplyBalancesCache=res?.ok?await res.json():[];

  updateLeaveApplyBalanceNote();
  updateLeaveApplyDayPeriodVisibility();
  document.getElementById('leaveApplyDaysPreview').textContent='';
  await populateLeaveApplyProjectField();
  document.getElementById('leaveApplyModal').classList.remove('hidden');
}

async function populateLeaveApplyProjectField() {
  const wrap=document.getElementById('leaveApplyProjectWrap');
  const sel=document.getElementById('leaveApplyProjectId');
  wrap.classList.add('hidden');
  sel.innerHTML='';
  const needed=await moduleHasProjectManagerStep('leave');
  if(!needed) return;
  const res=await api('/api/projects/mine');
  const myProjects=res?.ok?await res.json():[];
  if(!myProjects.length) return;  // no project to pick — step auto-skips
  sel.innerHTML=myProjects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');
  wrap.classList.remove('hidden');
}

function updateLeaveApplyBalanceNote() {
  const typeId=parseInt(document.getElementById('leaveApplyTypeId').value);
  const type=leaveTypesCache.find(t=>t.id===typeId);
  // A type that shares entitlement with another never has its own balance
  // row — its pool lives under the shared type's id.
  const balanceTypeId=type?.shares_entitlement_with_id||typeId;
  const sharedType=type?.shares_entitlement_with_id?leaveTypesCache.find(t=>t.id===type.shares_entitlement_with_id):null;
  const bal=leaveApplyBalancesCache.find(b=>b.leave_type_id===balanceTypeId);
  const note=document.getElementById('leaveApplyBalanceNote');
  const attachWrap=document.getElementById('leaveApplyAttachWrap');
  attachWrap.classList.toggle('hidden', !type?.requires_attachment);
  document.getElementById('leaveApplyAttachFile').required=!!type?.requires_attachment;
  const sharedSuffix=sharedType?` (shared with ${esc(sharedType.name)})`:'';
  const isMonthly=(sharedType||type)?.accrual_mode==='monthly';
  const period=isMonthly?'accrued so far':'this year';
  if(bal){
    // accrued_days already resolves to the full annual figure for
    // full_year types, and to the pro-rated earned-so-far figure for
    // monthly ones — see _accrued_days in routers/leave.py.
    const available=bal.accrued_days+bal.carried_forward_days-bal.used_days;
    note.textContent=`${available} day(s) available ${period}${sharedSuffix}`;
  } else if(sharedType){
    note.textContent=`${sharedType.annual_entitlement} day(s) available this year (new balance)${sharedSuffix}`;
  } else if(type){
    note.textContent=`${type.annual_entitlement} day(s) available this year (new balance)`;
  } else {
    note.textContent='';
  }
}

function ldLeaveComputeWorkdays(startStr, endStr) {
  if(!startStr||!endStr) return 0;
  const start=new Date(startStr+'T00:00:00'), end=new Date(endStr+'T00:00:00');
  if(end<start) return 0;
  const holidaySet=new Set(leaveHolidaysCache.map(h=>h.date));
  let count=0;
  const d=new Date(start);
  while(d<=end){
    const dow=d.getDay();
    const ds=d.toISOString().slice(0,10);
    if(dow!==0 && dow!==6 && !holidaySet.has(ds)) count++;
    d.setDate(d.getDate()+1);
  }
  return count;
}

// Pure: renders an application's half-day period(s) as a display suffix,
// e.g. " (PM start, AM end)" — "" when neither is set. Shared by both the
// My Leave and Approvals list templates.
function ldHalfDaySuffix(a) {
  const parts=[];
  if(a.start_day_period) parts.push(`${a.start_day_period} start`);
  if(a.end_day_period) parts.push(`${a.end_day_period} end`);
  return parts.length ? ` (${parts.join(', ')})` : '';
}

function ldLeaveComputeCalendarDays(startStr, endStr) {
  if(!startStr||!endStr) return 0;
  const start=new Date(startStr+'T00:00:00'), end=new Date(endStr+'T00:00:00');
  if(end<start) return 0;
  return Math.round((end-start)/86400000)+1;
}

// Pure: how much to subtract from a whole-range day count for the
// half-day period(s) selected — mirrors the backend's _half_day_deduction
// arithmetic (0, 0.5, or 1.0). Kept side-effect-free so it's directly
// testable and reusable from the preview below.
function ldLeaveHalfDayDeduction(start, end, startPeriod, endPeriod) {
  let deduction=0;
  if(startPeriod) deduction+=0.5;
  if(endPeriod && end!==start) deduction+=0.5;
  return deduction;
}

// Shows/hides the Start Day / End Day half-day selectors. The Start Day
// selector (and the wrapper as a whole) appears as soon as a leave type
// with allow_half_day checked is selected — the sole control, see
// routers/leave.py's matching server-side gate; a type's
// count_calendar_days no longer factors in — no need to wait for dates
// to be picked too, since which date it applies to isn't relevant until
// submit. The End Day selector stays gated on both dates being picked
// AND spanning more than one date (mirrors the DB's
// end_day_period-requires-a-range constraint) — showing it before that
// would let someone pick a period for a date that isn't decided yet.
function updateLeaveApplyDayPeriodVisibility() {
  const start=document.getElementById('leaveApplyStart').value;
  const end=document.getElementById('leaveApplyEnd').value;
  const typeId=parseInt(document.getElementById('leaveApplyTypeId').value);
  const type=leaveTypesCache.find(t=>t.id===typeId);
  const wrap=document.getElementById('leaveApplyDayPeriodWrap');
  const endWrap=document.getElementById('leaveApplyEndPeriodWrap');
  const eligible=!!(type && type.allow_half_day);
  wrap.classList.toggle('hidden', !eligible);
  const showEnd=eligible && !!start && !!end && start!==end;
  endWrap.classList.toggle('hidden', !showEnd);
  if(!showEnd) document.getElementById('leaveApplyEndPeriod').value='';
  if(!eligible) document.getElementById('leaveApplyStartPeriod').value='';
}

function updateLeaveApplyDaysPreview() {
  updateLeaveApplyDayPeriodVisibility();
  const start=document.getElementById('leaveApplyStart').value;
  const end=document.getElementById('leaveApplyEnd').value;
  const preview=document.getElementById('leaveApplyDaysPreview');
  if(!start||!end){ preview.textContent=''; return; }
  const typeId=parseInt(document.getElementById('leaveApplyTypeId').value);
  const type=leaveTypesCache.find(t=>t.id===typeId);
  const isCalendar=!!type?.count_calendar_days;
  let days=isCalendar?ldLeaveComputeCalendarDays(start,end):ldLeaveComputeWorkdays(start,end);
  if(type?.allow_half_day){
    const startPeriod=document.getElementById('leaveApplyStartPeriod').value;
    const endPeriod=document.getElementById('leaveApplyEndPeriod').value;
    days-=ldLeaveHalfDayDeduction(start,end,startPeriod,endPeriod);
  }
  preview.textContent=isCalendar
    ?`≈ ${days} calendar day(s) will be deducted (weekends & public holidays included)`
    :`≈ ${days} working day(s) will be deducted (weekends & public holidays excluded)`;
}

function handleLeaveAttachFile(e) {
  const file=e.target.files?.[0];
  if(!file) return;
  if(file.size>500*1024){ alert('File is too large. Please choose a file under ~500KB.'); e.target.value=''; return; }
  const reader=new FileReader();
  reader.onload=()=>{ leaveApplyAttachment=reader.result; };
  reader.readAsDataURL(file);
}

function closeLeaveApplyModal() {
  document.getElementById('leaveApplyModal').classList.add('hidden');
}

async function submitLeaveApplication(e) {
  e.preventDefault();
  const err=document.getElementById('leaveApplyErr');
  err.classList.add('hidden');
  const empId=(isLeaveManager()||currentUser?.role==='manager')?document.getElementById('leaveApplyEmpId').value:currentUser?.employee_id;
  const projectWrap=document.getElementById('leaveApplyProjectWrap');
  const body={
    employee_id: empId,
    leave_type_id: parseInt(document.getElementById('leaveApplyTypeId').value),
    start_date: document.getElementById('leaveApplyStart').value,
    end_date: document.getElementById('leaveApplyEnd').value,
    reason: document.getElementById('leaveApplyReason').value.trim()||null,
    attachment: leaveApplyAttachment,
    project_id: !projectWrap.classList.contains('hidden') && document.getElementById('leaveApplyProjectId').value
      ? parseInt(document.getElementById('leaveApplyProjectId').value) : null,
    start_day_period: document.getElementById('leaveApplyStartPeriod').value||null,
    end_day_period: document.getElementById('leaveApplyEndPeriod').value||null,
  };
  const res=await api('/api/leave/applications',{method:'POST',body:JSON.stringify(body)});
  if(res?.ok){
    closeLeaveApplyModal();
    showPage('leave-my');
  } else {
    const d=await res.json();
    err.textContent=d.detail||'Failed to submit application';
    err.classList.remove('hidden');
  }
}

// ---------------------------------------------------------------------------
// Leave Approvals (manager / HR)
// ---------------------------------------------------------------------------
async function loadLeaveApprovals() {
  const seq=++leaveApprovalRequestSeq; // discards a response that's no longer the latest
  const tbody=document.getElementById('leaveApprovalTableBody');
  tbody.innerHTML='<tr><td colspan="7" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  const offset=(leaveApprovalPage-1)*leaveApprovalPageSize;
  const params=new URLSearchParams({
    limit:String(leaveApprovalPageSize), offset:String(offset),
    sort_by:leaveApprovalSortKey, sort_dir:leaveApprovalSortDir,
  });
  if(leaveApprovalFilter) params.set('status', leaveApprovalFilter);
  const res=await api(`/api/leave/applications?${params}`);
  if(seq!==leaveApprovalRequestSeq) return; // a newer request has since started
  if(!res?.ok){ tbody.innerHTML=''; return; }
  leaveApprovalRowsCache=await res.json();
  leaveApprovalTotal=parseInt(res.headers.get('X-Total-Count')||'0',10);
  renderLeaveApprovalTable();
}

function setLeaveApprovalSort(key) {
  if(leaveApprovalSortKey===key) leaveApprovalSortDir = leaveApprovalSortDir==='asc' ? 'desc' : 'asc';
  else { leaveApprovalSortKey=key; leaveApprovalSortDir='asc'; }
  leaveApprovalPage=1;
  loadLeaveApprovals();
}
function setLeaveApprovalPageSize(size) { leaveApprovalPageSize=parseInt(size)||50; leaveApprovalPage=1; loadLeaveApprovals(); }
function leaveApprovalPagePrev() { if(leaveApprovalPage>1){ leaveApprovalPage--; loadLeaveApprovals(); } }
function leaveApprovalPageNext() {
  const totalPages=Math.max(1, Math.ceil(leaveApprovalTotal/leaveApprovalPageSize));
  if(leaveApprovalPage<totalPages){ leaveApprovalPage++; loadLeaveApprovals(); }
}

function renderLeaveApprovalTable() {
  const tbody=document.getElementById('leaveApprovalTableBody');
  const emptyEl=document.getElementById('leaveApprovalEmpty');
  const pagination=document.getElementById('leaveApprovalPagination');
  document.querySelectorAll('.leave-appr-sort-arrow').forEach(el=>{
    const key=el.dataset.sortKey;
    el.textContent = key===leaveApprovalSortKey ? (leaveApprovalSortDir==='asc'?' ▲':' ▼') : '';
  });

  if(!leaveApprovalRowsCache.length){ tbody.innerHTML=''; emptyEl?.classList.remove('hidden'); pagination?.classList.add('hidden'); return; }
  emptyEl?.classList.add('hidden');
  pagination?.classList.remove('hidden');
  const pageSizeEl=document.getElementById('leaveApprovalPageSize');
  if(pageSizeEl) pageSizeEl.value=String(leaveApprovalPageSize);

  const offset=(leaveApprovalPage-1)*leaveApprovalPageSize;
  const pageInfoEl=document.getElementById('leaveApprovalPageInfo');
  if(pageInfoEl) pageInfoEl.textContent=`${offset+1}-${Math.min(offset+leaveApprovalPageSize, leaveApprovalTotal)} of ${leaveApprovalTotal}`;

  tbody.innerHTML=leaveApprovalRowsCache.map(a=>`
    <tr>
      <td class="px-4 py-3">
        <p class="font-medium">${esc(displayName(a.employee_name, a.employee_preferred_name))}</p>
        <p class="text-xs text-slate-500">${esc(a.department||'')}${a.designation?' · '+esc(a.designation):''}</p>
      </td>
      <td class="px-4 py-3">
        <p>${esc(a.leave_type_name)}</p>
        ${a.reason?`<p class="text-xs text-slate-400 italic mt-0.5 line-clamp-1">${esc(a.reason)}</p>`:''}
        ${a.attachment?`<a href="${a.attachment}" target="_blank" class="text-xs text-blue-600 hover:underline">View attachment</a>`:''}
      </td>
      <td class="px-4 py-3 text-slate-600">${fmtDate(a.start_date)} → ${fmtDate(a.end_date)}</td>
      <td class="px-4 py-3 text-right text-slate-600">${a.days_count}${ldHalfDaySuffix(a)}</td>
      <td class="px-4 py-3"><span class="badge ${statusColor(LEAVE_STATUS_COLORS, a.status)} text-xs">${a.status}</span></td>
      <td class="px-4 py-3 text-slate-500">${fmtDate(a.created_at)}</td>
      <td class="px-4 py-3 text-right">
        ${a.status==='Pending Approval'?(a.is_actionable?`
          <button onclick="reviewLeaveApplication(${a.id},'Approved')" class="text-xs text-emerald-700 hover:underline mr-3">Approve</button>
          <button onclick="reviewLeaveApplication(${a.id},'Rejected')" class="text-xs text-red-700 hover:underline">Reject</button>
        `:`<span class="text-xs text-slate-400">Pending: ${esc(a.pending_with||'—')}</span>`):'<span class="text-xs text-slate-400">—</span>'}
      </td>
    </tr>`).join('');
}

function setLeaveApprovalFilter(status) {
  leaveApprovalFilter=status;
  leaveApprovalPage=1;
  document.querySelectorAll('.leave-appr-filter-btn').forEach(b=>b.classList.remove('leave-appr-filter-active'));
  event?.target?.classList?.add('leave-appr-filter-active');
  loadLeaveApprovals();
}

async function reviewLeaveApplication(appId, status) {
  const res=await api(`/api/leave/applications/${appId}/status`,{method:'PATCH',body:JSON.stringify({status})});
  if(res?.ok) loadLeaveApprovals();
  else { const d=await res.json(); alert(d.detail||'Failed to update'); }
}

// ---------------------------------------------------------------------------
// Holiday Manager
// ---------------------------------------------------------------------------
async function loadHolidaysCacheForYear(year) {
  const res=await api(`/api/holidays?year=${year}`);
  leaveHolidaysCache=res?.ok?await res.json():[];
}

let hmLeaveTypesLoaded=false;

async function loadLeaveHolidaysPage() {
  const yearSel=document.getElementById('holidayYearSelect');
  const curYear=new Date().getFullYear();
  if(!yearSel.options.length){
    yearSel.innerHTML=[curYear-1,curYear,curYear+1,curYear+2].map(y=>`<option value="${y}">${y}</option>`).join('');
    yearSel.value=curYear;
  }
  hmLeaveTypesLoaded=false;
  switchHolidayManagerTab('holidays');
}

function switchHolidayManagerTab(tab) {
  document.getElementById('hmSubTab_holidays').classList.toggle('view-tab-active', tab==='holidays');
  document.getElementById('hmSubTab_leavetypes').classList.toggle('view-tab-active', tab==='leavetypes');
  document.getElementById('hmSubPanel_holidays').classList.toggle('hidden', tab!=='holidays');
  document.getElementById('hmSubPanel_leavetypes').classList.toggle('hidden', tab!=='leavetypes');
  if(tab==='holidays') loadHolidays();
  else if(tab==='leavetypes' && !hmLeaveTypesLoaded){
    hmLeaveTypesLoaded=true;
    loadLeaveTypesForManage();
  }
}

async function loadHolidays() {
  const year=document.getElementById('holidayYearSelect').value;
  await loadHolidaysCacheForYear(year);
  const tbody=document.getElementById('holidayTableBody');
  const emptyEl=document.getElementById('holidayEmpty');
  if(!leaveHolidaysCache.length){
    tbody.innerHTML='';
    emptyEl.classList.remove('hidden');
    return;
  }
  emptyEl.classList.add('hidden');
  const dayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  tbody.innerHTML=leaveHolidaysCache.map(h=>{
    const d=new Date(h.date+'T00:00:00');
    return `<tr class="border-t border-slate-100">
      <td class="px-4 py-2">${fmtDate(h.date)}</td>
      <td class="px-4 py-2 text-slate-500">${dayNames[d.getDay()]}</td>
      <td class="px-4 py-2">${esc(h.name)}</td>
      <td class="px-4 py-2 text-right"><button onclick="deleteHoliday(${h.id})" class="text-slate-300 hover:text-red-500"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button></td>
    </tr>`;
  }).join('');
}

function openHolidayModal() {
  document.getElementById('holidayName').value='';
  document.getElementById('holidayDate').value='';
  document.getElementById('holidayModal').classList.remove('hidden');
}
function closeHolidayModal() { closeModal('holidayModal'); }

async function submitHoliday(e) {
  e.preventDefault();
  const date=document.getElementById('holidayDate').value;
  const body={ name:document.getElementById('holidayName').value.trim(), date, year:parseInt(date.slice(0,4)) };
  const res=await api('/api/holidays',{method:'POST',body:JSON.stringify(body)});
  if(res?.ok){
    closeHolidayModal();
    document.getElementById('holidayYearSelect').value=body.year;
    loadHolidays();
  } else {
    const d=await res.json(); alert(d.detail||'Failed to add holiday');
  }
}

async function deleteHoliday(id) {
  if(!confirm('Remove this holiday?')) return;
  await api(`/api/holidays/${id}`,{method:'DELETE'});
  loadHolidays();
}

// ---------------------------------------------------------------------------
// Leave Types (management, shown under Holiday Manager page)
// ---------------------------------------------------------------------------
async function loadLeaveTypesForManage() {
  await loadLeaveTypesCache();
  const wrap=document.getElementById('leaveTypeList');
  wrap.innerHTML=leaveTypesCache.length?leaveTypesCache.map(t=>{
    const sharedType=t.shares_entitlement_with_id?leaveTypesCache.find(x=>x.id===t.shares_entitlement_with_id):null;
    return `
    <div class="flex items-center gap-2 py-2 border-b border-slate-100">
      <span class="flex-1 text-sm text-slate-700">${esc(t.name)}</span>
      ${sharedType
        ?`<span class="badge text-xs bg-amber-100 text-amber-700">Shares with ${esc(sharedType.name)}</span>`
        :`<span class="text-xs text-slate-400">${t.annual_entitlement} days/yr</span>`}
      ${t.count_calendar_days?'<span class="badge text-xs bg-slate-100 text-slate-600">Calendar days</span>':''}
      ${!t.allow_half_day?'<span class="badge text-xs bg-slate-100 text-slate-600">No half-day</span>':''}
      ${t.accrual_mode==='monthly'?'<span class="badge text-xs bg-teal-100 text-teal-700">Accrues monthly</span>':''}
      ${t.max_days_per_application?`<span class="badge text-xs bg-slate-100 text-slate-600">Max ${t.max_days_per_application}/app</span>`:''}
      ${t.max_days_per_month?`<span class="badge text-xs bg-slate-100 text-slate-600">Max ${t.max_days_per_month}/mo</span>`:''}
      ${t.requires_approval?'<span class="badge text-xs bg-blue-100 text-blue-700">Approval</span>':''}
      ${t.requires_attachment?'<span class="badge text-xs bg-purple-100 text-purple-700">Doc required</span>':''}
      ${t.carry_forward_enabled?`<span class="badge text-xs bg-amber-100 text-amber-700" title="${t.carry_forward_max_days?`Max ${t.carry_forward_max_days} days`:''}${t.carry_forward_max_days&&t.carry_forward_max_percent?' or ':''}${t.carry_forward_max_percent?`Max ${t.carry_forward_max_percent}% of balance`:''}${t.carry_forward_expiry_days?`, expires ${t.carry_forward_expiry_days}d into new year`:''}">Carries forward</span>`:''}
      <button onclick="openLeaveTypeModal(${t.id})" class="text-slate-300 hover:text-blue-500"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
      <button onclick="deleteLeaveType(${t.id})" class="text-slate-300 hover:text-red-500"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
    </div>`;
  }).join(''):'<p class="text-sm text-slate-400 text-center py-4">No leave types yet.</p>';
}

function openLeaveTypeModal(typeId) {
  document.getElementById('leaveTypeId').value=typeId||'';
  document.getElementById('leaveTypeModalTitle').textContent=typeId?'Edit Leave Type':'Add Leave Type';

  // Share-with options: any other active leave type that isn't itself
  // sharing with something (one level deep only — matches backend validation
  // in _validate_shares_entitlement), excluding this type itself.
  const sharesSel=document.getElementById('leaveTypeSharesWith');
  const options=leaveTypesCache.filter(t=>t.id!==typeId&&!t.shares_entitlement_with_id);
  sharesSel.innerHTML='<option value="">— No, tracks its own balance —</option>'
    +options.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');

  if(typeId){
    const t=leaveTypesCache.find(x=>x.id===typeId);
    document.getElementById('leaveTypeName').value=t?.name||'';
    document.getElementById('leaveTypeEntitlement').value=t?.annual_entitlement||14;
    document.getElementById('leaveTypeCountMode').value=t?.count_calendar_days?'calendar':'working';
    document.getElementById('leaveTypeAccrualMode').value=t?.accrual_mode||'full_year';
    document.getElementById('leaveTypeMaxPerApp').value=t?.max_days_per_application||0;
    document.getElementById('leaveTypeMaxPerMonth').value=t?.max_days_per_month||0;
    document.getElementById('leaveTypeRequiresApproval').checked=!!t?.requires_approval;
    document.getElementById('leaveTypeRequiresAttachment').checked=!!t?.requires_attachment;
    document.getElementById('leaveTypeIsPaid').checked=t?.is_paid===undefined?true:!!t.is_paid;
    document.getElementById('leaveTypeAllowHalfDay').checked=t?.allow_half_day===undefined?true:!!t.allow_half_day;
    sharesSel.value=t?.shares_entitlement_with_id||'';
    document.getElementById('leaveTypeCarryForwardEnabled').checked=!!t?.carry_forward_enabled;
    document.getElementById('leaveTypeCarryMaxDays').value=t?.carry_forward_max_days||0;
    document.getElementById('leaveTypeCarryMaxPercent').value=t?.carry_forward_max_percent||0;
    document.getElementById('leaveTypeCarryExpiryDays').value=t?.carry_forward_expiry_days||0;
  } else {
    document.getElementById('leaveTypeName').value='';
    document.getElementById('leaveTypeEntitlement').value=14;
    document.getElementById('leaveTypeCountMode').value='working';
    document.getElementById('leaveTypeAccrualMode').value='full_year';
    document.getElementById('leaveTypeMaxPerApp').value=0;
    document.getElementById('leaveTypeMaxPerMonth').value=0;
    document.getElementById('leaveTypeRequiresApproval').checked=true;
    document.getElementById('leaveTypeRequiresAttachment').checked=false;
    document.getElementById('leaveTypeIsPaid').checked=true;
    document.getElementById('leaveTypeAllowHalfDay').checked=true;
    sharesSel.value='';
    document.getElementById('leaveTypeCarryForwardEnabled').checked=false;
    document.getElementById('leaveTypeCarryMaxDays').value=0;
    document.getElementById('leaveTypeCarryMaxPercent').value=0;
    document.getElementById('leaveTypeCarryExpiryDays').value=0;
  }
  onLeaveTypeSharesChange();
  onLeaveTypeCarryForwardChange();
  document.getElementById('leaveTypeModal').classList.remove('hidden');
}
function closeLeaveTypeModal() { closeModal('leaveTypeModal'); }

function onLeaveTypeSharesChange() {
  const sharing=!!document.getElementById('leaveTypeSharesWith').value;
  document.getElementById('leaveTypeEntitlementWrap').classList.toggle('hidden', sharing);
  document.getElementById('leaveTypeAccrualWrap').classList.toggle('hidden', sharing);
}

function onLeaveTypeCarryForwardChange() {
  const enabled=document.getElementById('leaveTypeCarryForwardEnabled').checked;
  document.getElementById('leaveTypeCarryForwardWrap').classList.toggle('hidden', !enabled);
}

async function submitLeaveType(e) {
  e.preventDefault();
  const id=document.getElementById('leaveTypeId').value;
  const sharesWith=document.getElementById('leaveTypeSharesWith').value;
  const body={
    name: document.getElementById('leaveTypeName').value.trim(),
    annual_entitlement: parseFloat(document.getElementById('leaveTypeEntitlement').value)||0,
    requires_approval: document.getElementById('leaveTypeRequiresApproval').checked,
    requires_attachment: document.getElementById('leaveTypeRequiresAttachment').checked,
    is_paid: document.getElementById('leaveTypeIsPaid').checked,
    allow_half_day: document.getElementById('leaveTypeAllowHalfDay').checked,
    shares_entitlement_with_id: sharesWith?parseInt(sharesWith):null,
    count_calendar_days: document.getElementById('leaveTypeCountMode').value==='calendar',
    accrual_mode: document.getElementById('leaveTypeAccrualMode').value,
    max_days_per_application: parseFloat(document.getElementById('leaveTypeMaxPerApp').value)||0,
    max_days_per_month: parseFloat(document.getElementById('leaveTypeMaxPerMonth').value)||0,
    carry_forward_enabled: document.getElementById('leaveTypeCarryForwardEnabled').checked,
    carry_forward_max_days: parseFloat(document.getElementById('leaveTypeCarryMaxDays').value)||0,
    carry_forward_max_percent: parseFloat(document.getElementById('leaveTypeCarryMaxPercent').value)||0,
    carry_forward_expiry_days: parseInt(document.getElementById('leaveTypeCarryExpiryDays').value)||0,
  };
  const url=id?`/api/leave/types/${id}`:'/api/leave/types';
  const res=await api(url,{method:id?'PUT':'POST',body:JSON.stringify(body)});
  if(res?.ok){ closeLeaveTypeModal(); loadLeaveTypesForManage(); }
  else if(res){ const d=await res.json().catch(()=>({})); alert(d.detail||'Failed to save leave type'); }
}

async function deleteLeaveType(id) {
  if(!confirm('Remove this leave type?')) return;
  await api(`/api/leave/types/${id}`,{method:'DELETE'});
  loadLeaveTypesForManage();
}

;
// ---- resignation.js ----
// Employee Resignation — self-service submission (Home dashboard "Resign"
// button), HR-on-behalf submission (Employee detail "File Resignation"),
// and the Resignation Approvals page (manager/HR review).
// ---------------------------------------------------------------------------
const RESIGN_STATUS_COLORS = {
  Pending: 'status-pending', Approved: 'status-positive',
  Rejected: 'status-negative', Withdrawn: 'status-neutral',
};
const RESIGN_ATTACH_MAX_BYTES = 6 * 1024 * 1024;

let _resignAttachment = null;
let resignApprovalFilter = 'Pending';
let resignApprovalRowsCache = [];
const resignApprovalList = createListState({ sortKey: 'created_at', sortDir: 'desc' });

function todayStr() { return new Date().toISOString().slice(0, 10); }

function openResignModal(empId, empName) {
  document.getElementById('resignModalTitle').textContent = empId ? 'File Resignation' : 'Submit Resignation';
  document.getElementById('resignEmpId').value = empId || '';
  const nameEl = document.getElementById('resignForEmpName');
  if (empId) { nameEl.textContent = `For: ${empName}`; nameEl.classList.remove('hidden'); }
  else { nameEl.classList.add('hidden'); }
  document.getElementById('resignReason').value = '';
  document.getElementById('resignEffectiveDate').value = todayStr();
  document.getElementById('resignLastDay').value = todayStr();
  document.getElementById('resignAttachFile').value = '';
  _resignAttachment = null;
  document.getElementById('resignErr').classList.add('hidden');
  document.getElementById('resignModal').classList.remove('hidden');
}
function closeResignModal() { closeModal('resignModal', () => { _resignAttachment = null; }); }

function fileResignationFromView() {
  if (!viewingId) return;
  const e = employees.find(em => em.employee_id === viewingId);
  if (!e) return;
  openResignModal(viewingId, displayName(e.full_name, e.preferred_name));
}

async function handleResignAttachFile(e) {
  const file = e.target.files?.[0];
  e.target.value = '';
  if (!file) return;
  if (file.size > RESIGN_ATTACH_MAX_BYTES) { alert('File is too large. Please choose a file under ~6MB.'); return; }
  const dataUrl = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
  _resignAttachment = { file_name: file.name, mime_type: file.type || 'application/octet-stream', data_url: dataUrl };
}

const submitResignation = guardAsync(async function(e) {
  e.preventDefault();
  const err = document.getElementById('resignErr');
  err.classList.add('hidden');
  const effectiveDate = document.getElementById('resignEffectiveDate').value;
  const lastDay = document.getElementById('resignLastDay').value;
  if (lastDay < effectiveDate) {
    err.textContent = 'Last working day must be on or after the effective date.';
    err.classList.remove('hidden');
    return;
  }
  const empId = document.getElementById('resignEmpId').value;
  const body = {
    employee_id: empId || null,
    reason: document.getElementById('resignReason').value,
    effective_date: effectiveDate,
    last_working_day: lastDay,
    attachment: _resignAttachment,
  };
  const res = await api('/api/resignations', { method: 'POST', body: JSON.stringify(body) });
  if (!res || !res.ok) {
    const d = await res?.json().catch(() => ({}));
    err.textContent = d?.detail || 'Failed to submit resignation';
    err.classList.remove('hidden');
    return;
  }
  closeResignModal();
  if (empId) { closeViewModal(); alert('Resignation filed.'); }
  else { await refreshResignButtonState(); }
});

// Toggles the "Resign" button vs. an inline pending-status line on the
// Dashboard General tab — called from renderDashboard() (dashboard.js) for
// the employee role only, same gate as dashboardQuickActions itself.
async function refreshResignButtonState() {
  const btn = document.getElementById('dashboardResignBtn');
  const statusEl = document.getElementById('dashboardResignStatus');
  if (!btn || !currentUser?.employee_id) return;
  const res = await api('/api/resignations?status=Pending');
  const rows = res?.ok ? await res.json() : [];
  const mine = rows.find(r => r.employee_id === currentUser.employee_id);
  if (mine) {
    btn.classList.add('hidden');
    statusEl.innerHTML = `Your resignation is pending approval. <a href="#" onclick="withdrawMyResignation(${mine.id});return false;" class="text-blue-600 hover:underline">Withdraw</a>`;
    statusEl.classList.remove('hidden');
  } else {
    btn.classList.remove('hidden');
    statusEl.classList.add('hidden');
  }
}

async function withdrawMyResignation(id) {
  if (!confirm('Withdraw your resignation request?')) return;
  const res = await api(`/api/resignations/${id}`, { method: 'PATCH', body: JSON.stringify({ status: 'Withdrawn' }) });
  if (!res?.ok) { const d = await res?.json().catch(() => ({})); alert(d?.detail || 'Failed to withdraw'); return; }
  await refreshResignButtonState();
}

// ---------------------------------------------------------------------------
// Resignation Approvals (manager / HR)
// ---------------------------------------------------------------------------
async function loadResignationApprovals() {
  const tbody = document.getElementById('resignationApprovalTableBody');
  tbody.innerHTML = '<tr><td colspan="6" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  let url = '/api/resignations';
  if (resignApprovalFilter) url += `?status=${encodeURIComponent(resignApprovalFilter)}`;
  const res = await api(url);
  if (!res?.ok) { tbody.innerHTML = ''; return; }
  resignApprovalRowsCache = await res.json();
  resignApprovalList.resetPage();
  renderResignationApprovalTable();
}

function setResignationApprovalSort(key) { resignApprovalList.setSort(key); renderResignationApprovalTable(); }
function setResignationApprovalPageSize(size) { resignApprovalList.setPageSize(size); renderResignationApprovalTable(); }
function resignationApprovalPagePrev() { resignApprovalList.prevPage(); renderResignationApprovalTable(); }
function resignationApprovalPageNext() { resignApprovalList.nextPage(resignApprovalRowsCache.length); renderResignationApprovalTable(); }

function renderResignationApprovalTable() {
  const tbody = document.getElementById('resignationApprovalTableBody');
  const emptyEl = document.getElementById('resignationApprovalEmpty');
  const pagination = document.getElementById('resignationApprovalPagination');
  resignApprovalList.updateSortArrows('.resign-appr-sort-arrow');

  if (!resignApprovalRowsCache.length) { tbody.innerHTML = ''; emptyEl?.classList.remove('hidden'); pagination?.classList.add('hidden'); return; }
  emptyEl?.classList.add('hidden');
  pagination?.classList.remove('hidden');
  const pageSizeEl = document.getElementById('resignationApprovalPageSize');
  if (pageSizeEl) pageSizeEl.value = String(resignApprovalList.pageSize);

  const { pageItems, start, total } = resignApprovalList.view(resignApprovalRowsCache);
  const pageInfoEl = document.getElementById('resignationApprovalPageInfo');
  if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + resignApprovalList.pageSize, total)} of ${total}`;

  tbody.innerHTML = pageItems.map(r => `
    <tr>
      <td class="px-4 py-3">
        <p class="font-medium">${esc(displayName(r.employee_name, r.employee_preferred_name))}</p>
        <p class="text-xs text-slate-500">${esc(r.department || '')}${r.designation ? ' · ' + esc(r.designation) : ''}</p>
      </td>
      <td class="px-4 py-3 text-slate-600">Eff ${fmtDate(r.effective_date)} · Last ${fmtDate(r.last_working_day)}</td>
      <td class="px-4 py-3">
        <p class="text-slate-600 italic line-clamp-1">${esc(r.reason)}</p>
        ${r.attachment_data_url ? `<a href="${r.attachment_data_url}" target="_blank" class="text-xs text-blue-600 hover:underline">${esc(r.attachment_file_name || 'View attachment')}</a>` : ''}
      </td>
      <td class="px-4 py-3"><span class="badge ${statusColor(RESIGN_STATUS_COLORS, r.status)} text-xs">${r.status}</span></td>
      <td class="px-4 py-3">
        <p class="text-slate-500">${fmtDate(r.created_at)}</p>
        <p class="text-xs text-slate-400">by ${esc(r.submitted_by)}</p>
      </td>
      <td class="px-4 py-3 text-right">
        ${r.status === 'Pending' ? (r.is_actionable ? `
          <button onclick="reviewResignationRequest(${r.id},'Approved')" class="text-xs text-emerald-700 hover:underline mr-3">Approve</button>
          <button onclick="reviewResignationRequest(${r.id},'Rejected')" class="text-xs text-red-700 hover:underline">Reject</button>
        ` : `<span class="text-xs text-slate-400">Pending: ${esc(r.pending_with||'—')}</span>`) : '<span class="text-xs text-slate-400">—</span>'}
      </td>
    </tr>`).join('');
}

function setResignationApprovalFilter(status) {
  resignApprovalFilter = status;
  document.querySelectorAll('.resign-appr-filter-btn').forEach(b => b.classList.remove('resign-appr-filter-active'));
  event?.target?.classList?.add('resign-appr-filter-active');
  loadResignationApprovals();
}

async function reviewResignationRequest(id, status) {
  const res = await api(`/api/resignations/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) });
  if (res?.ok) loadResignationApprovals();
  else { const d = await res.json(); alert(d.detail || 'Failed to update'); }
}

;
// ---- timesheet.js ----
// Timesheet / Projects
// ---------------------------------------------------------------------------
let projectsCache=[], myProjectsCache=[], projectFilter='';
// pageSize is set well above any realistic project count — this list has no
// pagination UI, only sorting, so createListState is used sort-only here.
const projectList = createListState({ sortKey: 'name', pageSize: 10000 });
// Pivot-table expand state for the Projects list — which project rows are
// showing their task sub-rows, and each project's own task list once
// fetched (lazy: only loaded on first expand, not for every project up
// front). Kept in sync with the Edit Project modal's own task list by
// loadProjectTasksForManage below, rather than a second independent fetch
// path, so editing a task there can't leave this cache stale.
let expandedProjectIds=new Set(), projectTasksByProject={};
let tsCurrentWeekStart=null, tsCurrentTimesheet=null;
let tsApprovalFilter='Submitted';
const TS_STATUS_COLORS={'Draft':'status-neutral','Submitted':'status-pending','Approved':'status-positive','Rejected':'status-negative'};

// Login roles eligible to be picked as a Project Manager. Matters beyond
// the picker itself: core/approval_workflow.py's "project_manager"
// approver type lets anyone listed in a project's manager_ids approve
// that project's timesheets, regardless of their own login role — so
// this list is what keeps that approval power aligned with roles that
// could plausibly hold it through any other path in the app. Frontend-
// only for now (POST/PUT /api/projects still accepts any employee_id),
// so this narrows the picker but doesn't by itself close that off.
const PROJECT_MANAGER_ELIGIBLE_ROLES=['manager','hr_manager','hr_admin'];
// employee_ids currently holding one of those roles — populated by
// loadProjectManagerEligibility() each time the Edit Project modal opens.
let projectManagerEligibleIds=new Set();

function isProjectManager() {
  return HR_MANAGER_ONLY_ROLES.includes(currentUser?.role);
}

// ---------------------------------------------------------------------------
// Projects (HR Manager)
// ---------------------------------------------------------------------------
const PROJECT_TABLE_COLUMNS=[
  {key:'name', label:'Project'},
  {key:'status', label:'Status'},
  {key:'task_count', label:'Tasks'},
  {key:'member_count', label:'Team'},
  {key:'total_allocated_hours', label:'Allocated'},
  {key:'total_logged_hours', label:'Clocked'},
];

async function loadProjects() {
  const listEl=document.getElementById('projectList');
  const emptyEl=document.getElementById('projectEmpty');
  listEl.innerHTML='<tr><td colspan="6" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  let url='/api/projects';
  if(projectFilter) url+=`?status=${encodeURIComponent(projectFilter)}`;
  const res=await api(url);
  if(!res?.ok){ listEl.innerHTML=''; return; }
  const rows=await res.json();
  projectsCache=rows;
  if(!rows.length){ listEl.innerHTML=''; emptyEl?.classList.remove('hidden'); renderProjectTableHead(); return; }
  emptyEl?.classList.add('hidden');
  renderProjectTableHead();
  renderProjectTable();
}

function renderProjectTableHead() {
  document.getElementById('projectTableHead').innerHTML=PROJECT_TABLE_COLUMNS.map(c=>{
    const active=projectList.sortKey===c.key;
    const arrow=active?(projectList.sortDir==='asc'?'▲':'▼'):'';
    return `<th class="text-left px-4 py-2.5 text-xs font-semibold text-slate-500 uppercase tracking-wide cursor-pointer select-none hover:text-slate-700" onclick="setProjectSort('${c.key}')">${c.label} <span class="text-blue-600">${arrow}</span></th>`;
  }).join('');
}

function setProjectSort(key) {
  projectList.setSort(key);
  renderProjectTableHead();
  renderProjectTable();
}

function renderProjectTable() {
  const listEl=document.getElementById('projectList');
  const STATUS_COLORS={'Active':'status-positive','On Hold':'status-pending','Completed':'status-neutral'};
  const { pageItems: sorted } = projectList.view(projectsCache);
  listEl.innerHTML=sorted.map(p=>{
    const expanded=expandedProjectIds.has(p.id);
    return `
    <tr class="border-t border-slate-100 cursor-pointer hover:bg-slate-50 transition" onclick="openProjectModal(${p.id})">
      <td class="px-4 py-3">
        <div class="flex items-center gap-2">
          <button onclick="event.stopPropagation();toggleProjectExpand(${p.id})" class="shrink-0 p-0.5 text-slate-400 hover:text-slate-600" title="${expanded?'Collapse':'Expand'} tasks">
            <svg class="w-3.5 h-3.5 transition-transform ${expanded?'rotate-90':''}" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
          </button>
          <div class="min-w-0">
            <div class="flex items-center gap-1.5">
              <p class="font-medium text-slate-800 truncate">${esc(p.name)}</p>
              ${p.is_open_to_all?'<span class="badge text-xs bg-blue-100 text-blue-700 shrink-0" title="Any employee can log time here, no membership needed">ALL</span>':''}
              ${p.is_billable?'<span class="badge text-xs bg-emerald-100 text-emerald-700 shrink-0">Billable</span>':''}
            </div>
            <p class="text-xs text-slate-400 line-clamp-1">${esc(p.description||'')}</p>
          </div>
        </div>
      </td>
      <td class="px-4 py-3"><span class="badge text-xs ${statusColor(STATUS_COLORS, p.status)}">${p.status}</span></td>
      <td class="px-4 py-3 text-slate-600">${p.task_count}</td>
      <td class="px-4 py-3 text-slate-600">${p.member_count}</td>
      <td class="px-4 py-3 text-slate-600">${p.total_allocated_hours}h</td>
      <td class="px-4 py-3 text-slate-600">${p.total_logged_hours}h</td>
    </tr>${expanded?projectTaskSubRows(p.id):''}`;
  }).join('');
}

// Pivot-table task sub-rows for one project — see toggleProjectExpand.
// Purely informational (no click handler): task editing stays in the
// existing Edit Project modal's Tasks tab, not duplicated here.
function projectTaskSubRows(projectId) {
  const tasks=projectTasksByProject[projectId];
  if(tasks===undefined) {
    return `<tr class="bg-slate-50/60"><td colspan="6" class="pl-12 pr-4 py-2.5 text-xs text-slate-400">Loading tasks…</td></tr>`;
  }
  if(!tasks.length) {
    return `<tr class="bg-slate-50/60"><td colspan="6" class="pl-12 pr-4 py-2.5 text-xs text-slate-400">No tasks yet.</td></tr>`;
  }
  return tasks.map(t=>`
    <tr class="bg-slate-50/60 border-t border-slate-100">
      <td class="pl-12 pr-4 py-2.5">
        <div class="flex items-center gap-2 min-w-0">
          <span class="text-slate-300 shrink-0">↳</span>
          <span class="text-slate-700 truncate">${esc(t.name)}</span>
        </div>
      </td>
      <td class="px-4 py-2.5"><span class="badge text-xs ${statusColor(TASK_STATUS_COLORS, t.status)}">${t.status}</span></td>
      <td class="px-4 py-2.5 text-slate-300">—</td>
      <td class="px-4 py-2.5 text-slate-300">—</td>
      <td class="px-4 py-2.5 text-slate-500">${t.estimated_hours?t.estimated_hours+'h':'—'}</td>
      <td class="px-4 py-2.5 text-slate-500">${t.logged_hours}h</td>
    </tr>`).join('');
}

async function toggleProjectExpand(projectId) {
  if(expandedProjectIds.has(projectId)) {
    expandedProjectIds.delete(projectId);
    renderProjectTable();
    return;
  }
  expandedProjectIds.add(projectId);
  renderProjectTable();
  if(!projectTasksByProject[projectId]) {
    const res=await api(`/api/projects/${projectId}/tasks`);
    projectTasksByProject[projectId]=res?.ok?await res.json():[];
    renderProjectTable();
  }
}

function setProjectFilter(status) {
  projectFilter=status;
  document.querySelectorAll('.project-filter-btn').forEach(b=>b.classList.remove('project-filter-active'));
  event?.target?.classList?.add('project-filter-active');
  loadProjects();
}

function switchProjectTab(name) {
  ['details','tasks'].forEach(t=>{
    document.getElementById(`projectTab-${t}`)?.classList.toggle('hidden', t!==name);
    const btn=document.querySelector(`.project-tab-btn[data-ptab="${t}"]`);
    if(btn){ btn.classList.toggle('project-tab-active', t===name); btn.classList.toggle('text-slate-500', t!==name); }
  });
}

// Fetches which employees currently hold a manager-tier login role
// (PROJECT_MANAGER_ELIGIBLE_ROLES), for renderProjectManagersChecklist to
// filter against. Reachable only by whoever can already open the Edit
// Project modal (nav-projects is HR_MANAGER_ONLY_ROLES-gated), which is
// exactly who /api/users' own role gate (_USER_MANAGE = superadmin,
// hr_manager) already allows — no new backend permission needed.
//
// Checks u.roles (the full set of capability checkboxes on their user
// account — Settings > Users' "Roles" checklist), NOT u.role (just
// whichever one is currently their "Active / Primary Role", the landing
// view Switch Active Role toggles between). A user can hold Manager
// alongside Employee and default to Employee as their day-to-day view —
// they still hold real Manager-tier capability, so they still belong in
// this picker. Checking only the single active role wrongly excluded
// exactly that case.
async function loadProjectManagerEligibility() {
  const res=await api('/api/users');
  const list=res?.ok?await res.json():[];
  projectManagerEligibleIds=new Set(
    list.filter(u=>u.is_active && u.employee_id && (u.roles||[u.role]).some(r=>PROJECT_MANAGER_ELIGIBLE_ROLES.includes(r)))
      .map(u=>u.employee_id)
  );
}

function renderProjectManagersChecklist(selectedIds) {
  const wrap=document.getElementById('projectManagersList');
  // Limited to manager-tier employees (see PROJECT_MANAGER_ELIGIBLE_ROLES)
  // — plus anyone already assigned, even if their role no longer
  // qualifies, so re-saving an existing project without touching this
  // field can't silently drop a legacy assignment the picker itself
  // wouldn't offer anymore.
  const active=(employees||[]).filter(e=>e.status==='Active' && (projectManagerEligibleIds.has(e.employee_id) || selectedIds.includes(e.employee_id)));
  wrap.innerHTML=active.map(e=>{
    const label=`${displayName(e.full_name,e.preferred_name)} (${e.employee_id})`;
    return `
    <label class="project-manager-option flex items-center gap-2 px-3 py-1.5 hover:bg-slate-50 cursor-pointer" data-label="${esc(label)}">
      <input type="checkbox" class="project-manager-checkbox" value="${e.employee_id}" ${selectedIds.includes(e.employee_id)?'checked':''} onchange="syncProjectManagersSelectAll()"/>
      ${esc(label)}
    </label>`;
  }).join('') + `<div id="projectManagersNoMatch" class="hidden text-center text-xs text-slate-400 py-3">No matches</div>`;
  const searchEl=document.getElementById('projectManagersSearch');
  if(searchEl) searchEl.value='';
  // Also handles the "nobody eligible at all" empty state and syncs
  // Select All — same computation filterProjectManagerOptions does for a
  // live search, run here once against the just-rendered, unfiltered list.
  filterProjectManagerOptions();
}

// Filters the checklist by name/ID as the user types, without re-rendering
// (so checked state — including for options scrolled out of view — is never
// lost). Reuses employee-picker.js's filterEmployeeOptions (same
// substring/case-insensitive match already used by every searchable
// employee <select> in the app) rather than a second hand-rolled matcher.
// "Select All" only ever acts on what's currently visible, so it composes
// with an active search instead of fighting it.
function filterProjectManagerOptions() {
  const q=document.getElementById('projectManagersSearch')?.value||'';
  const opts=[...document.querySelectorAll('.project-manager-option')];
  const matched=new Set(filterEmployeeOptions(
    opts.map(el=>({value: el.querySelector('.project-manager-checkbox').value, label: el.dataset.label})),
    q
  ).map(o=>o.value));
  let visibleCount=0;
  opts.forEach(opt=>{
    const match=matched.has(opt.querySelector('.project-manager-checkbox').value);
    opt.classList.toggle('hidden', !match);
    if(match) visibleCount++;
  });
  document.getElementById('projectManagersNoMatch')?.classList.toggle('hidden', visibleCount>0);
  syncProjectManagersSelectAll();
}

function visibleProjectManagerCheckboxes() {
  return [...document.querySelectorAll('.project-manager-option:not(.hidden) .project-manager-checkbox')];
}

function syncProjectManagersSelectAll() {
  const boxes=visibleProjectManagerCheckboxes();
  document.getElementById('projectManagersSelectAll').checked = boxes.length>0 && boxes.every(b=>b.checked);
}

function toggleAllProjectManagers() {
  const checked=document.getElementById('projectManagersSelectAll').checked;
  visibleProjectManagerCheckboxes().forEach(b=>b.checked=checked);
}

// Team Members — same searchable checkbox-list pattern as Project
// Manager(s) above, but with no role-eligibility filter: this is the
// project's timesheet membership roster (see routers/projects.py's
// add_timesheet_entry), open to any active employee, not just
// manager-tier ones.
function renderProjectMembersChecklist(selectedIds) {
  const wrap=document.getElementById('projectMembersList');
  // Plus anyone already a member even if their employee record is no
  // longer Active (deactivated after being added) — same reasoning as
  // the Project Manager(s) picker: an unrelated future save can't
  // silently drop them just because the picker itself wouldn't offer
  // them to newly add.
  const active=(employees||[]).filter(e=>e.status==='Active' || selectedIds.includes(e.employee_id));
  wrap.innerHTML=active.map(e=>{
    const label=`${displayName(e.full_name,e.preferred_name)} (${e.employee_id})`;
    return `
    <label class="project-member-option flex items-center gap-2 px-3 py-1.5 hover:bg-slate-50 cursor-pointer" data-label="${esc(label)}">
      <input type="checkbox" class="project-member-checkbox" value="${e.employee_id}" ${selectedIds.includes(e.employee_id)?'checked':''} onchange="syncProjectMembersSelectAll()"/>
      ${esc(label)}
    </label>`;
  }).join('') + `<div id="projectMembersNoMatch" class="hidden text-center text-xs text-slate-400 py-3">No matches</div>`;
  const searchEl=document.getElementById('projectMembersSearch');
  if(searchEl) searchEl.value='';
  filterProjectMemberOptions();
}

function filterProjectMemberOptions() {
  const q=document.getElementById('projectMembersSearch')?.value||'';
  const opts=[...document.querySelectorAll('.project-member-option')];
  const matched=new Set(filterEmployeeOptions(
    opts.map(el=>({value: el.querySelector('.project-member-checkbox').value, label: el.dataset.label})),
    q
  ).map(o=>o.value));
  let visibleCount=0;
  opts.forEach(opt=>{
    const match=matched.has(opt.querySelector('.project-member-checkbox').value);
    opt.classList.toggle('hidden', !match);
    if(match) visibleCount++;
  });
  document.getElementById('projectMembersNoMatch')?.classList.toggle('hidden', visibleCount>0);
  syncProjectMembersSelectAll();
}

function visibleProjectMemberCheckboxes() {
  return [...document.querySelectorAll('.project-member-option:not(.hidden) .project-member-checkbox')];
}

function syncProjectMembersSelectAll() {
  const boxes=visibleProjectMemberCheckboxes();
  document.getElementById('projectMembersSelectAll').checked = boxes.length>0 && boxes.every(b=>b.checked);
}

function toggleAllProjectMembers() {
  const checked=document.getElementById('projectMembersSelectAll').checked;
  visibleProjectMemberCheckboxes().forEach(b=>b.checked=checked);
}

async function openProjectModal(projectId) {
  document.getElementById('projectId').value=projectId||'';
  document.getElementById('projectModalTitle').textContent=projectId?'Edit Project':'Add Project';
  const tasksBtn=document.getElementById('projectTabTasksBtn');
  switchProjectTab('details');
  if(!employees || !employees.length) await loadEmployees();
  await loadProjectManagerEligibility();
  if(projectId){
    const p=projectsCache.find(x=>x.id===projectId);
    document.getElementById('projectName').value=p?.name||'';
    document.getElementById('projectDesc').value=p?.description||'';
    document.getElementById('projectStatus').value=p?.status||'Active';
    renderProjectManagersChecklist(p?.manager_ids||[]);
    renderProjectMembersChecklist(p?.member_ids||[]);
    document.getElementById('projectOpenToAll').checked=!!p?.is_open_to_all;
    document.getElementById('projectBillable').checked=!!p?.is_billable;
    tasksBtn.classList.remove('hidden');
    await loadProjectTasksForManage(projectId);
    resetProjectTaskForm();
  } else {
    document.getElementById('projectName').value='';
    document.getElementById('projectDesc').value='';
    document.getElementById('projectStatus').value='Active';
    renderProjectManagersChecklist([]);
    renderProjectMembersChecklist([]);
    document.getElementById('projectOpenToAll').checked=false;
    document.getElementById('projectBillable').checked=false;
    tasksBtn.classList.add('hidden');
  }
  document.getElementById('projectModal').classList.remove('hidden');
}
function closeProjectModal() { closeModal('projectModal'); }

const submitProject = guardAsync(async function() {
  const id=document.getElementById('projectId').value;
  const body={
    name: document.getElementById('projectName').value.trim(),
    description: document.getElementById('projectDesc').value.trim()||null,
    status: document.getElementById('projectStatus').value,
    manager_ids: [...document.querySelectorAll('.project-manager-checkbox:checked')].map(b=>b.value),
    member_ids: [...document.querySelectorAll('.project-member-checkbox:checked')].map(b=>b.value),
    is_open_to_all: document.getElementById('projectOpenToAll').checked,
    is_billable: document.getElementById('projectBillable').checked,
  };
  if(!body.name){ alert('Project name is required'); return; }
  const url=id?`/api/projects/${id}`:'/api/projects';
  const res=await api(url,{method:id?'PUT':'POST',body:JSON.stringify(body)});
  if(res?.ok){
    const proj=await res.json();
    if(!id){
      // Newly created — reopen in edit mode so tasks can be added right away
      await loadProjects();
      openProjectModal(proj.id);
    } else {
      closeProjectModal();
      loadProjects();
    }
  } else {
    const d=await res.json(); alert(d.detail||'Failed to save project');
  }
});

async function deleteProject(projectId) {
  if(!confirm('Delete this project?')) return;
  const res=await api(`/api/projects/${projectId}`,{method:'DELETE'});
  if(res?.ok||res?.status===204){ closeProjectModal(); loadProjects(); }
  else { const d=await res.json(); alert(d.detail||'Failed to delete project'); }
}

// ---------------------------------------------------------------------------
// Project Tasks (HR Manager)
// ---------------------------------------------------------------------------
let projectTasksCache=[];
const TASK_STATUS_COLORS={'Not Started':'status-neutral','In Progress':'status-info','Completed':'status-positive'};

async function loadProjectTasksForManage(projectId) {
  const res=await api(`/api/projects/${projectId}/tasks`);
  projectTasksCache=res?.ok?await res.json():[];
  // Keep the Projects list's pivot-table sub-rows in sync — this is the
  // one place task data actually changes, so it's also the one place
  // that needs to invalidate/refresh that cache (see toggleProjectExpand).
  projectTasksByProject[projectId]=projectTasksCache;
  if(expandedProjectIds.has(projectId)) renderProjectTable();
  document.getElementById('projectTaskList').innerHTML=projectTasksCache.length?projectTasksCache.map(t=>`
    <div class="border border-slate-200 rounded-lg p-2 text-sm">
      <div class="flex items-center justify-between gap-2">
        <span class="font-medium text-slate-700">${esc(t.name)}</span>
        <div class="flex items-center gap-1">
          <span class="badge text-xs ${statusColor(TASK_STATUS_COLORS, t.status)}">${t.status}</span>
        </div>
      </div>
      <p class="text-xs text-slate-500 mt-0.5">
        ${t.start_date?`${fmtDate(t.start_date)} → ${t.end_date?fmtDate(t.end_date):'?'}`:'No dates set'}
        ${t.estimated_hours?` · ${t.logged_hours}/${t.estimated_hours} hrs logged`:` · ${t.logged_hours} hrs logged`}
      </p>
      <div class="flex gap-2 mt-1">
        <button onclick="editProjectTask(${t.id})" class="text-xs text-blue-600 hover:underline">Edit</button>
        <button onclick="deleteProjectTask(${projectId},${t.id})" class="text-xs text-red-600 hover:underline">Delete</button>
      </div>
    </div>`).join(''):'<p class="text-xs text-slate-400 text-center py-2">No tasks yet.</p>';
}

function resetProjectTaskForm() {
  document.getElementById('projectTaskId').value='';
  document.getElementById('projectTaskName').value='';
  document.getElementById('projectTaskDesc').value='';
  document.getElementById('projectTaskHours').value='';
  document.getElementById('projectTaskStart').value='';
  document.getElementById('projectTaskEnd').value='';
  document.getElementById('projectTaskStatus').value='Not Started';
  document.getElementById('taskAssignSection').classList.add('hidden');
  document.getElementById('taskAssignHint').classList.remove('hidden');
}

function editProjectTask(taskId) {
  const t=projectTasksCache.find(x=>x.id===taskId);
  if(!t) return;
  document.getElementById('projectTaskId').value=t.id;
  document.getElementById('projectTaskName').value=t.name;
  document.getElementById('projectTaskDesc').value=t.description||'';
  document.getElementById('projectTaskHours').value=t.estimated_hours||'';
  document.getElementById('projectTaskStart').value=t.start_date||'';
  document.getElementById('projectTaskEnd').value=t.end_date||'';
  document.getElementById('projectTaskStatus').value=t.status;
  showTaskAssignSection(t.id);
}

const submitProjectTask = guardAsync(async function() {
  const projectId=document.getElementById('projectId').value;
  const taskId=document.getElementById('projectTaskId').value;
  const name=document.getElementById('projectTaskName').value.trim();
  if(!name){ alert('Task name is required'); return; }
  const body={
    name,
    description: document.getElementById('projectTaskDesc').value.trim()||null,
    estimated_hours: parseFloat(document.getElementById('projectTaskHours').value)||null,
    start_date: document.getElementById('projectTaskStart').value||null,
    end_date: document.getElementById('projectTaskEnd').value||null,
    status: document.getElementById('projectTaskStatus').value,
  };
  const url=taskId?`/api/projects/${projectId}/tasks/${taskId}`:`/api/projects/${projectId}/tasks`;
  const res=await api(url,{method:taskId?'PUT':'POST',body:JSON.stringify(body)});
  if(res?.ok){
    const saved=await res.json();
    await loadProjectTasksForManage(parseInt(projectId));
    // Keep the form open on the just-saved task so team members can be assigned right away
    document.getElementById('projectTaskId').value=saved.id;
    showTaskAssignSection(saved.id);
  } else {
    const d=await res.json(); alert(d.detail||'Failed to save task');
  }
});

async function deleteProjectTask(projectId, taskId) {
  if(!confirm('Delete this task?')) return;
  const res=await api(`/api/projects/${projectId}/tasks/${taskId}`,{method:'DELETE'});
  if(res?.ok||res?.status===204){ loadProjectTasksForManage(projectId); resetProjectTaskForm(); }
  else { const d=await res.json(); alert(d.detail||'Failed to delete task'); }
}

// ---------------------------------------------------------------------------
// Task Assignments — expected effort (start datetime + duration) for a
// project member on this task. Team membership itself lives at the
// project level (Details tab's Team Members list, plus the "Open to
// all" checkbox) — this only schedules effort for people already on
// that roster; it plays no part in deciding who can log timesheet hours
// against the project (see routers/projects.py's add_timesheet_entry).
// ---------------------------------------------------------------------------
async function showTaskAssignSection(taskId) {
  document.getElementById('taskAssignHint').classList.add('hidden');
  document.getElementById('taskAssignSection').classList.remove('hidden');
  await loadTaskAssignments(taskId);
}

async function loadTaskAssignments(taskId) {
  const projectId=parseInt(document.getElementById('projectId').value);
  const project=projectsCache.find(p=>p.id===projectId);
  const memberIds=project?.member_ids||[];

  const res=await api(`/api/projects/${projectId}/tasks/${taskId}/assignments`);
  const assignments=res?.ok?await res.json():[];
  document.getElementById('taskAssignList').innerHTML=assignments.length?assignments.map(a=>`
    <div class="flex items-center gap-2 py-1 border-b border-slate-100 text-xs">
      <span class="flex-1">${esc(displayName(a.full_name,a.preferred_name))}</span>
      <span class="text-slate-400">${fmtDate(a.start_datetime)}${a.start_datetime.includes('T')?', '+a.start_datetime.split('T')[1]:''} · ${a.duration_hours}h</span>
      <button onclick="removeTaskAssignment(${taskId},'${a.employee_id}')" class="text-slate-300 hover:text-red-500"><svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
    </div>`).join(''):'<p class="text-xs text-slate-400 text-center py-1">No one assigned yet.</p>';

  // Candidates are limited to the project's own Team Members roster
  // (Details tab) — you can't schedule effort for someone who isn't a
  // project member first.
  const assignedIds=new Set(assignments.map(a=>a.employee_id));
  const available=(employees||[]).filter(e=>memberIds.includes(e.employee_id)&&!assignedIds.has(e.employee_id));
  const sel=document.getElementById('taskAssignEmpId');
  const fieldsWrap=document.getElementById('taskAssignFields');
  const fieldsRow2=document.getElementById('taskAssignFieldsRow2');
  const noMembersEl=document.getElementById('taskAssignNoMembers');
  if(!memberIds.length){
    noMembersEl.classList.remove('hidden');
    fieldsWrap.classList.add('hidden');
    fieldsRow2.classList.add('hidden');
    return;
  }
  noMembersEl.classList.add('hidden');
  fieldsWrap.classList.remove('hidden');
  fieldsRow2.classList.remove('hidden');
  sel.innerHTML=available.length
    ? available.map(e=>`<option value="${e.employee_id}">${esc(displayName(e.full_name,e.preferred_name))}</option>`).join('')
    : '<option value="">All project members already assigned</option>';
}

const addTaskAssignment = guardAsync(async function() {
  const projectId=document.getElementById('projectId').value;
  const taskId=document.getElementById('projectTaskId').value;
  const employeeId=document.getElementById('taskAssignEmpId').value;
  if(!employeeId){ alert('No project member available to assign — every member is already scheduled on this task, or the project has no members yet.'); return; }
  const startDatetime=document.getElementById('taskAssignStart').value;
  const durationHours=parseFloat(document.getElementById('taskAssignDuration').value);
  if(!startDatetime||!durationHours){ alert('Start date/time and duration (hours) are required.'); return; }
  const res=await api(`/api/projects/${projectId}/tasks/${taskId}/assignments`,{method:'POST',body:JSON.stringify({employee_id:employeeId,start_datetime:startDatetime,duration_hours:durationHours})});
  if(res?.ok){
    document.getElementById('taskAssignStart').value='';
    document.getElementById('taskAssignDuration').value='';
    loadTaskAssignments(parseInt(taskId));
  } else {
    const d=await res.json(); alert(d.detail||'Failed to assign team member');
  }
});

async function removeTaskAssignment(taskId, employeeId) {
  const projectId=document.getElementById('projectId').value;
  await api(`/api/projects/${projectId}/tasks/${taskId}/assignments/${employeeId}`,{method:'DELETE'});
  loadTaskAssignments(taskId);
}

// ---------------------------------------------------------------------------
// My Timesheet
// ---------------------------------------------------------------------------
function tsGetMonday(d) {
  const date=new Date(d);
  const day=date.getDay();
  const diff=(day===0?-6:1)-day; // shift to Monday
  date.setDate(date.getDate()+diff);
  date.setHours(0,0,0,0);
  return date;
}
function tsFmt(d) { return d.toISOString().slice(0,10); }

async function loadTimesheetPage() {
  if(!tsCurrentWeekStart) tsCurrentWeekStart=tsGetMonday(new Date());
  const res=await api('/api/projects/mine');
  myProjectsCache=res?.ok?await res.json():[];
  document.getElementById('tsEntryProject').innerHTML=myProjectsCache.length
    ? myProjectsCache.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')
    : '<option value="">No assigned projects</option>';
  await loadTsEntryTasks();
  await loadCurrentTimesheet();
}

async function loadTsEntryTasks() {
  const projectId=document.getElementById('tsEntryProject').value;
  const taskSel=document.getElementById('tsEntryTask');
  if(!projectId){ taskSel.innerHTML='<option value="">—</option>'; return; }
  const res=await api(`/api/projects/${projectId}/tasks`);
  const tasks=res?.ok?await res.json():[];
  taskSel.innerHTML=tasks.length
    ? tasks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')
    : '<option value="">No tasks defined for this project</option>';
}

function shiftTimesheetWeek(dir) {
  tsCurrentWeekStart.setDate(tsCurrentWeekStart.getDate()+dir*7);
  loadCurrentTimesheet();
}

async function loadCurrentTimesheet() {
  const start=tsFmt(tsCurrentWeekStart);
  const end=new Date(tsCurrentWeekStart); end.setDate(end.getDate()+6);
  const endStr=tsFmt(end);
  // fmtDate() here (not the raw ISO start/endStr, which the API call below
  // needs as-is) — matches every other date-range label in the app
  // (Payroll runs, Leave, PIP/Performance cycles, Employee contract dates
  // all render `${fmtDate(a)} → ${fmtDate(b)}`); this was the one place
  // that had been left showing the raw "YYYY-MM-DD" string instead.
  document.getElementById('timesheetWeekLabel').textContent=`${fmtDate(start)} → ${fmtDate(endStr)}`;

  const empId=currentUser?.employee_id;
  if(!empId){
    document.getElementById('timesheetEntryBody').innerHTML='';
    document.getElementById('timesheetEntryEmpty').classList.remove('hidden');
    document.getElementById('timesheetAddForm').classList.add('hidden');
    document.getElementById('timesheetSubmitBtn').classList.add('hidden');
    return;
  }
  const res=await api('/api/timesheets',{method:'POST',body:JSON.stringify({employee_id:empId,period_start:start,period_end:endStr})});
  const ts=await res.json();
  const detailRes=await api(`/api/timesheets/${ts.id}`);
  tsCurrentTimesheet=await detailRes.json();
  renderTimesheetEntries();
}

function renderTimesheetEntries() {
  const ts=tsCurrentTimesheet;
  const tbody=document.getElementById('timesheetEntryBody');
  const emptyEl=document.getElementById('timesheetEntryEmpty');
  const isDraft=ts.status==='Draft';

  if(!ts.entries.length){
    tbody.innerHTML='';
    emptyEl.classList.remove('hidden');
  } else {
    emptyEl.classList.add('hidden');
    tbody.innerHTML=ts.entries.map(e=>`
      <tr class="border-t border-slate-100">
        <td class="px-4 py-2">${fmtDate(e.date)}</td>
        <td class="px-4 py-2">${esc(e.project_name)}</td>
        <td class="px-4 py-2">${esc(e.task_name||'—')}</td>
        <td class="px-4 py-2">${e.hours}</td>
        <td class="px-4 py-2 text-slate-500">${esc(e.description||'')}</td>
        <td class="px-4 py-2 text-right">${isDraft?`<button onclick="deleteTimesheetEntry(${e.id})" class="text-slate-300 hover:text-red-500"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>`:''}</td>
      </tr>`).join('');
  }
  document.getElementById('timesheetTotalHours').textContent=ts.total_hours;

  const badgeWrap=document.getElementById('timesheetStatusBadgeWrap');
  badgeWrap.innerHTML=`<span class="badge ${statusColor(TS_STATUS_COLORS, ts.status)}">${ts.status}</span>${ts.notes?` <span class="text-xs text-slate-400 ml-1">${esc(ts.notes)}</span>`:''}`;

  document.getElementById('timesheetAddForm').classList.toggle('hidden', !isDraft);
  document.getElementById('timesheetSubmitBtn').classList.toggle('hidden', !isDraft);
  document.getElementById('tsEntryDate').value='';
  document.getElementById('tsEntryHours').value='';
  document.getElementById('tsEntryDesc').value='';
}

const addTimesheetEntry = guardAsync(async function() {
  const projectId=document.getElementById('tsEntryProject').value;
  if(!projectId){ alert('You have no assigned projects to log time against. Ask HR to add you to a project.'); return; }
  const taskId=document.getElementById('tsEntryTask').value;
  if(!taskId){ alert('This project has no tasks defined yet. Ask HR to add a task before logging time.'); return; }
  const date=document.getElementById('tsEntryDate').value;
  const hours=parseFloat(document.getElementById('tsEntryHours').value);
  if(!date||!hours){ alert('Date and hours are required.'); return; }
  const body={ project_id:parseInt(projectId), task_id:parseInt(taskId), date, hours, description:document.getElementById('tsEntryDesc').value.trim()||null };
  const res=await api(`/api/timesheets/${tsCurrentTimesheet.id}/entries`,{method:'POST',body:JSON.stringify(body)});
  if(res?.ok){
    const detailRes=await api(`/api/timesheets/${tsCurrentTimesheet.id}`);
    tsCurrentTimesheet=await detailRes.json();
    renderTimesheetEntries();
  } else {
    const d=await res.json(); alert(d.detail||'Failed to add entry');
  }
});

async function deleteTimesheetEntry(entryId) {
  await api(`/api/timesheets/${tsCurrentTimesheet.id}/entries/${entryId}`,{method:'DELETE'});
  const detailRes=await api(`/api/timesheets/${tsCurrentTimesheet.id}`);
  tsCurrentTimesheet=await detailRes.json();
  renderTimesheetEntries();
}

const submitTimesheet = guardAsync(async function() {
  if(!confirm('Submit this timesheet for approval? You will not be able to edit it afterwards.')) return;
  const res=await api(`/api/timesheets/${tsCurrentTimesheet.id}/status`,{method:'PATCH',body:JSON.stringify({status:'Submitted'})});
  if(res?.ok){ loadCurrentTimesheet(); }
  else { const d=await res.json(); alert(d.detail||'Failed to submit'); }
});

// ---------------------------------------------------------------------------
// Timesheet Approvals (manager / HR)
// ---------------------------------------------------------------------------
// Server-paginated (routers/timesheets.py's limit/offset + sort_by/sort_dir
// + X-Total-Count header) — mirrors Audit Log's pattern (see audit.js),
// extended with server-side sort since this table's column headers are
// genuinely sortable (Employee/Period/Hours/Status), unlike Audit Log which
// had no sort UI to preserve. tsApprovalRowsCache now holds just the current
// page (openTimesheetDetail below looks a clicked row up in it for its
// is_actionable/pending_with fields, which only the list endpoint computes).
let tsApprovalRowsCache=[];
let tsApprovalPage=1, tsApprovalPageSize=50, tsApprovalTotal=0;
let tsApprovalSortKey='period_start', tsApprovalSortDir='desc';

async function loadTimesheetApprovals() {
  const tbody=document.getElementById('timesheetApprovalTableBody');
  tbody.innerHTML='<tr><td colspan="4" class="text-slate-400 text-sm text-center py-8">Loading…</td></tr>';
  const offset=(tsApprovalPage-1)*tsApprovalPageSize;
  const params=new URLSearchParams({
    limit:String(tsApprovalPageSize), offset:String(offset),
    sort_by:tsApprovalSortKey, sort_dir:tsApprovalSortDir,
  });
  if(tsApprovalFilter) params.set('status', tsApprovalFilter);
  const res=await api(`/api/timesheets?${params}`);
  if(!res?.ok){ tbody.innerHTML=''; return; }
  tsApprovalRowsCache=await res.json();
  tsApprovalTotal=parseInt(res.headers.get('X-Total-Count')||'0',10);
  renderTimesheetApprovalTable();
}

function setTimesheetApprovalSort(key) {
  if(tsApprovalSortKey===key) tsApprovalSortDir = tsApprovalSortDir==='asc' ? 'desc' : 'asc';
  else { tsApprovalSortKey=key; tsApprovalSortDir='asc'; }
  tsApprovalPage=1;
  loadTimesheetApprovals();
}
function setTimesheetApprovalPageSize(size) { tsApprovalPageSize=parseInt(size)||50; tsApprovalPage=1; loadTimesheetApprovals(); }
function timesheetApprovalPagePrev() { if(tsApprovalPage>1){ tsApprovalPage--; loadTimesheetApprovals(); } }
function timesheetApprovalPageNext() {
  const totalPages=Math.max(1, Math.ceil(tsApprovalTotal/tsApprovalPageSize));
  if(tsApprovalPage<totalPages){ tsApprovalPage++; loadTimesheetApprovals(); }
}

function renderTimesheetApprovalTable() {
  const tbody=document.getElementById('timesheetApprovalTableBody');
  const emptyEl=document.getElementById('timesheetApprovalEmpty');
  const pagination=document.getElementById('timesheetApprovalPagination');
  document.querySelectorAll('.ts-appr-sort-arrow').forEach(el=>{
    const key=el.dataset.sortKey;
    el.textContent = key===tsApprovalSortKey ? (tsApprovalSortDir==='asc'?' ▲':' ▼') : '';
  });

  if(!tsApprovalRowsCache.length){ tbody.innerHTML=''; emptyEl?.classList.remove('hidden'); pagination?.classList.add('hidden'); return; }
  emptyEl?.classList.add('hidden');
  pagination?.classList.remove('hidden');
  const pageSizeEl=document.getElementById('timesheetApprovalPageSize');
  if(pageSizeEl) pageSizeEl.value=String(tsApprovalPageSize);

  const offset=(tsApprovalPage-1)*tsApprovalPageSize;
  const pageInfoEl=document.getElementById('timesheetApprovalPageInfo');
  if(pageInfoEl) pageInfoEl.textContent=`${offset+1}-${Math.min(offset+tsApprovalPageSize, tsApprovalTotal)} of ${tsApprovalTotal}`;

  tbody.innerHTML=tsApprovalRowsCache.map(t=>`
    <tr class="cursor-pointer hover:bg-slate-50 transition" onclick="openTimesheetDetail(${t.id})">
      <td class="px-4 py-3">
        <p class="font-medium">${esc(displayName(t.employee_name,t.employee_preferred_name))}</p>
        <p class="text-xs text-slate-500">${esc(t.department||'')}${t.designation?' · '+esc(t.designation):''}</p>
      </td>
      <td class="px-4 py-3 text-slate-600">
        ${fmtDate(t.period_start)} → ${fmtDate(t.period_end)}
        ${t.status==='Submitted' && !t.is_actionable ? `<p class="text-xs text-slate-400 mt-0.5">Pending with: ${esc(t.pending_with||'—')}</p>` : ''}
      </td>
      <td class="px-4 py-3 text-right text-slate-600">${t.total_hours} hrs</td>
      <td class="px-4 py-3"><span class="badge ${statusColor(TS_STATUS_COLORS, t.status)} text-xs">${t.status}</span></td>
    </tr>`).join('');
}

function setTimesheetApprovalFilter(status) {
  tsApprovalFilter=status;
  tsApprovalPage=1;
  document.querySelectorAll('.ts-appr-filter-btn').forEach(b=>b.classList.remove('ts-appr-filter-active'));
  event?.target?.classList?.add('ts-appr-filter-active');
  loadTimesheetApprovals();
}

async function openTimesheetDetail(tsId) {
  const res=await api(`/api/timesheets/${tsId}`);
  if(!res?.ok) return;
  const ts=await res.json();
  document.getElementById('timesheetDetailTitle').textContent=`Timesheet — ${fmtDate(ts.period_start)} to ${fmtDate(ts.period_end)}`;
  document.getElementById('timesheetDetailMeta').textContent=`Status: ${ts.status}${ts.submitted_at?' · Submitted '+fmtDate(ts.submitted_at):''}`;
  document.getElementById('timesheetDetailBody').innerHTML=ts.entries.map(e=>`
    <tr class="border-t border-slate-100">
      <td class="py-2">${fmtDate(e.date)}</td><td class="py-2">${esc(e.project_name)}</td>
      <td class="py-2">${esc(e.task_name||'—')}</td>
      <td class="py-2">${e.hours}</td><td class="py-2 text-slate-500">${esc(e.description||'')}</td>
    </tr>`).join('');
  document.getElementById('timesheetDetailTotal').textContent=`Total: ${ts.total_hours} hours`;
  const actions=document.getElementById('timesheetDetailActions');
  const cached=tsApprovalRowsCache.find(r=>r.id===ts.id);
  actions.innerHTML=ts.status!=='Submitted'?'':(!cached||cached.is_actionable)?`
    <button onclick="reviewTimesheet(${ts.id},'Approved')" class="btn-primary text-sm">Approve</button>
    <button onclick="reviewTimesheet(${ts.id},'Rejected')" class="btn-ghost text-sm text-red-600">Reject</button>
  `:`<p class="text-xs text-slate-400">Pending with: ${esc(cached.pending_with||'—')}</p>`;
  await loadTimesheetDetailOvertime(tsId);
  document.getElementById('timesheetDetailModal').classList.remove('hidden');
}

const OT_STATUS_COLORS={'Pending':'status-pending','Approved':'status-positive','Rejected':'status-negative'};

async function loadTimesheetDetailOvertime(tsId) {
  const wrap=document.getElementById('timesheetDetailOvertimeWrap');
  const list=document.getElementById('timesheetDetailOvertimeList');
  const res=await api(`/api/timesheets/${tsId}/overtime`);
  const records=res?.ok?await res.json():[];
  if(!records.length){ wrap.classList.add('hidden'); list.innerHTML=''; return; }
  wrap.classList.remove('hidden');
  list.innerHTML=records.map(o=>`
    <div class="flex items-center gap-3 bg-slate-50 rounded-lg px-3 py-2">
      <span class="text-sm text-slate-700 shrink-0">${fmtDate(o.work_date)}</span>
      <span class="text-xs text-slate-500 shrink-0">${o.logged_hours}h logged, ${o.threshold_hours}h normal</span>
      <span class="text-sm font-medium text-amber-700 shrink-0">+${o.overtime_hours}h OT</span>
      <span class="badge ${statusColor(OT_STATUS_COLORS, o.status)} text-xs shrink-0">${o.status}</span>
      <span class="flex-1"></span>
      ${o.status==='Pending'?`
        <button onclick="reviewOvertime(${o.id},${tsId},'Approved')" class="btn-primary text-xs px-2 py-1">Approve</button>
        <button onclick="reviewOvertime(${o.id},${tsId},'Rejected')" class="btn-ghost text-xs px-2 py-1 text-red-600">Reject</button>
      `:''}
    </div>`).join('');
}

async function reviewOvertime(recordId, tsId, status) {
  const res=await api(`/api/overtime/${recordId}/status`,{method:'PATCH',body:JSON.stringify({status})});
  if(res?.ok){ loadTimesheetDetailOvertime(tsId); }
  else { const d=await res.json(); alert(d.detail||'Failed to update overtime record'); }
}

